INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-1-u3-C1','math',2,1,'u3',2,'(두 자리 수)+(한 자리 수) — 모으는 상황을 덧셈으로 나타내고, 일의 자리 합이 10을 넘으면 10을 먼저 만들거나(가르기) 십의 자리로 받아올려 계산하기',ARRAY['2수01-06']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-1-u3-C2','math',2,1,'u3',3,'(두 자리 수)+(두 자리 수) — 십의 자리끼리·일의 자리끼리 나누어 더하거나 몇십을 만들어 더하고, 일의 자리 합의 10을 십의 자리 1로 받아올리기',ARRAY['2수01-06']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-1-u3-C3','math',2,1,'u3',4,'덧셈 세로셈 — 자리를 맞추어 쓰고 일의 자리부터 계산하며, 받아올림한 1을 윗자리에 더하고 십의 자리 합이 10을 넘으면 백의 자리로 올리기',ARRAY['2수01-06']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-1-u3-C4','math',2,1,'u3',5,'(두 자리 수)−(한 자리 수) — 일의 자리끼리 뺄 수 없을 때 먼저 몇십을 만들거나(가르기) 십의 자리에서 10을 받아내려 계산하기',ARRAY['2수01-06']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-1-u3-C5','math',2,1,'u3',6,'(두 자리 수)−(두 자리 수)·(몇십)−(몇십몇) — 받아내림 세로셈으로 계산하고 십의 자리를 1 줄이며, 뺄셈의 답에 뺀 수를 더해 확인하기',ARRAY['2수01-06']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-1-u3-C6','math',2,1,'u3',8,'세 수의 계산 — 덧셈과 뺄셈이 섞여 있어도 앞에서부터 차례로 두 수씩 계산하기',ARRAY['2수01-08']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-1-u3-C7','math',2,1,'u3',9,'덧셈과 뺄셈의 관계 — 전체와 두 부분으로 덧셈식 하나를 뺄셈식 둘로, 뺄셈식을 덧셈식으로 나타내기',ARRAY['2수01-07']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-1-u3-C8','math',2,1,'u3',9,'□가 사용된 식 — 모르는 수를 □로 하여 식을 만들고, 전체와 부분의 관계(덧셈과 뺄셈의 관계)로 □의 값 구하기',ARRAY['2수01-09']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u3-X01','math',2,'u3',ARRAY['M2-1-u3-C1','M2-1-u3-C2','M2-1-u3-C3']::text[],'받아올림한 1을 십의 자리에서 더하지 않는다 — 28+19를 37, 58+46을 94','일의 자리 합이 10을 넘으면 십의 자리 위에 작은 1을 먼저 쓰고, 십의 자리를 더할 때 손가락으로 1을 짚기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u3-X02','math',2,'u3',ARRAY['M2-1-u3-C2','M2-1-u3-C3']::text[],'자리별 합을 그대로 이어 쓴다 — 8+9=17을 붙여 28+19를 317·3017, 17+6을 113','한 칸에는 숫자 하나 — 17은 1(십)과 7(일)로 나누어 7만 쓰고 1은 올린다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u3-X03','math',2,'u3',ARRAY['M2-1-u3-C1','M2-1-u3-C3']::text[],'자리를 맞추지 않는다 — 한 자리 수를 십의 자리에 맞춰 17+6을 77처럼','세로셈에서 일의 자리끼리 오른쪽 끝을 맞추어 쓰기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u3-X04','math',2,'u3',ARRAY['M2-1-u3-C1','M2-1-u3-C2']::text[],'10을 만들 때 가르기를 잘못한다 — 몇을 더해야 몇십이 되는지 틀리거나, 가른 뒤 남은 수 대신 처음 수를 다시 더함','「몇십까지 몇이 모자라지?」를 먼저 말하고, 가른 두 수를 모으면 처음 수가 되는지 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u3-X05','math',2,'u3',ARRAY['M2-1-u3-C3']::text[],'십의 자리 합이 10을 넘을 때 백의 자리로 올리지 않는다 — 62+53을 15·75+74를 49','십의 자리 합 11은 「10이 11개」 — 100이 1개와 10이 1개로 바꿔 백의 자리를 만든다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u3-X06','math',2,'u3',ARRAY['M2-1-u3-C1','M2-1-u3-C3']::text[],'받아올림을 10으로 더하거나 두 번 더한다 — 십의 자리 식을 4 + 2 + 10으로, 답이 10 커짐','받아올린 10은 십의 자리에서 「1」이다 — 십 모형 하나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u3-X07','math',2,'u3',ARRAY['M2-1-u3-C4','M2-1-u3-C5']::text[],'일의 자리에서 큰 수에서 작은 수를 거꾸로 뺀다 — 23−5를 22, 42−19를 37','「위의 수에서 아래 수」 — 위의 수가 작으면 빼지 말고 십의 자리에서 10을 받아내리기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u3-X08','math',2,'u3',ARRAY['M2-1-u3-C4','M2-1-u3-C5']::text[],'받아내림을 하고 십의 자리를 1 줄이지 않는다 — 42−19를 33','십 모형 하나를 풀었으면 십의 자리 숫자 위에 줄을 긋고 1 작은 수를 써 두기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u3-X09','math',2,'u3',ARRAY['M2-1-u3-C4','M2-1-u3-C5']::text[],'받아내린 10을 1처럼 더하거나 뺄셈 가르기를 잘못한다 — 23의 십을 풀어 일의 자리를 4로, 23−5에서 5를 3과 5로','십 모형 1개를 일 모형 10개로 바꾸는 장면 — 일의 자리는 3이 아니라 13') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u3-X10','math',2,'u3',ARRAY['M2-1-u3-C1','M2-1-u3-C5','M2-1-u3-C7']::text[],'덧셈 상황과 뺄셈 상황을 헷갈려 반대 계산을 한다 — 「남은·몇 개 더 많이」를 더하고 「모두」를 뺌','물음의 「모두·남은·더 많이」에 동그라미 — 모으면 덧셈, 덜거나 견주면 뺄셈') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u3-X11','math',2,'u3',ARRAY['M2-1-u3-C6']::text[],'세 수의 계산을 앞에서부터 하지 않는다 — 42−15+27에서 15+27을 먼저 해 0','①②를 식 아래에 써 놓고 왼쪽 두 수부터 차례로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u3-X12','math',2,'u3',ARRAY['M2-1-u3-C6']::text[],'세 수의 계산에서 한 번만 계산하고 멈추거나 부호를 무시하고 모두 더한다','식에 있는 기호 두 개에 차례로 동그라미 — 두 번 계산해야 끝') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u3-X13','math',2,'u3',ARRAY['M2-1-u3-C7']::text[],'전체와 부분을 가리지 않고 부분끼리 빼거나 덧셈식과 뺄셈식을 헷갈린다 — 8+5=13을 8−5=13으로','막대 그림에 전체(긴 막대)와 부분(짧은 막대 둘)을 먼저 표시하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u3-X14','math',2,'u3',ARRAY['M2-1-u3-C7','M2-1-u3-C8']::text[],'전체와 부분의 자리를 바꾸어 식을 쓴다 — 부분에서 전체를 빼거나, 덧셈식에서 전체를 더함','뺄셈식은 「전체 − 부분 = 부분」, 덧셈식은 「부분 + 부분 = 전체」 틀에 넣어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u3-X15','math',2,'u3',ARRAY['M2-1-u3-C8']::text[],'□가 있는 식에서 보이는 두 수를 그대로 더하거나 빼 관계를 거꾸로 쓴다 — 5+□=9에서 □를 14, □−7=8에서 □를 1','□ 자리에 답을 넣어 식이 맞는지 소리 내어 읽어 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u3-X16','math',2,'u3',ARRAY['M2-1-u3-C5','M2-1-u3-C6','M2-1-u3-C8']::text[],'묻는 말이나 조건을 놓친다 — 확인하는 식에 처음 수를 더하거나, 가장 큰↔가장 작은·바르게 계산한 값 대신 중간 값을 답함','물음에 밑줄 — 마지막에 구한 수가 물음에 맞는 답인지 다시 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L02_basic#1','math',2,1,'u3','L02','g2_1_math_u3_L02_basic','lesson_basic','M2-1-u3-C1',1,'mc','auto','곰이가 물고기 13마리를 잡았는데 5마리를 더 잡았어요. 모두 몇 마리인지 구하는 식은 어느 것인가요?',ARRAY['M2-1-u3-X10']::text[],true,'{"seq":1,"concept":"M2-1-u3-C1","difficulty":1,"kind":"mc","stem":"곰이가 물고기 13마리를 잡았는데 5마리를 더 잡았어요. 모두 몇 마리인지 구하는 식은 어느 것인가요?","options":[{"t":"13 + 5","correct":true},{"t":"13 − 5","mis":"M2-1-u3-X10"},{"t":"5 − 3","mis":"M2-1-u3-X10"}],"explanation":["「더 잡았어요」, 「모두」는 두 묶음을 모으는 이야기예요.","모으면 덧셈 — 13 + 5 = 18이에요.","덜어 내는 이야기가 아니라서 뺄셈이 아니에요."],"variant_rule":{"alt":[{"stem":"펭귄 16마리 가운데 4마리가 떠났어요. 남은 펭귄의 수를 구하는 식은 어느 것인가요?","options":[{"t":"16 − 4","correct":true},{"t":"16 + 4","mis":"M2-1-u3-X10"},{"t":"4 − 1","mis":"M2-1-u3-X10"}],"explanation":["「떠났어요」, 「남은」은 덜어 내는 이야기예요.","덜어 내면 뺄셈 — 16 − 4 = 12예요.","모으는 이야기가 아니라서 덧셈이 아니에요."]},{"stem":"색종이 24장에 13장을 더 받았어요. 색종이는 모두 몇 장인지 구하는 식은 어느 것인가요?","options":[{"t":"24 + 13","correct":true},{"t":"24 − 13","mis":"M2-1-u3-X10"},{"t":"13 − 4","mis":"M2-1-u3-X10"}],"explanation":["「더 받았어요」, 「모두」는 모으는 이야기예요.","모으면 덧셈 — 24 + 13 = 37이에요.","덜어 내는 이야기가 아니라서 뺄셈이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L02_basic#2','math',2,1,'u3','L02','g2_1_math_u3_L02_basic','lesson_basic','M2-1-u3-C1',1,'mc','auto','17 + 6은 얼마인가요?',ARRAY['M2-1-u3-X01','M2-1-u3-X03']::text[],true,'{"seq":2,"concept":"M2-1-u3-C1","difficulty":1,"kind":"mc","stem":"17 + 6은 얼마인가요?","explanation":["일의 자리 7 + 6 = 13 — 3을 쓰고 10은 십의 자리로 받아올려요.","십의 자리 1 + 1 = 2. 그래서 17 + 6 = 23이에요.","받아올림한 1은 십의 자리에서 꼭 더해요 — 빠뜨리면 10이 작아져요."],"variant_rule":{"ar2":{"ask":"value","kind":"a21"}},"options":[{"t":"23","correct":true},{"t":"13","mis":"M2-1-u3-X01"},{"t":"77","mis":"M2-1-u3-X03"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L02_basic#3','math',2,1,'u3','L02','g2_1_math_u3_L02_basic','lesson_basic','M2-1-u3-C1',1,'mc','auto','18 + 5를 계산할 때, 18에 얼마를 더하면 20이 되나요?',ARRAY['M2-1-u3-X04']::text[],true,'{"seq":3,"concept":"M2-1-u3-C1","difficulty":1,"kind":"mc","stem":"18 + 5를 계산할 때, 18에 얼마를 더하면 20이 되나요?","explanation":["18에서 20까지는 2만큼 더 가야 해요.","18 + 2 = 20 — 먼저 몇십을 만들어요.","남은 3을 더하면 20 + 3 = 23이에요."],"variant_rule":{"ar2":{"ask":"fill","kind":"a21"}},"options":[{"t":"2","correct":true},{"t":"3","mis":"M2-1-u3-X04"},{"t":"8","mis":"M2-1-u3-X04"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L02_basic#4','math',2,1,'u3','L02','g2_1_math_u3_L02_basic','lesson_basic','M2-1-u3-C1',1,'sa','auto','하루가 도토리 25개를 가지고 있었는데 7개를 더 받았어요. 도토리는 모두 몇 개인가요?','{}'::text[],true,'{"seq":4,"concept":"M2-1-u3-C1","difficulty":1,"kind":"sa","stem":"하루가 도토리 25개를 가지고 있었는데 7개를 더 받았어요. 도토리는 모두 몇 개인가요?","explanation":["일의 자리 5 + 7 = 12 — 2를 쓰고 10은 십의 자리로 받아올려요.","십의 자리 2 + 1 = 3. 그래서 25 + 7 = 32예요.","「모두」는 모으는 이야기라 덧셈이에요 — 32개예요."],"variant_rule":{"ar2":{"ask":"story","kind":"a21"}},"answer":["32","32개"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L02_basic#5','math',2,1,'u3','L02','g2_1_math_u3_L02_basic','lesson_basic','M2-1-u3-C1',2,'mc','auto','38 + 5를 계산하려고 5를 2와 □로 갈랐어요. □에 알맞은 수는 얼마인가요?',ARRAY['M2-1-u3-X04']::text[],true,'{"seq":5,"concept":"M2-1-u3-C1","difficulty":2,"kind":"mc","stem":"38 + 5를 계산하려고 5를 2와 □로 갈랐어요. □에 알맞은 수는 얼마인가요?","explanation":["38에 2를 더하면 40이 돼요.","5는 2와 3 — □는 3이에요.","40 + 3 = 43, 그래서 38 + 5 = 43이에요."],"variant_rule":{"ar2":{"ask":"split","kind":"a21"}},"options":[{"t":"3","correct":true},{"t":"2","mis":"M2-1-u3-X04"},{"t":"8","mis":"M2-1-u3-X04"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L02_basic#6','math',2,1,'u3','L02','g2_1_math_u3_L02_basic','lesson_basic','M2-1-u3-C1',2,'sa','auto','46 + 9는 얼마인가요?','{}'::text[],true,'{"seq":6,"concept":"M2-1-u3-C1","difficulty":2,"kind":"sa","stem":"46 + 9는 얼마인가요?","explanation":["일의 자리 6 + 9 = 15 — 5를 쓰고 10은 십의 자리로 받아올려요.","십의 자리 4 + 1 = 5. 그래서 46 + 9 = 55예요.","받아올림한 1은 십의 자리에서 꼭 더해요 — 빠뜨리면 10이 작아져요."],"variant_rule":{"ar2":{"ask":"value","kind":"a21"}},"answer":["55"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L02_basic#7','math',2,1,'u3','L02','g2_1_math_u3_L02_basic','lesson_basic','M2-1-u3-C1',2,'ox','auto','27 + 8 = 25 입니다.',ARRAY['M2-1-u3-X01']::text[],true,'{"seq":7,"concept":"M2-1-u3-C1","difficulty":2,"kind":"ox","stem":"27 + 8 = 25 입니다.","explanation":["일의 자리 7 + 8 = 15 — 5를 쓰고 10은 십의 자리로 받아올려요.","십의 자리 2 + 1 = 3. 그래서 27 + 8 = 35예요.","받아올림한 1은 십의 자리에서 꼭 더해요 — 빠뜨리면 10이 작아져요."],"variant_rule":{"ar2":{"ask":"value","kind":"a21"}},"answer":"X","mis":"M2-1-u3-X01","reason_options":[{"t":"바르게 계산하면 35가 되니까","correct":true},{"t":"일의 자리끼리, 십의 자리끼리 더하기만 하면 되니까","mis":"M2-1-u3-X01"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L02_basic#8','math',2,1,'u3','L02','g2_1_math_u3_L02_basic','lesson_basic','M2-1-u3-C1',2,'mc','auto','17 + 6을 계산할 때 6을 3과 3으로 가르는 까닭은 무엇인가요?',ARRAY['M2-1-u3-X04']::text[],true,'{"seq":8,"concept":"M2-1-u3-C1","difficulty":2,"kind":"mc","stem":"17 + 6을 계산할 때 6을 3과 3으로 가르는 까닭은 무엇인가요?","options":[{"t":"17에 3을 더하면 20이 되어 계산하기 쉬워서","correct":true},{"t":"6은 3과 3으로만 가를 수 있어서","mis":"M2-1-u3-X04"},{"t":"17의 일의 자리 7과 같아지게 하려고","mis":"M2-1-u3-X04"}],"explanation":["17은 3만 더하면 20이 돼요.","그래서 6을 3과 3으로 갈라 17 + 3 = 20, 20 + 3 = 23으로 계산해요.","6은 1과 5, 2와 4로도 가를 수 있지만 20을 만들려면 3이 필요해요."],"variant_rule":{"alt":[{"stem":"28 + 5를 계산할 때 5를 2와 3으로 가르는 까닭은 무엇인가요?","options":[{"t":"28에 2를 더하면 30이 되어 계산하기 쉬워서","correct":true},{"t":"5는 2와 3으로만 가를 수 있어서","mis":"M2-1-u3-X04"},{"t":"28의 십의 자리 2와 같아지게 하려고","mis":"M2-1-u3-X04"}],"explanation":["28은 2만 더하면 30이 돼요.","그래서 5를 2와 3으로 갈라 28 + 2 = 30, 30 + 3 = 33으로 계산해요.","몇십을 먼저 만들면 더하기 쉬워요."]},{"stem":"36 + 7을 계산할 때 7을 4와 3으로 가르는 까닭은 무엇인가요?","options":[{"t":"36에 4를 더하면 40이 되어 계산하기 쉬워서","correct":true},{"t":"7은 4와 3으로만 가를 수 있어서","mis":"M2-1-u3-X04"},{"t":"36의 일의 자리 6보다 작게 하려고","mis":"M2-1-u3-X04"}],"explanation":["36은 4만 더하면 40이 돼요.","그래서 7을 4와 3으로 갈라 36 + 4 = 40, 40 + 3 = 43으로 계산해요.","몇십을 먼저 만들면 더하기 쉬워요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L02_basic#9','math',2,1,'u3','L02','g2_1_math_u3_L02_basic','lesson_basic','M2-1-u3-C1',2,'error','auto','친구들이 덧셈을 했어요. 잘못 계산한 친구는 누구인가요?',ARRAY['M2-1-u3-X02','M2-1-u3-X01']::text[],true,'{"seq":9,"concept":"M2-1-u3-C1","difficulty":2,"kind":"error","stem":"친구들이 덧셈을 했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"하린: 17 + 6 = 113","correct":true,"mis_target":"M2-1-u3-X02"},{"t":"도윤: 25 + 7 = 32","mis":"M2-1-u3-X01"},{"t":"서아: 38 + 5 = 43","mis":"M2-1-u3-X01"}],"explanation":["17 + 6에서 일의 자리 7 + 6 = 13이에요.","13의 10은 십의 자리로 올려 1 + 1 = 2 — 17 + 6 = 23이에요.","하린이는 13을 그대로 이어 붙여 113이라고 썼어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 친구들이 덧셈을 했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"민준: 28 + 4 = 22","correct":true,"mis_target":"M2-1-u3-X01"},{"t":"지우: 46 + 8 = 54","mis":"M2-1-u3-X01"},{"t":"하루: 19 + 3 = 22","mis":"M2-1-u3-X01"}],"explanation":["28 + 4에서 일의 자리 8 + 4 = 12예요.","10을 십의 자리로 올려 2 + 1 = 3 — 28 + 4 = 32예요.","민준이는 받아올림한 1을 더하지 않았어요."]},{"stem":"이번에는 다른 보기예요. 친구들이 덧셈을 했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"은우: 45 + 8 = 125","correct":true,"mis_target":"M2-1-u3-X03"},{"t":"다예: 57 + 6 = 63","mis":"M2-1-u3-X01"},{"t":"서아: 29 + 9 = 38","mis":"M2-1-u3-X01"}],"explanation":["8은 일의 자리 수라서 45의 5와 줄을 맞춰야 해요.","45 + 8 = 53이에요.","은우는 8을 십의 자리에 맞춰 45 + 80처럼 계산했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L02_basic#10','math',2,1,'u3','L02','g2_1_math_u3_L02_basic','lesson_basic','M2-1-u3-C1',3,'mc','auto','26 + □에서 받아올림이 생기려면 □ 안에 들어갈 수 있는 가장 작은 한 자리 수는 무엇인가요?',ARRAY['M2-1-u3-X04','M2-1-u3-X16']::text[],true,'{"seq":10,"concept":"M2-1-u3-C1","difficulty":3,"kind":"mc","stem":"26 + □에서 받아올림이 생기려면 □ 안에 들어갈 수 있는 가장 작은 한 자리 수는 무엇인가요?","options":[{"t":"4","correct":true},{"t":"3","mis":"M2-1-u3-X04"},{"t":"9","mis":"M2-1-u3-X16"}],"explanation":["일의 자리 6 + □가 10이거나 10보다 커야 받아올림이 생겨요.","6 + 4 = 10이니 가장 작은 수는 4예요.","9도 받아올림이 생기지만 「가장 작은」 수를 물었어요."],"variant_rule":{"alt":[{"stem":"38 + □에서 받아올림이 생기려면 □ 안에 들어갈 수 있는 가장 작은 한 자리 수는 무엇인가요?","options":[{"t":"2","correct":true},{"t":"1","mis":"M2-1-u3-X04"},{"t":"9","mis":"M2-1-u3-X16"}],"explanation":["일의 자리 8 + □가 10이거나 10보다 커야 해요.","8 + 2 = 10이니 가장 작은 수는 2예요.","「가장 작은」 수를 물었으니 9가 아니에요."]},{"stem":"45 + □에서 받아올림이 생기려면 □ 안에 들어갈 수 있는 가장 작은 한 자리 수는 무엇인가요?","options":[{"t":"5","correct":true},{"t":"4","mis":"M2-1-u3-X04"},{"t":"9","mis":"M2-1-u3-X16"}],"explanation":["일의 자리 5 + □가 10이거나 10보다 커야 해요.","5 + 5 = 10이니 가장 작은 수는 5예요.","「가장 작은」 수를 물었으니 9가 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L02_challenge#1','math',2,1,'u3','L02','g2_1_math_u3_L02_challenge','lesson_challenge','M2-1-u3-C1',2,'sa','auto','69 + 8은 얼마인가요?','{}'::text[],true,'{"seq":1,"concept":"M2-1-u3-C1","difficulty":2,"kind":"sa","stem":"69 + 8은 얼마인가요?","explanation":["일의 자리 9 + 8 = 17 — 7을 쓰고 10은 십의 자리로 받아올려요.","십의 자리 6 + 1 = 7. 그래서 69 + 8 = 77이에요.","받아올림한 1은 십의 자리에서 꼭 더해요 — 빠뜨리면 10이 작아져요."],"variant_rule":{"ar2":{"ask":"value","kind":"a21"}},"answer":["77"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L02_challenge#2','math',2,1,'u3','L02','g2_1_math_u3_L02_challenge','lesson_challenge','M2-1-u3-C1',2,'mc','auto','27 + 9를 계산하려고 9를 3과 □로 갈랐어요. □에 알맞은 수는 얼마인가요?',ARRAY['M2-1-u3-X04']::text[],true,'{"seq":2,"concept":"M2-1-u3-C1","difficulty":2,"kind":"mc","stem":"27 + 9를 계산하려고 9를 3과 □로 갈랐어요. □에 알맞은 수는 얼마인가요?","explanation":["27에 3을 더하면 30이 돼요.","9는 3과 6 — □는 6이에요.","30 + 6 = 36, 그래서 27 + 9 = 36이에요."],"variant_rule":{"ar2":{"ask":"split","kind":"a21"}},"options":[{"t":"6","correct":true},{"t":"3","mis":"M2-1-u3-X04"},{"t":"7","mis":"M2-1-u3-X04"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L02_challenge#3','math',2,1,'u3','L02','g2_1_math_u3_L02_challenge','lesson_challenge','M2-1-u3-C1',3,'mc','auto','다예가 도토리 58개를 가지고 있었는데 6개를 더 받았어요. 도토리는 모두 몇 개인가요?',ARRAY['M2-1-u3-X01','M2-1-u3-X03','M2-1-u3-X02']::text[],true,'{"seq":3,"concept":"M2-1-u3-C1","difficulty":3,"kind":"mc","stem":"다예가 도토리 58개를 가지고 있었는데 6개를 더 받았어요. 도토리는 모두 몇 개인가요?","explanation":["일의 자리 8 + 6 = 14 — 4를 쓰고 10은 십의 자리로 받아올려요.","십의 자리 5 + 1 = 6. 그래서 58 + 6 = 64예요.","「모두」는 모으는 이야기라 덧셈이에요 — 64개예요."],"variant_rule":{"ar2":{"ask":"story","kind":"a21"}},"options":[{"t":"64","correct":true},{"t":"54","mis":"M2-1-u3-X01"},{"t":"118","mis":"M2-1-u3-X03"},{"t":"514","mis":"M2-1-u3-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L02_challenge#4','math',2,1,'u3','L02','g2_1_math_u3_L02_challenge','lesson_challenge','M2-1-u3-C1',3,'mc','auto','28 + 5를 10을 만들어 계산한 식으로 바른 것은 어느 것인가요?',ARRAY['M2-1-u3-X04','M2-1-u3-X06']::text[],true,'{"seq":4,"concept":"M2-1-u3-C1","difficulty":3,"kind":"mc","stem":"28 + 5를 10을 만들어 계산한 식으로 바른 것은 어느 것인가요?","options":[{"t":"28 + 2 + 3","correct":true},{"t":"28 + 2 + 5","mis":"M2-1-u3-X04"},{"t":"28 + 5 + 10","mis":"M2-1-u3-X06"}],"explanation":["28은 2를 더하면 30이 돼요.","5를 2와 3으로 갈라 28 + 2 + 3 = 33이에요.","가른 뒤에는 남은 3만 더해요 — 5를 다시 더하지 않아요."],"variant_rule":{"alt":[{"stem":"17 + 6을 10을 만들어 계산한 식으로 바른 것은 어느 것인가요?","options":[{"t":"17 + 3 + 3","correct":true},{"t":"17 + 3 + 6","mis":"M2-1-u3-X04"},{"t":"17 + 6 + 10","mis":"M2-1-u3-X06"}],"explanation":["17은 3을 더하면 20이 돼요.","6을 3과 3으로 갈라 17 + 3 + 3 = 23이에요.","가른 뒤에는 남은 3만 더해요."]},{"stem":"46 + 7을 10을 만들어 계산한 식으로 바른 것은 어느 것인가요?","options":[{"t":"46 + 4 + 3","correct":true},{"t":"46 + 4 + 7","mis":"M2-1-u3-X04"},{"t":"46 + 7 + 10","mis":"M2-1-u3-X06"}],"explanation":["46은 4를 더하면 50이 돼요.","7을 4와 3으로 갈라 46 + 4 + 3 = 53이에요.","가른 뒤에는 남은 3만 더해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L02_challenge#5','math',2,1,'u3','L02','g2_1_math_u3_L02_challenge','lesson_challenge','M2-1-u3-C1',3,'ox','auto','35 + 8 = 43 입니다.',ARRAY['M2-1-u3-X01']::text[],true,'{"seq":5,"concept":"M2-1-u3-C1","difficulty":3,"kind":"ox","stem":"35 + 8 = 43 입니다.","explanation":["일의 자리 5 + 8 = 13 — 3을 쓰고 10은 십의 자리로 받아올려요.","십의 자리 3 + 1 = 4. 그래서 35 + 8 = 43이에요.","받아올림한 1은 십의 자리에서 꼭 더해요 — 빠뜨리면 10이 작아져요."],"variant_rule":{"ar2":{"ask":"value","kind":"a21"}},"answer":"O","mis":"M2-1-u3-X01","reason_options":[{"t":"받아올림한 1을 십의 자리에 더해 계산했으니까","correct":true},{"t":"일의 자리끼리, 십의 자리끼리 더하기만 하면 되니까","mis":"M2-1-u3-X01"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L02_challenge#6','math',2,1,'u3','L02','g2_1_math_u3_L02_challenge','lesson_challenge','M2-1-u3-C1',3,'sa','auto','구슬이 29개 있어요. 6개를 더 넣으면 구슬은 30개보다 몇 개 많아지나요?','{}'::text[],true,'{"seq":6,"concept":"M2-1-u3-C1","difficulty":3,"kind":"sa","stem":"구슬이 29개 있어요. 6개를 더 넣으면 구슬은 30개보다 몇 개 많아지나요?","answer":["5","5개"],"explanation":["29 + 6 = 35예요.","35는 30보다 5 많아요.","29에 1을 더하면 30 — 남은 5가 30보다 많은 만큼이에요."],"variant_rule":{"alt":[{"stem":"사탕이 48개 있어요. 5개를 더 받으면 사탕은 50개보다 몇 개 많아지나요?","answer":["3","3개"],"explanation":["48 + 5 = 53이에요.","53은 50보다 3 많아요.","48에 2를 더하면 50 — 남은 3이 50보다 많은 만큼이에요."]},{"stem":"딱지가 37장 있어요. 8장을 더 접으면 딱지는 40장보다 몇 장 많아지나요?","answer":["5","5장"],"explanation":["37 + 8 = 45예요.","45는 40보다 5 많아요.","37에 3을 더하면 40 — 남은 5가 40보다 많은 만큼이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L02_challenge#7','math',2,1,'u3','L02','g2_1_math_u3_L02_challenge','lesson_challenge','M2-1-u3-C1',3,'sa','auto','펭이가 도토리 47개를 가지고 있었는데 8개를 더 받았어요. 도토리는 모두 몇 개인가요?','{}'::text[],true,'{"seq":7,"concept":"M2-1-u3-C1","difficulty":3,"kind":"sa","stem":"펭이가 도토리 47개를 가지고 있었는데 8개를 더 받았어요. 도토리는 모두 몇 개인가요?","explanation":["일의 자리 7 + 8 = 15 — 5를 쓰고 10은 십의 자리로 받아올려요.","십의 자리 4 + 1 = 5. 그래서 47 + 8 = 55예요.","「모두」는 모으는 이야기라 덧셈이에요 — 55개예요."],"variant_rule":{"ar2":{"ask":"story","kind":"a21"}},"answer":["55","55개"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L02_challenge#8','math',2,1,'u3','L02','g2_1_math_u3_L02_challenge','lesson_challenge','M2-1-u3-C1',4,'mc','auto','계산 결과가 가장 큰 것은 어느 것인가요?',ARRAY['M2-1-u3-X01']::text[],true,'{"seq":8,"concept":"M2-1-u3-C1","difficulty":4,"kind":"mc","stem":"계산 결과가 가장 큰 것은 어느 것인가요?","options":[{"t":"47 + 9","correct":true},{"t":"46 + 8","mis":"M2-1-u3-X01"},{"t":"49 + 4","mis":"M2-1-u3-X01"}],"explanation":["46 + 8 = 54, 49 + 4 = 53, 47 + 9 = 56이에요.","가장 큰 것은 47 + 9 = 56이에요.","받아올림한 1을 빠뜨리면 셋 다 10씩 작아져요 — 하나하나 바르게 계산해요."],"variant_rule":{"alt":[{"stem":"계산 결과가 가장 작은 것은 어느 것인가요?","options":[{"t":"28 + 5","correct":true},{"t":"25 + 9","mis":"M2-1-u3-X01"},{"t":"26 + 9","mis":"M2-1-u3-X16"}],"explanation":["28 + 5 = 33, 25 + 9 = 34, 26 + 9 = 35예요.","가장 작은 것은 28 + 5 = 33이에요.","「가장 작은」 것을 물었어요."]},{"stem":"계산 결과가 30보다 큰 것은 어느 것인가요?","options":[{"t":"24 + 8","correct":true},{"t":"22 + 7","mis":"M2-1-u3-X16"},{"t":"23 + 6","mis":"M2-1-u3-X16"}],"explanation":["24 + 8 = 32, 22 + 7 = 29, 23 + 6 = 29예요.","30보다 큰 것은 24 + 8이에요.","일의 자리 합이 10을 넘는 것은 24 + 8뿐이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L02_challenge#9','math',2,1,'u3','L02','g2_1_math_u3_L02_challenge','lesson_challenge','M2-1-u3-C1',4,'essay','teacher','36 + 7을 두 가지 방법으로 계산하고, 각 방법을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-1-u3-C1","difficulty":4,"kind":"essay","stem":"36 + 7을 두 가지 방법으로 계산하고, 각 방법을 설명해 보세요.","answer_guide":{"answer":"① 36에 4를 더해 40을 만들고 남은 3을 더해 43. ② 36을 30과 6으로 가르고 6 + 7 = 13, 30 + 13 = 43. (7을 4와 3으로 갈라 계산해도 좋다.)","scoring_points":["서로 다른 방법 두 가지를 썼는가","두 방법 모두 답이 43인가","10(몇십)을 만들거나 자리를 나누는 까닭을 말로 썼는가"]},"explanation":["36은 4를 더하면 40이 돼요.","7을 4와 3으로 갈라 40 + 3 = 43이에요.","36을 30과 6으로 나누어 6 + 7 = 13, 30 + 13 = 43으로 해도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L02_challenge#10','math',2,1,'u3','L02','g2_1_math_u3_L02_challenge','lesson_challenge','M2-1-u3-C1',4,'mc','auto','어떤 수에 7을 더해야 할 것을 잘못하여 7을 뺐더니 18이 되었어요. 바르게 계산하면 얼마인가요?',ARRAY['M2-1-u3-X16','M2-1-u3-X10']::text[],true,'{"seq":10,"concept":"M2-1-u3-C1","difficulty":4,"kind":"mc","stem":"어떤 수에 7을 더해야 할 것을 잘못하여 7을 뺐더니 18이 되었어요. 바르게 계산하면 얼마인가요?","options":[{"t":"32","correct":true},{"t":"25","mis":"M2-1-u3-X16"},{"t":"11","mis":"M2-1-u3-X10"}],"explanation":["7을 뺐더니 18이니 어떤 수는 18 + 7 = 25예요.","바르게 계산하면 25 + 7 = 32예요.","25는 어떤 수 — 물음은 바르게 계산한 값이에요."],"variant_rule":{"alt":[{"stem":"어떤 수에 8을 더해야 할 것을 잘못하여 8을 뺐더니 26이 되었어요. 바르게 계산하면 얼마인가요?","options":[{"t":"42","correct":true},{"t":"34","mis":"M2-1-u3-X16"},{"t":"18","mis":"M2-1-u3-X10"}],"explanation":["8을 뺐더니 26이니 어떤 수는 26 + 8 = 34예요.","바르게 계산하면 34 + 8 = 42예요.","34는 어떤 수 — 물음은 바르게 계산한 값이에요."]},{"stem":"어떤 수에 9를 더해야 할 것을 잘못하여 9를 뺐더니 35가 되었어요. 바르게 계산하면 얼마인가요?","options":[{"t":"53","correct":true},{"t":"44","mis":"M2-1-u3-X16"},{"t":"26","mis":"M2-1-u3-X10"}],"explanation":["9를 뺐더니 35니까 어떤 수는 35 + 9 = 44예요.","바르게 계산하면 44 + 9 = 53이에요.","44는 어떤 수 — 물음은 바르게 계산한 값이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L03_basic#1','math',2,1,'u3','L03','g2_1_math_u3_L03_basic','lesson_basic','M2-1-u3-C2',1,'mc','auto','28 + 19는 얼마인가요?',ARRAY['M2-1-u3-X01','M2-1-u3-X02']::text[],true,'{"seq":1,"concept":"M2-1-u3-C2","difficulty":1,"kind":"mc","stem":"28 + 19는 얼마인가요?","explanation":["일의 자리 8 + 9 = 17 — 7을 쓰고 10은 십의 자리로 받아올려요.","십의 자리 2 + 1 + 1 = 4. 그래서 28 + 19 = 47이에요.","받아올림한 1은 십의 자리에서 꼭 더해요 — 빠뜨리면 10이 작아져요."],"variant_rule":{"ar2":{"ask":"value","kind":"a22"}},"options":[{"t":"47","correct":true},{"t":"37","mis":"M2-1-u3-X01"},{"t":"317","mis":"M2-1-u3-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L03_basic#2','math',2,1,'u3','L03','g2_1_math_u3_L03_basic','lesson_basic','M2-1-u3-C2',1,'sa','auto','45 + 17은 얼마인가요?','{}'::text[],true,'{"seq":2,"concept":"M2-1-u3-C2","difficulty":1,"kind":"sa","stem":"45 + 17은 얼마인가요?","explanation":["일의 자리 5 + 7 = 12 — 2를 쓰고 10은 십의 자리로 받아올려요.","십의 자리 4 + 1 + 1 = 6. 그래서 45 + 17 = 62예요.","받아올림한 1은 십의 자리에서 꼭 더해요 — 빠뜨리면 10이 작아져요."],"variant_rule":{"ar2":{"ask":"value","kind":"a22"}},"answer":["62"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L03_basic#3','math',2,1,'u3','L03','g2_1_math_u3_L03_basic','lesson_basic','M2-1-u3-C2',1,'mc','auto','28 + 19를 자리별로 나누어 더해요. 십의 자리끼리 더하면 얼마인가요?',ARRAY['M2-1-u3-X02']::text[],true,'{"seq":3,"concept":"M2-1-u3-C2","difficulty":1,"kind":"mc","stem":"28 + 19를 자리별로 나누어 더해요. 십의 자리끼리 더하면 얼마인가요?","options":[{"t":"30","correct":true},{"t":"3","mis":"M2-1-u3-X02"},{"t":"17","mis":"M2-1-u3-X02"}],"explanation":["28은 20과 8, 19는 10과 9예요.","십의 자리끼리 20 + 10 = 30이에요.","3은 숫자만 더한 것 — 십의 자리라서 30이에요."],"variant_rule":{"alt":[{"stem":"45 + 17을 자리별로 나누어 더해요. 일의 자리끼리 더하면 얼마인가요?","options":[{"t":"12","correct":true},{"t":"2","mis":"M2-1-u3-X01"},{"t":"50","mis":"M2-1-u3-X02"}],"explanation":["45는 40과 5, 17은 10과 7이에요.","일의 자리끼리 5 + 7 = 12예요.","12에서 2만 남기고 10을 버리면 안 돼요 — 10은 십의 자리로 가요."]},{"stem":"37 + 27을 자리별로 나누어 더해요. 십의 자리끼리 더하면 얼마인가요?","options":[{"t":"50","correct":true},{"t":"5","mis":"M2-1-u3-X02"},{"t":"14","mis":"M2-1-u3-X02"}],"explanation":["37은 30과 7, 27은 20과 7이에요.","십의 자리끼리 30 + 20 = 50이에요.","5는 숫자만 더한 것 — 십의 자리라서 50이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L03_basic#4','math',2,1,'u3','L03','g2_1_math_u3_L03_basic','lesson_basic','M2-1-u3-C2',1,'sa','auto','하루가 도토리 24개를 가지고 있었는데 18개를 더 받았어요. 도토리는 모두 몇 개인가요?','{}'::text[],true,'{"seq":4,"concept":"M2-1-u3-C2","difficulty":1,"kind":"sa","stem":"하루가 도토리 24개를 가지고 있었는데 18개를 더 받았어요. 도토리는 모두 몇 개인가요?","explanation":["일의 자리 4 + 8 = 12 — 2를 쓰고 10은 십의 자리로 받아올려요.","십의 자리 2 + 1 + 1 = 4. 그래서 24 + 18 = 42예요.","「모두」는 모으는 이야기라 덧셈이에요 — 42개예요."],"variant_rule":{"ar2":{"ask":"story","kind":"a22"}},"answer":["42","42개"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L03_basic#5','math',2,1,'u3','L03','g2_1_math_u3_L03_basic','lesson_basic','M2-1-u3-C2',2,'mc','auto','28 + 19를 계산하려고 9를 2와 □로 갈랐어요. □에 알맞은 수는 얼마인가요?',ARRAY['M2-1-u3-X04']::text[],true,'{"seq":5,"concept":"M2-1-u3-C2","difficulty":2,"kind":"mc","stem":"28 + 19를 계산하려고 9를 2와 □로 갈랐어요. □에 알맞은 수는 얼마인가요?","explanation":["28에 2를 더하면 30이 돼요.","9는 2와 7 — □는 7이에요.","30 + 7 + 10 = 47 — 몇십을 먼저 만들면 더하기 쉬워요."],"variant_rule":{"ar2":{"ask":"split","kind":"a22"}},"options":[{"t":"7","correct":true},{"t":"2","mis":"M2-1-u3-X04"},{"t":"8","mis":"M2-1-u3-X04"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L03_basic#6','math',2,1,'u3','L03','g2_1_math_u3_L03_basic','lesson_basic','M2-1-u3-C2',2,'ox','auto','37 + 27 = 54 입니다.',ARRAY['M2-1-u3-X01']::text[],true,'{"seq":6,"concept":"M2-1-u3-C2","difficulty":2,"kind":"ox","stem":"37 + 27 = 54 입니다.","explanation":["일의 자리 7 + 7 = 14 — 4를 쓰고 10은 십의 자리로 받아올려요.","십의 자리 3 + 2 + 1 = 6. 그래서 37 + 27 = 64예요.","받아올림한 1은 십의 자리에서 꼭 더해요 — 빠뜨리면 10이 작아져요."],"variant_rule":{"ar2":{"ask":"value","kind":"a22"}},"answer":"X","mis":"M2-1-u3-X01","reason_options":[{"t":"바르게 계산하면 64가 되니까","correct":true},{"t":"일의 자리끼리, 십의 자리끼리 더하기만 하면 되니까","mis":"M2-1-u3-X01"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L03_basic#7','math',2,1,'u3','L03','g2_1_math_u3_L03_basic','lesson_basic','M2-1-u3-C2',2,'mc','auto','36 + 25를 계산할 때, 36에 얼마를 더하면 40이 되나요?',ARRAY['M2-1-u3-X04']::text[],true,'{"seq":7,"concept":"M2-1-u3-C2","difficulty":2,"kind":"mc","stem":"36 + 25를 계산할 때, 36에 얼마를 더하면 40이 되나요?","explanation":["36에서 40까지는 4만큼 더 가야 해요.","36 + 4 = 40 — 먼저 몇십을 만들어요.","남은 21을 더하면 40 + 21 = 61이에요."],"variant_rule":{"ar2":{"ask":"fill","kind":"a22"}},"options":[{"t":"4","correct":true},{"t":"21","mis":"M2-1-u3-X04"},{"t":"6","mis":"M2-1-u3-X04"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L03_basic#8','math',2,1,'u3','L03','g2_1_math_u3_L03_basic','lesson_basic','M2-1-u3-C2',2,'mc','auto','56 + 38은 얼마인가요?',ARRAY['M2-1-u3-X01','M2-1-u3-X02','M2-1-u3-X06']::text[],true,'{"seq":8,"concept":"M2-1-u3-C2","difficulty":2,"kind":"mc","stem":"56 + 38은 얼마인가요?","explanation":["일의 자리 6 + 8 = 14 — 4를 쓰고 10은 십의 자리로 받아올려요.","십의 자리 5 + 3 + 1 = 9. 그래서 56 + 38 = 94예요.","받아올림한 1은 십의 자리에서 꼭 더해요 — 빠뜨리면 10이 작아져요."],"variant_rule":{"ar2":{"ask":"value","kind":"a22"}},"options":[{"t":"94","correct":true},{"t":"84","mis":"M2-1-u3-X01"},{"t":"814","mis":"M2-1-u3-X02"},{"t":"104","mis":"M2-1-u3-X06"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L03_basic#9','math',2,1,'u3','L03','g2_1_math_u3_L03_basic','lesson_basic','M2-1-u3-C2',2,'error','auto','친구들이 덧셈을 했어요. 잘못 계산한 친구는 누구인가요?',ARRAY['M2-1-u3-X02','M2-1-u3-X01']::text[],true,'{"seq":9,"concept":"M2-1-u3-C2","difficulty":2,"kind":"error","stem":"친구들이 덧셈을 했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"하린: 28 + 19 = 317","correct":true,"mis_target":"M2-1-u3-X02"},{"t":"도윤: 24 + 18 = 42","mis":"M2-1-u3-X01"},{"t":"서아: 45 + 17 = 62","mis":"M2-1-u3-X01"}],"explanation":["28 + 19에서 일의 자리 8 + 9 = 17이에요.","7을 쓰고 1은 십의 자리로 — 2 + 1 + 1 = 4, 답은 47이에요.","하린이는 십의 자리 3과 17을 그대로 이어 썼어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 친구들이 덧셈을 했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"민준: 37 + 27 = 54","correct":true,"mis_target":"M2-1-u3-X01"},{"t":"지우: 26 + 35 = 61","mis":"M2-1-u3-X01"},{"t":"하루: 18 + 46 = 64","mis":"M2-1-u3-X01"}],"explanation":["37 + 27에서 일의 자리 7 + 7 = 14예요.","4를 쓰고 1을 받아올려 3 + 2 + 1 = 6, 답은 64예요.","민준이는 받아올림한 1을 더하지 않았어요."]},{"stem":"이번에는 다른 보기예요. 친구들이 덧셈을 했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"은우: 46 + 28 = 64","correct":true,"mis_target":"M2-1-u3-X01"},{"t":"다예: 19 + 33 = 52","mis":"M2-1-u3-X01"},{"t":"서아: 27 + 45 = 72","mis":"M2-1-u3-X01"}],"explanation":["46 + 28에서 일의 자리 6 + 8 = 14예요.","4를 쓰고 1을 받아올려 4 + 2 + 1 = 7, 답은 74예요.","은우는 받아올림한 1을 더하지 않았어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L03_basic#10','math',2,1,'u3','L03','g2_1_math_u3_L03_basic','lesson_basic','M2-1-u3-C2',3,'mc','auto','받아올림이 있는 덧셈은 어느 것인가요?',ARRAY['M2-1-u3-X01']::text[],true,'{"seq":10,"concept":"M2-1-u3-C2","difficulty":3,"kind":"mc","stem":"받아올림이 있는 덧셈은 어느 것인가요?","options":[{"t":"36 + 27","correct":true},{"t":"42 + 35","mis":"M2-1-u3-X01"},{"t":"51 + 28","mis":"M2-1-u3-X01"}],"explanation":["일의 자리 합이 10이거나 10보다 크면 받아올림이 있어요.","36 + 27은 6 + 7 = 13이라 받아올림이 있어요.","2 + 5 = 7, 1 + 8 = 9는 10보다 작아요."],"variant_rule":{"alt":[{"stem":"받아올림이 없는 덧셈은 어느 것인가요?","options":[{"t":"43 + 25","correct":true},{"t":"38 + 24","mis":"M2-1-u3-X16"},{"t":"29 + 15","mis":"M2-1-u3-X16"}],"explanation":["일의 자리 합이 10보다 작으면 받아올림이 없어요.","43 + 25는 3 + 5 = 8이라 받아올림이 없어요.","8 + 4 = 12, 9 + 5 = 14는 받아올림이 있어요 — 「없는」 것을 물었어요."]},{"stem":"이번에는 다른 보기예요. 받아올림이 있는 덧셈은 어느 것인가요?","options":[{"t":"17 + 26","correct":true},{"t":"23 + 45","mis":"M2-1-u3-X01"},{"t":"34 + 52","mis":"M2-1-u3-X01"}],"explanation":["일의 자리 합을 먼저 봐요.","17 + 26은 7 + 6 = 13이라 받아올림이 있어요.","3 + 5 = 8, 4 + 2 = 6은 10보다 작아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L03_challenge#1','math',2,1,'u3','L03','g2_1_math_u3_L03_challenge','lesson_challenge','M2-1-u3-C2',2,'sa','auto','39 + 26은 얼마인가요?','{}'::text[],true,'{"seq":1,"concept":"M2-1-u3-C2","difficulty":2,"kind":"sa","stem":"39 + 26은 얼마인가요?","explanation":["일의 자리 9 + 6 = 15 — 5를 쓰고 10은 십의 자리로 받아올려요.","십의 자리 3 + 2 + 1 = 6. 그래서 39 + 26 = 65예요.","받아올림한 1은 십의 자리에서 꼭 더해요 — 빠뜨리면 10이 작아져요."],"variant_rule":{"ar2":{"ask":"value","kind":"a22"}},"answer":["65"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L03_challenge#2','math',2,1,'u3','L03','g2_1_math_u3_L03_challenge','lesson_challenge','M2-1-u3-C2',2,'mc','auto','47 + 25를 세로셈으로 계산할 때, 십의 자리에서 계산할 식은 어느 것인가요?',ARRAY['M2-1-u3-X01','M2-1-u3-X06']::text[],true,'{"seq":2,"concept":"M2-1-u3-C2","difficulty":2,"kind":"mc","stem":"47 + 25를 세로셈으로 계산할 때, 십의 자리에서 계산할 식은 어느 것인가요?","explanation":["일의 자리 7 + 5 = 12 — 10을 십의 자리로 받아올려요.","받아올림한 10은 십의 자리에서는 1이에요. 그래서 십의 자리 식은 4 + 2 + 1이에요.","받아올린 수는 십의 자리에서 「1」로 더해요 — 10을 더하지 않아요."],"variant_rule":{"ar2":{"ask":"carry","kind":"a22"}},"options":[{"t":"4 + 2 + 1","correct":true},{"t":"4 + 2","mis":"M2-1-u3-X01"},{"t":"4 + 2 + 10","mis":"M2-1-u3-X06"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L03_challenge#3','math',2,1,'u3','L03','g2_1_math_u3_L03_challenge','lesson_challenge','M2-1-u3-C2',3,'mc','auto','다예가 도토리 38개를 가지고 있었는데 47개를 더 받았어요. 도토리는 모두 몇 개인가요?',ARRAY['M2-1-u3-X01','M2-1-u3-X02','M2-1-u3-X06']::text[],true,'{"seq":3,"concept":"M2-1-u3-C2","difficulty":3,"kind":"mc","stem":"다예가 도토리 38개를 가지고 있었는데 47개를 더 받았어요. 도토리는 모두 몇 개인가요?","explanation":["일의 자리 8 + 7 = 15 — 5를 쓰고 10은 십의 자리로 받아올려요.","십의 자리 3 + 4 + 1 = 8. 그래서 38 + 47 = 85예요.","「모두」는 모으는 이야기라 덧셈이에요 — 85개예요."],"variant_rule":{"ar2":{"ask":"story","kind":"a22"}},"options":[{"t":"85","correct":true},{"t":"75","mis":"M2-1-u3-X01"},{"t":"715","mis":"M2-1-u3-X02"},{"t":"95","mis":"M2-1-u3-X06"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L03_challenge#4','math',2,1,'u3','L03','g2_1_math_u3_L03_challenge','lesson_challenge','M2-1-u3-C2',3,'ox','auto','18 + 47 = 65 입니다.',ARRAY['M2-1-u3-X01']::text[],true,'{"seq":4,"concept":"M2-1-u3-C2","difficulty":3,"kind":"ox","stem":"18 + 47 = 65 입니다.","explanation":["일의 자리 8 + 7 = 15 — 5를 쓰고 10은 십의 자리로 받아올려요.","십의 자리 1 + 4 + 1 = 6. 그래서 18 + 47 = 65예요.","받아올림한 1은 십의 자리에서 꼭 더해요 — 빠뜨리면 10이 작아져요."],"variant_rule":{"ar2":{"ask":"value","kind":"a22"}},"answer":"O","mis":"M2-1-u3-X01","reason_options":[{"t":"받아올림한 1을 십의 자리에 더해 계산했으니까","correct":true},{"t":"일의 자리끼리, 십의 자리끼리 더하기만 하면 되니까","mis":"M2-1-u3-X01"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L03_challenge#5','math',2,1,'u3','L03','g2_1_math_u3_L03_challenge','lesson_challenge','M2-1-u3-C2',3,'sa','auto','도토리를 곰이는 28개 주웠고, 펭이는 곰이보다 9개 더 많이 주웠어요. 두 친구가 주운 도토리는 모두 몇 개인가요?','{}'::text[],true,'{"seq":5,"concept":"M2-1-u3-C2","difficulty":3,"kind":"sa","stem":"도토리를 곰이는 28개 주웠고, 펭이는 곰이보다 9개 더 많이 주웠어요. 두 친구가 주운 도토리는 모두 몇 개인가요?","answer":["65","65개"],"explanation":["펭이는 28 + 9 = 37개 주웠어요.","모두 28 + 37 = 65개예요.","펭이가 주운 수를 먼저 구하고 두 수를 더해요."],"variant_rule":{"alt":[{"stem":"구슬을 지우는 25개 가졌고, 서아는 지우보다 7개 더 많이 가졌어요. 두 친구의 구슬은 모두 몇 개인가요?","answer":["57","57개"],"explanation":["서아는 25 + 7 = 32개예요.","모두 25 + 32 = 57개예요.","서아의 수를 먼저 구하고 두 수를 더해요."]},{"stem":"색종이를 하루는 19장 가졌고, 다예는 하루보다 8장 더 많이 가졌어요. 두 친구의 색종이는 모두 몇 장인가요?","answer":["46","46장"],"explanation":["다예는 19 + 8 = 27장이에요.","모두 19 + 27 = 46장이에요.","다예의 수를 먼저 구하고 두 수를 더해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L03_challenge#6','math',2,1,'u3','L03','g2_1_math_u3_L03_challenge','lesson_challenge','M2-1-u3-C2',3,'mc','auto','□ 안에 알맞은 수는 무엇인가요?  2□ + 35 = 63',ARRAY['M2-1-u3-X01','M2-1-u3-X02']::text[],true,'{"seq":6,"concept":"M2-1-u3-C2","difficulty":3,"kind":"mc","stem":"□ 안에 알맞은 수는 무엇인가요?  2□ + 35 = 63","options":[{"t":"8","correct":true},{"t":"9","mis":"M2-1-u3-X01"},{"t":"18","mis":"M2-1-u3-X02"}],"explanation":["일의 자리 □ + 5의 일의 자리가 3이 되려면 □ + 5 = 13이에요.","그래서 □ = 8 — 28 + 35 = 63으로 확인해요.","받아올림한 1이 십의 자리 2 + 3에 더해져 6이 돼요."],"variant_rule":{"alt":[{"stem":"□ 안에 알맞은 수는 무엇인가요?  4□ + 28 = 75","options":[{"t":"7","correct":true},{"t":"6","mis":"M2-1-u3-X01"},{"t":"17","mis":"M2-1-u3-X02"}],"explanation":["□ + 8의 일의 자리가 5가 되려면 □ + 8 = 15예요.","그래서 □ = 7 — 47 + 28 = 75로 확인해요.","받아올림한 1까지 더해 십의 자리가 4 + 2 + 1 = 7이 돼요."]},{"stem":"□ 안에 알맞은 수는 무엇인가요?  3□ + 16 = 54","options":[{"t":"8","correct":true},{"t":"9","mis":"M2-1-u3-X01"},{"t":"18","mis":"M2-1-u3-X02"}],"explanation":["□ + 6의 일의 자리가 4가 되려면 □ + 6 = 14예요.","그래서 □ = 8 — 38 + 16 = 54로 확인해요.","받아올림한 1까지 더해 십의 자리가 3 + 1 + 1 = 5가 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L03_challenge#7','math',2,1,'u3','L03','g2_1_math_u3_L03_challenge','lesson_challenge','M2-1-u3-C2',3,'mc','auto','46 + 27을 계산하려고 7을 4와 □로 갈랐어요. □에 알맞은 수는 얼마인가요?',ARRAY['M2-1-u3-X04']::text[],true,'{"seq":7,"concept":"M2-1-u3-C2","difficulty":3,"kind":"mc","stem":"46 + 27을 계산하려고 7을 4와 □로 갈랐어요. □에 알맞은 수는 얼마인가요?","explanation":["46에 4를 더하면 50이 돼요.","7은 4와 3 — □는 3이에요.","50 + 3 + 20 = 73 — 몇십을 먼저 만들면 더하기 쉬워요."],"variant_rule":{"ar2":{"ask":"split","kind":"a22"}},"options":[{"t":"3","correct":true},{"t":"4","mis":"M2-1-u3-X04"},{"t":"6","mis":"M2-1-u3-X04"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L03_challenge#8','math',2,1,'u3','L03','g2_1_math_u3_L03_challenge','lesson_challenge','M2-1-u3-C2',4,'mc','auto','두 수의 합이 72인 것은 어느 것인가요?',ARRAY['M2-1-u3-X01']::text[],true,'{"seq":8,"concept":"M2-1-u3-C2","difficulty":4,"kind":"mc","stem":"두 수의 합이 72인 것은 어느 것인가요?","options":[{"t":"38과 34","correct":true},{"t":"45와 37","mis":"M2-1-u3-X01"},{"t":"53과 29","mis":"M2-1-u3-X01"}],"explanation":["38 + 34 = 72, 45 + 37 = 82, 53 + 29 = 82예요.","합이 72인 것은 38과 34예요.","받아올림한 1을 빠뜨리면 45 + 37, 53 + 29도 72처럼 보여요."],"variant_rule":{"alt":[{"stem":"두 수의 합이 61인 것은 어느 것인가요?","options":[{"t":"27과 34","correct":true},{"t":"36과 35","mis":"M2-1-u3-X01"},{"t":"42와 29","mis":"M2-1-u3-X01"}],"explanation":["27 + 34 = 61, 36 + 35 = 71, 42 + 29 = 71이에요.","합이 61인 것은 27과 34예요.","받아올림한 1을 빠뜨리면 71이 61처럼 보여요."]},{"stem":"두 수의 합이 54인 것은 어느 것인가요?","options":[{"t":"19와 35","correct":true},{"t":"28과 36","mis":"M2-1-u3-X01"},{"t":"45와 19","mis":"M2-1-u3-X01"}],"explanation":["19 + 35 = 54, 28 + 36 = 64, 45 + 19 = 64예요.","합이 54인 것은 19와 35예요.","받아올림한 1을 빠뜨리면 64가 54처럼 보여요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L03_challenge#9','math',2,1,'u3','L03','g2_1_math_u3_L03_challenge','lesson_challenge','M2-1-u3-C2',4,'essay','teacher','28 + 19를 두 가지 방법으로 계산하고, 각 방법을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-1-u3-C2","difficulty":4,"kind":"essay","stem":"28 + 19를 두 가지 방법으로 계산하고, 각 방법을 설명해 보세요.","answer_guide":{"answer":"① 자리별로: 20 + 10 = 30, 8 + 9 = 17, 30 + 17 = 47. ② 몇십 만들기: 19를 20으로 보고 28 + 20 = 48, 1을 더 더했으니 48 − 1 = 47. (일의 자리부터 8 + 9 = 17, 7을 쓰고 1을 받아올려 2 + 1 + 1 = 4로 해도 좋다.)","scoring_points":["서로 다른 방법 두 가지를 썼는가","두 방법 모두 답이 47인가","받아올림(17의 10을 십의 자리로)이나 몇십 만들기를 말로 설명했는가"]},"explanation":["자리별로 나누면 30 + 17 = 47이에요.","19를 20으로 보고 더한 뒤 1을 빼도 47이에요.","일의 자리 17의 10은 십의 자리로 받아올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L03_challenge#10','math',2,1,'u3','L03','g2_1_math_u3_L03_challenge','lesson_challenge','M2-1-u3-C2',4,'mc','auto','곰이는 사탕을 27개 가지고 있고, 펭이는 곰이보다 15개 더 많이 가지고 있어요. 펭이가 친구에게서 사탕 18개를 더 받으면 펭이의 사탕은 몇 개가 되나요?',ARRAY['M2-1-u3-X16','M2-1-u3-X01']::text[],true,'{"seq":10,"concept":"M2-1-u3-C2","difficulty":4,"kind":"mc","stem":"곰이는 사탕을 27개 가지고 있고, 펭이는 곰이보다 15개 더 많이 가지고 있어요. 펭이가 친구에게서 사탕 18개를 더 받으면 펭이의 사탕은 몇 개가 되나요?","options":[{"t":"60","correct":true},{"t":"45","mis":"M2-1-u3-X16"},{"t":"50","mis":"M2-1-u3-X01"}],"explanation":["펭이는 처음에 27 + 15 = 42개예요.","18개를 더 받으면 42 + 18 = 60개예요.","45는 곰이의 27개에 18을 더한 수 — 펭이의 수부터 구해요."],"variant_rule":{"alt":[{"stem":"지우는 구슬을 19개 가지고 있고, 서아는 지우보다 16개 더 많이 가지고 있어요. 서아가 구슬 27개를 더 받으면 서아의 구슬은 몇 개가 되나요?","options":[{"t":"62","correct":true},{"t":"46","mis":"M2-1-u3-X16"},{"t":"52","mis":"M2-1-u3-X01"}],"explanation":["서아는 처음에 19 + 16 = 35개예요.","27개를 더 받으면 35 + 27 = 62개예요.","46은 지우의 19개에 27을 더한 수 — 서아의 수부터 구해요."]},{"stem":"하루는 딱지를 36장 가지고 있고, 다예는 하루보다 18장 더 많이 가지고 있어요. 다예가 딱지 29장을 더 접으면 다예의 딱지는 몇 장이 되나요?","options":[{"t":"83","correct":true},{"t":"65","mis":"M2-1-u3-X16"},{"t":"73","mis":"M2-1-u3-X01"}],"explanation":["다예는 처음에 36 + 18 = 54장이에요.","29장을 더 접으면 54 + 29 = 83장이에요.","65는 하루의 36장에 29를 더한 수 — 다예의 수부터 구해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L04_basic#1','math',2,1,'u3','L04','g2_1_math_u3_L04_basic','lesson_basic','M2-1-u3-C3',1,'mc','auto','36 + 28을 세로셈으로 계산하면 얼마인가요?',ARRAY['M2-1-u3-X01','M2-1-u3-X02']::text[],true,'{"seq":1,"concept":"M2-1-u3-C3","difficulty":1,"kind":"mc","stem":"36 + 28을 세로셈으로 계산하면 얼마인가요?","explanation":["일의 자리 6 + 8 = 14 — 4를 쓰고 10은 십의 자리로 받아올려요.","십의 자리 3 + 2 + 1 = 6. 그래서 36 + 28 = 64예요.","받아올림한 1은 십의 자리에서 꼭 더해요 — 빠뜨리면 10이 작아져요."],"variant_rule":{"ar2":{"ask":"vert","kind":"a22"}},"options":[{"t":"64","correct":true},{"t":"54","mis":"M2-1-u3-X01"},{"t":"514","mis":"M2-1-u3-X02"}],"asset":{"type":"vert2","top":36,"bottom":28,"op":"+","ans":null}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L04_basic#2','math',2,1,'u3','L04','g2_1_math_u3_L04_basic','lesson_basic','M2-1-u3-C3',1,'mc','auto','62 + 53을 세로셈으로 계산하면 얼마인가요?',ARRAY['M2-1-u3-X05']::text[],true,'{"seq":2,"concept":"M2-1-u3-C3","difficulty":1,"kind":"mc","stem":"62 + 53을 세로셈으로 계산하면 얼마인가요?","explanation":["일의 자리 2 + 3 = 5예요.","십의 자리 6 + 5 = 11 — 10이 넘어 백의 자리로 올려요. 그래서 62 + 53 = 115예요.","십의 자리 합이 10을 넘으면 백의 자리에 1을 써요."],"variant_rule":{"ar2":{"ask":"vert","kind":"a22h"}},"options":[{"t":"115","correct":true},{"t":"15","mis":"M2-1-u3-X05"},{"t":"105","mis":"M2-1-u3-X05"}],"asset":{"type":"vert2","top":62,"bottom":53,"op":"+","ans":null}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L04_basic#3','math',2,1,'u3','L04','g2_1_math_u3_L04_basic','lesson_basic','M2-1-u3-C3',1,'mc','auto','47 + 28을 세로셈으로 계산할 때, 십의 자리에서 계산할 식은 어느 것인가요?',ARRAY['M2-1-u3-X01','M2-1-u3-X06']::text[],true,'{"seq":3,"concept":"M2-1-u3-C3","difficulty":1,"kind":"mc","stem":"47 + 28을 세로셈으로 계산할 때, 십의 자리에서 계산할 식은 어느 것인가요?","explanation":["일의 자리 7 + 8 = 15 — 10을 십의 자리로 받아올려요.","받아올림한 10은 십의 자리에서는 1이에요. 그래서 십의 자리 식은 4 + 2 + 1이에요.","받아올린 수는 십의 자리에서 「1」로 더해요 — 10을 더하지 않아요."],"variant_rule":{"ar2":{"ask":"carry","kind":"a22"}},"options":[{"t":"4 + 2 + 1","correct":true},{"t":"4 + 2","mis":"M2-1-u3-X01"},{"t":"4 + 2 + 10","mis":"M2-1-u3-X06"}],"asset":{"type":"vert2","top":47,"bottom":28,"op":"+","ans":null}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L04_basic#4','math',2,1,'u3','L04','g2_1_math_u3_L04_basic','lesson_basic','M2-1-u3-C3',1,'mc','auto','세로셈으로 계산할 때 가장 먼저 계산하는 자리는 어디인가요?',ARRAY['M2-1-u3-X03']::text[],true,'{"seq":4,"concept":"M2-1-u3-C3","difficulty":1,"kind":"mc","stem":"세로셈으로 계산할 때 가장 먼저 계산하는 자리는 어디인가요?","options":[{"t":"일의 자리","correct":true},{"t":"십의 자리","mis":"M2-1-u3-X03"},{"t":"백의 자리","mis":"M2-1-u3-X03"}],"explanation":["세로셈은 오른쪽 끝, 일의 자리부터 계산해요.","일의 자리에서 받아올림이 생기면 십의 자리에 더해야 하니까요.","십의 자리부터 하면 받아올림을 놓치기 쉬워요."],"variant_rule":{"alt":[{"stem":"일의 자리에서 받아올림한 1은 어느 자리 위에 작게 써 두나요?","options":[{"t":"십의 자리","correct":true},{"t":"일의 자리","mis":"M2-1-u3-X01"},{"t":"백의 자리","mis":"M2-1-u3-X05"}],"explanation":["일의 자리 합의 10은 십의 자리 1이 돼요.","그래서 십의 자리 위에 작게 1을 써 두어요.","십의 자리를 더할 때 그 1을 함께 더해요."]},{"stem":"세로셈으로 두 수를 쓸 때 맞추어 써야 하는 것은 어느 것인가요?","options":[{"t":"같은 자리끼리 위아래로","correct":true},{"t":"두 수의 왼쪽 끝","mis":"M2-1-u3-X03"},{"t":"큰 수의 십의 자리와 작은 수의 일의 자리","mis":"M2-1-u3-X03"}],"explanation":["세로셈은 자리를 맞추어 써요.","일의 자리는 일의 자리끼리, 십의 자리는 십의 자리끼리 위아래로 써요.","자리를 맞추지 않으면 값이 달라져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L04_basic#5','math',2,1,'u3','L04','g2_1_math_u3_L04_basic','lesson_basic','M2-1-u3-C3',2,'mc','auto','68 + 59를 세로셈으로 계산하면 얼마인가요?',ARRAY['M2-1-u3-X01','M2-1-u3-X05']::text[],true,'{"seq":5,"concept":"M2-1-u3-C3","difficulty":2,"kind":"mc","stem":"68 + 59를 세로셈으로 계산하면 얼마인가요?","explanation":["일의 자리 8 + 9 = 17 — 7을 쓰고 10은 십의 자리로 받아올려요.","십의 자리 6 + 5 + 1 = 12 — 10이 넘어 백의 자리로 올려요. 그래서 68 + 59 = 127이에요.","십의 자리 합이 10을 넘으면 백의 자리에 1을 써요."],"variant_rule":{"ar2":{"ask":"vert","kind":"a22h"}},"options":[{"t":"127","correct":true},{"t":"117","mis":"M2-1-u3-X01"},{"t":"27","mis":"M2-1-u3-X05"}],"asset":{"type":"vert2","top":68,"bottom":59,"op":"+","ans":null}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L04_basic#6','math',2,1,'u3','L04','g2_1_math_u3_L04_basic','lesson_basic','M2-1-u3-C3',2,'ox','auto','75 + 74 = 49 입니다.',ARRAY['M2-1-u3-X01']::text[],true,'{"seq":6,"concept":"M2-1-u3-C3","difficulty":2,"kind":"ox","stem":"75 + 74 = 49 입니다.","explanation":["일의 자리 5 + 4 = 9예요.","십의 자리 7 + 7 = 14 — 10이 넘어 백의 자리로 올려요. 그래서 75 + 74 = 149예요.","십의 자리 합이 10을 넘으면 백의 자리에 1을 써요."],"variant_rule":{"ar2":{"ask":"value","kind":"a22h"}},"answer":"X","mis":"M2-1-u3-X05","reason_options":[{"t":"바르게 계산하면 149가 되니까","correct":true},{"t":"일의 자리끼리, 십의 자리끼리 더하기만 하면 되니까","mis":"M2-1-u3-X01"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L04_basic#7','math',2,1,'u3','L04','g2_1_math_u3_L04_basic','lesson_basic','M2-1-u3-C3',2,'mc','auto','58 + 7을 세로셈으로 계산하면 얼마인가요?',ARRAY['M2-1-u3-X01','M2-1-u3-X03']::text[],true,'{"seq":7,"concept":"M2-1-u3-C3","difficulty":2,"kind":"mc","stem":"58 + 7을 세로셈으로 계산하면 얼마인가요?","explanation":["일의 자리 8 + 7 = 15 — 5를 쓰고 10은 십의 자리로 받아올려요.","십의 자리 5 + 1 = 6. 그래서 58 + 7 = 65예요.","받아올림한 1은 십의 자리에서 꼭 더해요 — 빠뜨리면 10이 작아져요."],"variant_rule":{"ar2":{"ask":"vert","kind":"a21"}},"options":[{"t":"65","correct":true},{"t":"55","mis":"M2-1-u3-X01"},{"t":"128","mis":"M2-1-u3-X03"}],"asset":{"type":"vert2","top":58,"bottom":7,"op":"+","ans":null}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L04_basic#8','math',2,1,'u3','L04','g2_1_math_u3_L04_basic','lesson_basic','M2-1-u3-C3',2,'mc','auto','99 + 1은 얼마인가요?',ARRAY['M2-1-u3-X01','M2-1-u3-X05','M2-1-u3-X03']::text[],true,'{"seq":8,"concept":"M2-1-u3-C3","difficulty":2,"kind":"mc","stem":"99 + 1은 얼마인가요?","explanation":["일의 자리 9 + 1 = 10 — 0을 쓰고 10은 십의 자리로 받아올려요.","십의 자리 9 + 1 = 10 — 10이 넘어 백의 자리로 올려요. 그래서 99 + 1 = 100이에요.","십의 자리 합이 10을 넘으면 백의 자리에 1을 써요."],"variant_rule":{"ar2":{"ask":"value","kind":"a22h"}},"options":[{"t":"100","correct":true},{"t":"90","mis":"M2-1-u3-X01"},{"t":"0","mis":"M2-1-u3-X05"},{"t":"109","mis":"M2-1-u3-X03"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L04_basic#9','math',2,1,'u3','L04','g2_1_math_u3_L04_basic','lesson_basic','M2-1-u3-C3',2,'mc','auto','지우가 58 + 46을 세로셈으로 계산한 것이에요. 잘못 계산한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M2-1-u3-X02','M2-1-u3-X03']::text[],true,'{"seq":9,"concept":"M2-1-u3-C3","difficulty":2,"kind":"mc","stem":"지우가 58 + 46을 세로셈으로 계산한 것이에요. 잘못 계산한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"받아올림한 1을 십의 자리에서 더하지 않았어요.","correct":true},{"t":"일의 자리 8 + 6을 잘못 더했어요.","mis":"M2-1-u3-X02"},{"t":"두 수의 자리를 맞추지 않았어요.","mis":"M2-1-u3-X03"}],"explanation":["일의 자리 8 + 6 = 14 — 4를 쓰고 1을 받아올려요.","십의 자리 5 + 4 + 1 = 10 — 바른 답은 104예요.","지우는 받아올림한 1을 더하지 않아 94라고 썼어요."],"asset":{"type":"vert2","top":58,"bottom":46,"op":"+","ans":94},"variant_rule":{"alt":[{"stem":"지우가 62 + 53을 세로셈으로 계산한 것이에요. 잘못 계산한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"십의 자리 합 11의 1을 백의 자리로 올리지 않았어요.","correct":true},{"t":"일의 자리 2 + 3을 잘못 더했어요.","mis":"M2-1-u3-X02"},{"t":"받아올림한 1을 두 번 더했어요.","mis":"M2-1-u3-X06"}],"explanation":["일의 자리 2 + 3 = 5예요.","십의 자리 6 + 5 = 11 — 1을 쓰고 1은 백의 자리로, 바른 답은 115예요.","지우는 백의 자리를 쓰지 않아 15라고 썼어요."],"asset":{"type":"vert2","top":62,"bottom":53,"op":"+","ans":15}},{"stem":"지우가 47 + 28을 세로셈으로 계산한 것이에요. 잘못 계산한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"일의 자리 합 15를 그대로 이어 썼어요.","correct":true},{"t":"십의 자리 4 + 2를 잘못 더했어요.","mis":"M2-1-u3-X01"},{"t":"두 수의 자리를 맞추지 않았어요.","mis":"M2-1-u3-X03"}],"explanation":["일의 자리 7 + 8 = 15 — 5만 쓰고 1은 받아올려요.","십의 자리 4 + 2 + 1 = 7 — 바른 답은 75예요.","지우는 15를 한 칸에 다 써서 615가 되었어요."],"asset":{"type":"vert2","top":47,"bottom":28,"op":"+","ans":615}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L04_basic#10','math',2,1,'u3','L04','g2_1_math_u3_L04_basic','lesson_basic','M2-1-u3-C3',3,'sa','auto','서아가 색종이 58장을 가지고 있었는데 46장을 더 받았어요. 색종이는 모두 몇 장인가요?','{}'::text[],true,'{"seq":10,"concept":"M2-1-u3-C3","difficulty":3,"kind":"sa","stem":"서아가 색종이 58장을 가지고 있었는데 46장을 더 받았어요. 색종이는 모두 몇 장인가요?","explanation":["일의 자리 8 + 6 = 14 — 4를 쓰고 10은 십의 자리로 받아올려요.","십의 자리 5 + 4 + 1 = 10 — 10이 넘어 백의 자리로 올려요. 그래서 58 + 46 = 104예요.","「모두」는 모으는 이야기라 덧셈이에요 — 104장이에요."],"variant_rule":{"ar2":{"ask":"story","kind":"a22h"}},"answer":["104","104장"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L04_challenge#1','math',2,1,'u3','L04','g2_1_math_u3_L04_challenge','lesson_challenge','M2-1-u3-C3',2,'mc','auto','87 + 46을 세로셈으로 계산하면 얼마인가요?',ARRAY['M2-1-u3-X01','M2-1-u3-X05']::text[],true,'{"seq":1,"concept":"M2-1-u3-C3","difficulty":2,"kind":"mc","stem":"87 + 46을 세로셈으로 계산하면 얼마인가요?","explanation":["일의 자리 7 + 6 = 13 — 3을 쓰고 10은 십의 자리로 받아올려요.","십의 자리 8 + 4 + 1 = 13 — 10이 넘어 백의 자리로 올려요. 그래서 87 + 46 = 133이에요.","십의 자리 합이 10을 넘으면 백의 자리에 1을 써요."],"variant_rule":{"ar2":{"ask":"vert","kind":"a22h"}},"options":[{"t":"133","correct":true},{"t":"123","mis":"M2-1-u3-X01"},{"t":"33","mis":"M2-1-u3-X05"}],"asset":{"type":"vert2","top":87,"bottom":46,"op":"+","ans":null}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L04_challenge#2','math',2,1,'u3','L04','g2_1_math_u3_L04_challenge','lesson_challenge','M2-1-u3-C3',2,'sa','auto','94 + 38은 얼마인가요?','{}'::text[],true,'{"seq":2,"concept":"M2-1-u3-C3","difficulty":2,"kind":"sa","stem":"94 + 38은 얼마인가요?","explanation":["일의 자리 4 + 8 = 12 — 2를 쓰고 10은 십의 자리로 받아올려요.","십의 자리 9 + 3 + 1 = 13 — 10이 넘어 백의 자리로 올려요. 그래서 94 + 38 = 132예요.","십의 자리 합이 10을 넘으면 백의 자리에 1을 써요."],"variant_rule":{"ar2":{"ask":"value","kind":"a22h"}},"answer":["132"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L04_challenge#3','math',2,1,'u3','L04','g2_1_math_u3_L04_challenge','lesson_challenge','M2-1-u3-C3',3,'mc','auto','39 + 46을 세로셈으로 계산할 때, 십의 자리에서 계산할 식은 어느 것인가요?',ARRAY['M2-1-u3-X01','M2-1-u3-X06']::text[],true,'{"seq":3,"concept":"M2-1-u3-C3","difficulty":3,"kind":"mc","stem":"39 + 46을 세로셈으로 계산할 때, 십의 자리에서 계산할 식은 어느 것인가요?","explanation":["일의 자리 9 + 6 = 15 — 10을 십의 자리로 받아올려요.","받아올림한 10은 십의 자리에서는 1이에요. 그래서 십의 자리 식은 3 + 4 + 1이에요.","받아올린 수는 십의 자리에서 「1」로 더해요 — 10을 더하지 않아요."],"variant_rule":{"ar2":{"ask":"carry","kind":"a22"}},"options":[{"t":"3 + 4 + 1","correct":true},{"t":"3 + 4","mis":"M2-1-u3-X01"},{"t":"3 + 4 + 10","mis":"M2-1-u3-X06"}],"asset":{"type":"vert2","top":39,"bottom":46,"op":"+","ans":null}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L04_challenge#4','math',2,1,'u3','L04','g2_1_math_u3_L04_challenge','lesson_challenge','M2-1-u3-C3',3,'mc','auto','하루가 도토리 76개를 가지고 있었는데 49개를 더 받았어요. 도토리는 모두 몇 개인가요?',ARRAY['M2-1-u3-X01','M2-1-u3-X05','M2-1-u3-X02']::text[],true,'{"seq":4,"concept":"M2-1-u3-C3","difficulty":3,"kind":"mc","stem":"하루가 도토리 76개를 가지고 있었는데 49개를 더 받았어요. 도토리는 모두 몇 개인가요?","explanation":["일의 자리 6 + 9 = 15 — 5를 쓰고 10은 십의 자리로 받아올려요.","십의 자리 7 + 4 + 1 = 12 — 10이 넘어 백의 자리로 올려요. 그래서 76 + 49 = 125예요.","「모두」는 모으는 이야기라 덧셈이에요 — 125개예요."],"variant_rule":{"ar2":{"ask":"story","kind":"a22h"}},"options":[{"t":"125","correct":true},{"t":"115","mis":"M2-1-u3-X01"},{"t":"25","mis":"M2-1-u3-X05"},{"t":"1115","mis":"M2-1-u3-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L04_challenge#5','math',2,1,'u3','L04','g2_1_math_u3_L04_challenge','lesson_challenge','M2-1-u3-C3',3,'mc','auto','68 + 59를 세로셈으로 계산할 때, 일의 자리 8 + 9 = 17에서 십의 자리로 받아올린 1은 실제로 얼마를 나타내나요?',ARRAY['M2-1-u3-X01','M2-1-u3-X02']::text[],true,'{"seq":5,"concept":"M2-1-u3-C3","difficulty":3,"kind":"mc","stem":"68 + 59를 세로셈으로 계산할 때, 일의 자리 8 + 9 = 17에서 십의 자리로 받아올린 1은 실제로 얼마를 나타내나요?","options":[{"t":"10","correct":true},{"t":"1","mis":"M2-1-u3-X01"},{"t":"17","mis":"M2-1-u3-X02"}],"explanation":["17은 10과 7이에요.","7은 일의 자리에 쓰고, 10은 십의 자리에 1로 올려요.","그래서 받아올린 1은 실제로 10을 나타내요."],"variant_rule":{"alt":[{"stem":"62 + 53에서 십의 자리 6 + 5 = 11의 1을 백의 자리로 올렸어요. 올린 1은 실제로 얼마를 나타내나요?","options":[{"t":"100","correct":true},{"t":"10","mis":"M2-1-u3-X05"},{"t":"1","mis":"M2-1-u3-X05"}],"explanation":["십의 자리 11은 10이 11개 — 110이에요.","그중 100은 백의 자리 1이 돼요.","그래서 올린 1은 100을 나타내요."]},{"stem":"47 + 36에서 일의 자리 7 + 6 = 13의 1을 십의 자리로 받아올렸어요. 받아올린 1은 실제로 얼마를 나타내나요?","options":[{"t":"10","correct":true},{"t":"1","mis":"M2-1-u3-X01"},{"t":"13","mis":"M2-1-u3-X02"}],"explanation":["13은 10과 3이에요.","3은 일의 자리에, 10은 십의 자리에 1로 올려요.","그래서 받아올린 1은 10을 나타내요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L04_challenge#6','math',2,1,'u3','L04','g2_1_math_u3_L04_challenge','lesson_challenge','M2-1-u3-C3',3,'ox','auto','49 + 51 = 100 입니다.',ARRAY['M2-1-u3-X01']::text[],true,'{"seq":6,"concept":"M2-1-u3-C3","difficulty":3,"kind":"ox","stem":"49 + 51 = 100 입니다.","explanation":["일의 자리 9 + 1 = 10 — 0을 쓰고 10은 십의 자리로 받아올려요.","십의 자리 4 + 5 + 1 = 10 — 10이 넘어 백의 자리로 올려요. 그래서 49 + 51 = 100이에요.","십의 자리 합이 10을 넘으면 백의 자리에 1을 써요."],"variant_rule":{"ar2":{"ask":"value","kind":"a22h"}},"answer":"O","mis":"M2-1-u3-X05","reason_options":[{"t":"받아올림한 1을 십의 자리에 더해 계산했으니까","correct":true},{"t":"일의 자리끼리, 십의 자리끼리 더하기만 하면 되니까","mis":"M2-1-u3-X01"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L04_challenge#7','math',2,1,'u3','L04','g2_1_math_u3_L04_challenge','lesson_challenge','M2-1-u3-C3',3,'sa','auto','책을 1반은 58권, 2반은 46권 모았어요. 두 반이 모은 책은 100권보다 몇 권 많은가요?','{}'::text[],true,'{"seq":7,"concept":"M2-1-u3-C3","difficulty":3,"kind":"sa","stem":"책을 1반은 58권, 2반은 46권 모았어요. 두 반이 모은 책은 100권보다 몇 권 많은가요?","answer":["4","4권"],"explanation":["58 + 46 = 104권이에요.","104는 100보다 4 많아요.","받아올림을 두 번 해요 — 일의 자리 14, 십의 자리 5 + 4 + 1 = 10."],"variant_rule":{"alt":[{"stem":"줄넘기를 지우는 67번, 서아는 48번 했어요. 두 친구가 한 줄넘기는 100번보다 몇 번 많은가요?","answer":["15","15번"],"explanation":["67 + 48 = 115번이에요.","115는 100보다 15 많아요.","일의 자리 15, 십의 자리 6 + 4 + 1 = 11 — 백의 자리가 생겨요."]},{"stem":"도토리를 곰이는 79개, 펭이는 35개 주웠어요. 두 친구가 주운 도토리는 100개보다 몇 개 많은가요?","answer":["14","14개"],"explanation":["79 + 35 = 114개예요.","114는 100보다 14 많아요.","일의 자리 14, 십의 자리 7 + 3 + 1 = 11 — 백의 자리가 생겨요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L04_challenge#8','math',2,1,'u3','L04','g2_1_math_u3_L04_challenge','lesson_challenge','M2-1-u3-C3',4,'mc','auto','수 카드 3, 6, 8, 9를 한 번씩 모두 써서 두 자리 수 두 개를 만들었어요. 두 수의 합이 가장 클 때, 그 합은 얼마인가요?',ARRAY['M2-1-u3-X16']::text[],true,'{"seq":8,"concept":"M2-1-u3-C3","difficulty":4,"kind":"mc","stem":"수 카드 3, 6, 8, 9를 한 번씩 모두 써서 두 자리 수 두 개를 만들었어요. 두 수의 합이 가장 클 때, 그 합은 얼마인가요?","options":[{"t":"179","correct":true},{"t":"161","mis":"M2-1-u3-X16"},{"t":"134","mis":"M2-1-u3-X16"}],"explanation":["합이 크려면 큰 수 9와 8을 십의 자리에 놓아요.","96 + 83 = 179 (93 + 86도 179)예요.","98처럼 한 수만 크게 만들면 98 + 63 = 161로 더 작아요."],"variant_rule":{"alt":[{"stem":"수 카드 2, 4, 7, 8을 한 번씩 모두 써서 두 자리 수 두 개를 만들었어요. 두 수의 합이 가장 클 때, 그 합은 얼마인가요?","options":[{"t":"156","correct":true},{"t":"129","mis":"M2-1-u3-X16"},{"t":"111","mis":"M2-1-u3-X16"}],"explanation":["합이 크려면 큰 수 8과 7을 십의 자리에 놓아요.","84 + 72 = 156 (82 + 74도 156)이에요.","87처럼 한 수만 크게 만들면 87 + 42 = 129로 더 작아요."]},{"stem":"수 카드 1, 4, 5, 9를 한 번씩 모두 써서 두 자리 수 두 개를 만들었어요. 두 수의 합이 가장 클 때, 그 합은 얼마인가요?","options":[{"t":"145","correct":true},{"t":"136","mis":"M2-1-u3-X16"},{"t":"109","mis":"M2-1-u3-X16"}],"explanation":["합이 크려면 큰 수 9와 5를 십의 자리에 놓아요.","94 + 51 = 145 (91 + 54도 145)예요.","95 + 41 = 136처럼 십의 자리에 4를 놓으면 더 작아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L04_challenge#9','math',2,1,'u3','L04','g2_1_math_u3_L04_challenge','lesson_challenge','M2-1-u3-C3',4,'essay','teacher','47 + 85를 세로셈으로 계산하는 방법을 순서대로 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-1-u3-C3","difficulty":4,"kind":"essay","stem":"47 + 85를 세로셈으로 계산하는 방법을 순서대로 설명해 보세요.","answer_guide":{"answer":"① 자리를 맞추어 쓴다. ② 일의 자리 7 + 5 = 12 — 2를 쓰고 1을 십의 자리로 받아올린다. ③ 십의 자리 4 + 8 + 1 = 13 — 3을 쓰고 1을 백의 자리에 쓴다. 답은 132.","scoring_points":["자리를 맞추어 일의 자리부터 계산했는가","일의 자리에서 받아올림한 1을 십의 자리에 더했는가","십의 자리 합 13의 1을 백의 자리에 써서 132를 구했는가"]},"explanation":["일의 자리 7 + 5 = 12 — 2를 쓰고 1을 받아올려요.","십의 자리 4 + 8 + 1 = 13 — 3을 쓰고 1은 백의 자리에 써요.","그래서 47 + 85 = 132예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L04_challenge#10','math',2,1,'u3','L04','g2_1_math_u3_L04_challenge','lesson_challenge','M2-1-u3-C3',4,'mc','auto','빨간 구슬은 68개이고, 파란 구슬은 빨간 구슬보다 17개 더 많아요. 구슬은 모두 몇 개인가요?',ARRAY['M2-1-u3-X16','M2-1-u3-X01']::text[],true,'{"seq":10,"concept":"M2-1-u3-C3","difficulty":4,"kind":"mc","stem":"빨간 구슬은 68개이고, 파란 구슬은 빨간 구슬보다 17개 더 많아요. 구슬은 모두 몇 개인가요?","options":[{"t":"153","correct":true},{"t":"85","mis":"M2-1-u3-X16"},{"t":"143","mis":"M2-1-u3-X01"}],"explanation":["파란 구슬은 68 + 17 = 85개예요.","모두 68 + 85 = 153개예요.","85는 파란 구슬만의 수 — 물음은 모두예요."],"variant_rule":{"alt":[{"stem":"노란 색종이는 57장이고, 초록 색종이는 노란 색종이보다 26장 더 많아요. 색종이는 모두 몇 장인가요?","options":[{"t":"140","correct":true},{"t":"83","mis":"M2-1-u3-X16"},{"t":"130","mis":"M2-1-u3-X01"}],"explanation":["초록 색종이는 57 + 26 = 83장이에요.","모두 57 + 83 = 140장이에요.","83은 초록 색종이만의 수 — 물음은 모두예요."]},{"stem":"곰이는 도토리를 49개 주웠고, 펭이는 곰이보다 38개 더 많이 주웠어요. 두 친구가 주운 도토리는 모두 몇 개인가요?","options":[{"t":"136","correct":true},{"t":"87","mis":"M2-1-u3-X16"},{"t":"126","mis":"M2-1-u3-X01"}],"explanation":["펭이는 49 + 38 = 87개예요.","모두 49 + 87 = 136개예요.","87은 펭이만의 수 — 물음은 모두예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L05_basic#1','math',2,1,'u3','L05','g2_1_math_u3_L05_basic','lesson_basic','M2-1-u3-C4',1,'mc','auto','23 − 5는 얼마인가요?',ARRAY['M2-1-u3-X07','M2-1-u3-X08']::text[],true,'{"seq":1,"concept":"M2-1-u3-C4","difficulty":1,"kind":"mc","stem":"23 − 5는 얼마인가요?","explanation":["일의 자리 3에서 5를 뺄 수 없어 십의 자리에서 10을 받아내려요 — 13 − 5 = 8.","십의 자리는 2에서 1을 내려 주어 1. 그래서 23 − 5 = 18이에요.","5 − 3처럼 거꾸로 빼지 않아요 — 위의 수에서 아래 수를 빼요."],"variant_rule":{"ar2":{"ask":"value","kind":"s21"}},"options":[{"t":"18","correct":true},{"t":"22","mis":"M2-1-u3-X07"},{"t":"28","mis":"M2-1-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L05_basic#2','math',2,1,'u3','L05','g2_1_math_u3_L05_basic','lesson_basic','M2-1-u3-C4',1,'mc','auto','32 − 7을 계산할 때, 32에서 얼마를 빼면 30이 되나요?',ARRAY['M2-1-u3-X09']::text[],true,'{"seq":2,"concept":"M2-1-u3-C4","difficulty":1,"kind":"mc","stem":"32 − 7을 계산할 때, 32에서 얼마를 빼면 30이 되나요?","explanation":["32에서 일의 자리 2를 빼면 30이 돼요.","32 − 2 = 30 — 먼저 몇십을 만들어요.","남은 5를 더 빼면 30 − 5 = 25예요."],"variant_rule":{"ar2":{"ask":"fill","kind":"s21"}},"options":[{"t":"2","correct":true},{"t":"5","mis":"M2-1-u3-X09"},{"t":"8","mis":"M2-1-u3-X09"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L05_basic#3','math',2,1,'u3','L05','g2_1_math_u3_L05_basic','lesson_basic','M2-1-u3-C4',1,'mc','auto','41 − 6을 계산하려고 6을 1과 □로 갈랐어요. □에 알맞은 수는 얼마인가요?',ARRAY['M2-1-u3-X09']::text[],true,'{"seq":3,"concept":"M2-1-u3-C4","difficulty":1,"kind":"mc","stem":"41 − 6을 계산하려고 6을 1과 □로 갈랐어요. □에 알맞은 수는 얼마인가요?","explanation":["41에서 1을 빼면 40이 돼요.","6은 1과 5 — □는 5예요.","40 − 5 = 35, 그래서 41 − 6 = 35예요."],"variant_rule":{"ar2":{"ask":"split","kind":"s21"}},"options":[{"t":"5","correct":true},{"t":"1","mis":"M2-1-u3-X09"},{"t":"9","mis":"M2-1-u3-X09"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L05_basic#4','math',2,1,'u3','L05','g2_1_math_u3_L05_basic','lesson_basic','M2-1-u3-C4',1,'sa','auto','하루가 도토리 24개를 가지고 있었는데 6개를 친구에게 주었어요. 남은 도토리는 몇 개인가요?','{}'::text[],true,'{"seq":4,"concept":"M2-1-u3-C4","difficulty":1,"kind":"sa","stem":"하루가 도토리 24개를 가지고 있었는데 6개를 친구에게 주었어요. 남은 도토리는 몇 개인가요?","explanation":["일의 자리 4에서 6을 뺄 수 없어 십의 자리에서 10을 받아내려요 — 14 − 6 = 8.","십의 자리는 2에서 1을 내려 주어 1. 그래서 24 − 6 = 18이에요.","「남은」은 덜어 내는 이야기라 뺄셈이에요 — 18개예요."],"variant_rule":{"ar2":{"ask":"story","kind":"s21"}},"answer":["18","18개"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L05_basic#5','math',2,1,'u3','L05','g2_1_math_u3_L05_basic','lesson_basic','M2-1-u3-C4',2,'sa','auto','53 − 7은 얼마인가요?','{}'::text[],true,'{"seq":5,"concept":"M2-1-u3-C4","difficulty":2,"kind":"sa","stem":"53 − 7은 얼마인가요?","explanation":["일의 자리 3에서 7을 뺄 수 없어 십의 자리에서 10을 받아내려요 — 13 − 7 = 6.","십의 자리는 5에서 1을 내려 주어 4. 그래서 53 − 7 = 46이에요.","7 − 3처럼 거꾸로 빼지 않아요 — 위의 수에서 아래 수를 빼요."],"variant_rule":{"ar2":{"ask":"value","kind":"s21"}},"answer":["46"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L05_basic#6','math',2,1,'u3','L05','g2_1_math_u3_L05_basic','lesson_basic','M2-1-u3-C4',2,'mc','auto','32 − 7을 세로셈으로 계산할 때, 일의 자리에서 계산할 식은 어느 것인가요?',ARRAY['M2-1-u3-X07','M2-1-u3-X09']::text[],true,'{"seq":6,"concept":"M2-1-u3-C4","difficulty":2,"kind":"mc","stem":"32 − 7을 세로셈으로 계산할 때, 일의 자리에서 계산할 식은 어느 것인가요?","explanation":["일의 자리 2에서 7을 뺄 수 없어요.","십의 자리에서 10을 받아내리면 일의 자리는 12 — 12 − 7을 계산해요.","7 − 2처럼 아래 수에서 위의 수를 빼지 않아요."],"variant_rule":{"ar2":{"ask":"borrow","kind":"s21"}},"options":[{"t":"12 − 7","correct":true},{"t":"7 − 2","mis":"M2-1-u3-X07"},{"t":"3 − 7","mis":"M2-1-u3-X09"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L05_basic#7','math',2,1,'u3','L05','g2_1_math_u3_L05_basic','lesson_basic','M2-1-u3-C4',2,'ox','auto','42 − 8 = 46 입니다.',ARRAY['M2-1-u3-X07']::text[],true,'{"seq":7,"concept":"M2-1-u3-C4","difficulty":2,"kind":"ox","stem":"42 − 8 = 46 입니다.","explanation":["일의 자리 2에서 8을 뺄 수 없어 십의 자리에서 10을 받아내려요 — 12 − 8 = 4.","십의 자리는 4에서 1을 내려 주어 3. 그래서 42 − 8 = 34예요.","8 − 2처럼 거꾸로 빼지 않아요 — 위의 수에서 아래 수를 빼요."],"variant_rule":{"ar2":{"ask":"value","kind":"s21"}},"answer":"X","mis":"M2-1-u3-X07","reason_options":[{"t":"바르게 계산하면 34가 되니까","correct":true},{"t":"일의 자리는 큰 수에서 작은 수를 빼면 되니까","mis":"M2-1-u3-X07"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L05_basic#8','math',2,1,'u3','L05','g2_1_math_u3_L05_basic','lesson_basic','M2-1-u3-C4',2,'mc','auto','23 − 5를 계산하려고 23의 십 모형 하나를 일 모형 10개로 바꾸었어요. 일 모형은 모두 몇 개가 되나요?',ARRAY['M2-1-u3-X09']::text[],true,'{"seq":8,"concept":"M2-1-u3-C4","difficulty":2,"kind":"mc","stem":"23 − 5를 계산하려고 23의 십 모형 하나를 일 모형 10개로 바꾸었어요. 일 모형은 모두 몇 개가 되나요?","options":[{"t":"13","correct":true},{"t":"3","mis":"M2-1-u3-X09"},{"t":"4","mis":"M2-1-u3-X09"}],"explanation":["23은 십 모형 2개와 일 모형 3개예요.","십 모형 하나를 일 모형 10개로 바꾸면 일 모형은 3 + 10 = 13개예요.","그래서 13 − 5 = 8, 십 모형은 1개 남아 18이에요."],"variant_rule":{"alt":[{"stem":"41 − 6을 계산하려고 41의 십 모형 하나를 일 모형 10개로 바꾸었어요. 일 모형은 모두 몇 개가 되나요?","options":[{"t":"11","correct":true},{"t":"1","mis":"M2-1-u3-X09"},{"t":"2","mis":"M2-1-u3-X09"}],"explanation":["41은 십 모형 4개와 일 모형 1개예요.","십 모형 하나를 바꾸면 일 모형은 1 + 10 = 11개예요.","그래서 11 − 6 = 5, 십 모형은 3개 남아 35예요."]},{"stem":"52 − 8을 계산하려고 52의 십 모형 하나를 일 모형 10개로 바꾸었어요. 일 모형은 모두 몇 개가 되나요?","options":[{"t":"12","correct":true},{"t":"2","mis":"M2-1-u3-X09"},{"t":"3","mis":"M2-1-u3-X09"}],"explanation":["52는 십 모형 5개와 일 모형 2개예요.","십 모형 하나를 바꾸면 일 모형은 2 + 10 = 12개예요.","그래서 12 − 8 = 4, 십 모형은 4개 남아 44예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L05_basic#9','math',2,1,'u3','L05','g2_1_math_u3_L05_basic','lesson_basic','M2-1-u3-C4',2,'error','auto','친구들이 뺄셈을 했어요. 잘못 계산한 친구는 누구인가요?',ARRAY['M2-1-u3-X07','M2-1-u3-X08']::text[],true,'{"seq":9,"concept":"M2-1-u3-C4","difficulty":2,"kind":"error","stem":"친구들이 뺄셈을 했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"하린: 32 − 7 = 35","correct":true,"mis_target":"M2-1-u3-X07"},{"t":"도윤: 41 − 6 = 35","mis":"M2-1-u3-X08"},{"t":"서아: 53 − 7 = 46","mis":"M2-1-u3-X08"}],"explanation":["32 − 7에서 일의 자리 2에서 7을 뺄 수 없어요.","십에서 10을 받아내려 12 − 7 = 5, 십의 자리 2 — 답은 25예요.","하린이는 7 − 2로 거꾸로 빼서 35라고 했어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 친구들이 뺄셈을 했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"민준: 41 − 6 = 45","correct":true,"mis_target":"M2-1-u3-X08"},{"t":"지우: 32 − 7 = 25","mis":"M2-1-u3-X07"},{"t":"하루: 24 − 9 = 15","mis":"M2-1-u3-X07"}],"explanation":["41 − 6에서 십에서 10을 받아내려 11 − 6 = 5예요.","십의 자리는 4에서 1이 줄어 3 — 답은 35예요.","민준이는 받아내림하고 십의 자리를 줄이지 않았어요."]},{"stem":"이번에는 다른 보기예요. 친구들이 뺄셈을 했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"은우: 50 − 4 = 54","correct":true,"mis_target":"M2-1-u3-X07"},{"t":"다예: 62 − 5 = 57","mis":"M2-1-u3-X08"},{"t":"서아: 31 − 8 = 23","mis":"M2-1-u3-X08"}],"explanation":["50 − 4에서 일의 자리 0에서 4를 뺄 수 없어요.","십에서 10을 받아내려 10 − 4 = 6, 십의 자리 4 — 답은 46이에요.","은우는 4 − 0으로 거꾸로 빼서 54라고 했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L05_basic#10','math',2,1,'u3','L05','g2_1_math_u3_L05_basic','lesson_basic','M2-1-u3-C4',3,'mc','auto','서아가 색종이 60장을 가지고 있었는데 7장을 친구에게 주었어요. 남은 색종이는 몇 장인가요?',ARRAY['M2-1-u3-X07','M2-1-u3-X08']::text[],true,'{"seq":10,"concept":"M2-1-u3-C4","difficulty":3,"kind":"mc","stem":"서아가 색종이 60장을 가지고 있었는데 7장을 친구에게 주었어요. 남은 색종이는 몇 장인가요?","explanation":["일의 자리 0에서 7을 뺄 수 없어 십의 자리에서 10을 받아내려요 — 10 − 7 = 3.","십의 자리는 6에서 1을 내려 주어 5. 그래서 60 − 7 = 53이에요.","「남은」은 덜어 내는 이야기라 뺄셈이에요 — 53장이에요."],"variant_rule":{"ar2":{"ask":"story","kind":"s21"}},"options":[{"t":"53","correct":true},{"t":"67","mis":"M2-1-u3-X07"},{"t":"63","mis":"M2-1-u3-X08"},{"t":"54","mis":"M2-1-u3-X07"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L05_challenge#1','math',2,1,'u3','L05','g2_1_math_u3_L05_challenge','lesson_challenge','M2-1-u3-C4',2,'sa','auto','71 − 9는 얼마인가요?','{}'::text[],true,'{"seq":1,"concept":"M2-1-u3-C4","difficulty":2,"kind":"sa","stem":"71 − 9는 얼마인가요?","explanation":["일의 자리 1에서 9를 뺄 수 없어 십의 자리에서 10을 받아내려요 — 11 − 9 = 2.","십의 자리는 7에서 1을 내려 주어 6. 그래서 71 − 9 = 62예요.","9 − 1처럼 거꾸로 빼지 않아요 — 위의 수에서 아래 수를 빼요."],"variant_rule":{"ar2":{"ask":"value","kind":"s21"}},"answer":["62"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L05_challenge#2','math',2,1,'u3','L05','g2_1_math_u3_L05_challenge','lesson_challenge','M2-1-u3-C4',2,'mc','auto','53 − 7을 계산하려고 7을 3과 □로 갈랐어요. □에 알맞은 수는 얼마인가요?',ARRAY['M2-1-u3-X09']::text[],true,'{"seq":2,"concept":"M2-1-u3-C4","difficulty":2,"kind":"mc","stem":"53 − 7을 계산하려고 7을 3과 □로 갈랐어요. □에 알맞은 수는 얼마인가요?","explanation":["53에서 3을 빼면 50이 돼요.","7은 3과 4 — □는 4예요.","50 − 4 = 46, 그래서 53 − 7 = 46이에요."],"variant_rule":{"ar2":{"ask":"split","kind":"s21"}},"options":[{"t":"4","correct":true},{"t":"3","mis":"M2-1-u3-X09"},{"t":"7","mis":"M2-1-u3-X09"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L05_challenge#3','math',2,1,'u3','L05','g2_1_math_u3_L05_challenge','lesson_challenge','M2-1-u3-C4',3,'mc','auto','다예가 도토리 45개를 가지고 있었는데 8개를 친구에게 주었어요. 남은 도토리는 몇 개인가요?',ARRAY['M2-1-u3-X07','M2-1-u3-X08']::text[],true,'{"seq":3,"concept":"M2-1-u3-C4","difficulty":3,"kind":"mc","stem":"다예가 도토리 45개를 가지고 있었는데 8개를 친구에게 주었어요. 남은 도토리는 몇 개인가요?","explanation":["일의 자리 5에서 8을 뺄 수 없어 십의 자리에서 10을 받아내려요 — 15 − 8 = 7.","십의 자리는 4에서 1을 내려 주어 3. 그래서 45 − 8 = 37이에요.","「남은」은 덜어 내는 이야기라 뺄셈이에요 — 37개예요."],"variant_rule":{"ar2":{"ask":"story","kind":"s21"}},"options":[{"t":"37","correct":true},{"t":"43","mis":"M2-1-u3-X07"},{"t":"47","mis":"M2-1-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L05_challenge#4','math',2,1,'u3','L05','g2_1_math_u3_L05_challenge','lesson_challenge','M2-1-u3-C4',3,'mc','auto','42 − 7을 먼저 몇십을 만들어 계산한 식으로 바른 것은 어느 것인가요?',ARRAY['M2-1-u3-X09','M2-1-u3-X08']::text[],true,'{"seq":4,"concept":"M2-1-u3-C4","difficulty":3,"kind":"mc","stem":"42 − 7을 먼저 몇십을 만들어 계산한 식으로 바른 것은 어느 것인가요?","options":[{"t":"42 − 2 − 5","correct":true},{"t":"42 − 2 − 7","mis":"M2-1-u3-X09"},{"t":"42 − 7 + 10","mis":"M2-1-u3-X08"}],"explanation":["42에서 2를 빼면 40이 돼요.","7을 2와 5로 갈라 42 − 2 − 5 = 35예요.","가른 뒤에는 남은 5만 빼요 — 7을 다시 빼지 않아요."],"variant_rule":{"alt":[{"stem":"31 − 4를 먼저 몇십을 만들어 계산한 식으로 바른 것은 어느 것인가요?","options":[{"t":"31 − 1 − 3","correct":true},{"t":"31 − 1 − 4","mis":"M2-1-u3-X09"},{"t":"31 − 4 + 10","mis":"M2-1-u3-X08"}],"explanation":["31에서 1을 빼면 30이 돼요.","4를 1과 3으로 갈라 31 − 1 − 3 = 27이에요.","가른 뒤에는 남은 3만 빼요."]},{"stem":"63 − 8을 먼저 몇십을 만들어 계산한 식으로 바른 것은 어느 것인가요?","options":[{"t":"63 − 3 − 5","correct":true},{"t":"63 − 3 − 8","mis":"M2-1-u3-X09"},{"t":"63 − 8 + 10","mis":"M2-1-u3-X08"}],"explanation":["63에서 3을 빼면 60이 돼요.","8을 3과 5로 갈라 63 − 3 − 5 = 55예요.","가른 뒤에는 남은 5만 빼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L05_challenge#5','math',2,1,'u3','L05','g2_1_math_u3_L05_challenge','lesson_challenge','M2-1-u3-C4',3,'ox','auto','36 − 9 = 27 입니다.',ARRAY['M2-1-u3-X07']::text[],true,'{"seq":5,"concept":"M2-1-u3-C4","difficulty":3,"kind":"ox","stem":"36 − 9 = 27 입니다.","explanation":["일의 자리 6에서 9를 뺄 수 없어 십의 자리에서 10을 받아내려요 — 16 − 9 = 7.","십의 자리는 3에서 1을 내려 주어 2. 그래서 36 − 9 = 27이에요.","9 − 6처럼 거꾸로 빼지 않아요 — 위의 수에서 아래 수를 빼요."],"variant_rule":{"ar2":{"ask":"value","kind":"s21"}},"answer":"O","mis":"M2-1-u3-X07","reason_options":[{"t":"십의 자리에서 받아내린 10을 더해 일의 자리를 뺐으니까","correct":true},{"t":"일의 자리는 큰 수에서 작은 수를 빼면 되니까","mis":"M2-1-u3-X07"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L05_challenge#6','math',2,1,'u3','L05','g2_1_math_u3_L05_challenge','lesson_challenge','M2-1-u3-C4',3,'sa','auto','40보다 2 큰 수에서 7을 빼면 얼마인가요?','{}'::text[],true,'{"seq":6,"concept":"M2-1-u3-C4","difficulty":3,"kind":"sa","stem":"40보다 2 큰 수에서 7을 빼면 얼마인가요?","answer":["35"],"explanation":["40보다 2 큰 수는 42예요.","42 − 7 — 일의 자리 2에서 7을 뺄 수 없어 받아내림해요.","12 − 7 = 5, 십의 자리 3 — 답은 35예요."],"variant_rule":{"alt":[{"stem":"50보다 3 큰 수에서 6을 빼면 얼마인가요?","answer":["47"],"explanation":["50보다 3 큰 수는 53이에요.","53 − 6 — 받아내림해서 13 − 6 = 7이에요.","십의 자리 4 — 답은 47이에요."]},{"stem":"70보다 1 큰 수에서 4를 빼면 얼마인가요?","answer":["67"],"explanation":["70보다 1 큰 수는 71이에요.","71 − 4 — 받아내림해서 11 − 4 = 7이에요.","십의 자리 6 — 답은 67이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L05_challenge#7','math',2,1,'u3','L05','g2_1_math_u3_L05_challenge','lesson_challenge','M2-1-u3-C4',3,'mc','auto','65 − 9를 계산할 때, 65에서 얼마를 빼면 60이 되나요?',ARRAY['M2-1-u3-X09']::text[],true,'{"seq":7,"concept":"M2-1-u3-C4","difficulty":3,"kind":"mc","stem":"65 − 9를 계산할 때, 65에서 얼마를 빼면 60이 되나요?","explanation":["65에서 일의 자리 5를 빼면 60이 돼요.","65 − 5 = 60 — 먼저 몇십을 만들어요.","남은 4를 더 빼면 60 − 4 = 56이에요."],"variant_rule":{"ar2":{"ask":"fill","kind":"s21"}},"options":[{"t":"5","correct":true},{"t":"4","mis":"M2-1-u3-X09"},{"t":"6","mis":"M2-1-u3-X09"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L05_challenge#8','math',2,1,'u3','L05','g2_1_math_u3_L05_challenge','lesson_challenge','M2-1-u3-C4',4,'mc','auto','4□ − 6에서 받아내림이 생겨요. □ 안에 들어갈 수 있는 수는 모두 몇 개인가요?',ARRAY['M2-1-u3-X16']::text[],true,'{"seq":8,"concept":"M2-1-u3-C4","difficulty":4,"kind":"mc","stem":"4□ − 6에서 받아내림이 생겨요. □ 안에 들어갈 수 있는 수는 모두 몇 개인가요?","options":[{"t":"6개","correct":true},{"t":"5개","mis":"M2-1-u3-X16"},{"t":"4개","mis":"M2-1-u3-X16"}],"explanation":["일의 자리 □가 6보다 작으면 받아내림이 생겨요.","□는 0, 1, 2, 3, 4, 5 — 모두 6개예요.","0도 들어갈 수 있어요 — 40 − 6도 받아내림이 있어요."],"variant_rule":{"alt":[{"stem":"7□ − 8에서 받아내림이 생겨요. □ 안에 들어갈 수 있는 수는 모두 몇 개인가요?","options":[{"t":"8개","correct":true},{"t":"7개","mis":"M2-1-u3-X16"},{"t":"9개","mis":"M2-1-u3-X16"}],"explanation":["일의 자리 □가 8보다 작으면 받아내림이 생겨요.","□는 0부터 7까지 — 모두 8개예요.","0을 빠뜨리지 않고, 8은 받아내림이 없어 빼요."]},{"stem":"2□ − 3에서 받아내림이 생겨요. □ 안에 들어갈 수 있는 수는 모두 몇 개인가요?","options":[{"t":"3개","correct":true},{"t":"2개","mis":"M2-1-u3-X16"},{"t":"4개","mis":"M2-1-u3-X16"}],"explanation":["일의 자리 □가 3보다 작으면 받아내림이 생겨요.","□는 0, 1, 2 — 모두 3개예요.","0을 빠뜨리지 않고, 3은 받아내림이 없어 빼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L05_challenge#9','math',2,1,'u3','L05','g2_1_math_u3_L05_challenge','lesson_challenge','M2-1-u3-C4',4,'essay','teacher','32 − 7을 두 가지 방법으로 계산하고, 각 방법을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-1-u3-C4","difficulty":4,"kind":"essay","stem":"32 − 7을 두 가지 방법으로 계산하고, 각 방법을 설명해 보세요.","answer_guide":{"answer":"① 7을 2와 5로 갈라 32 − 2 = 30, 30 − 5 = 25. ② 십 하나를 풀어 일의 자리를 12로 만들어 12 − 7 = 5, 십의 자리는 2가 남아 25.","scoring_points":["서로 다른 방법 두 가지를 썼는가","두 방법 모두 답이 25인가","몇십 만들기나 받아내림(십 하나를 10으로)을 말로 설명했는가"]},"explanation":["7을 2와 5로 가르면 32 − 2 = 30, 30 − 5 = 25예요.","십 하나를 풀면 12 − 7 = 5, 남은 십 2개 — 25예요.","두 방법 모두 일의 자리에서 뺄 수 없을 때 쓰는 방법이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L05_challenge#10','math',2,1,'u3','L05','g2_1_math_u3_L05_challenge','lesson_challenge','M2-1-u3-C4',4,'mc','auto','어떤 수에서 8을 빼야 할 것을 잘못하여 8을 더했더니 51이 되었어요. 바르게 계산하면 얼마인가요?',ARRAY['M2-1-u3-X16','M2-1-u3-X10']::text[],true,'{"seq":10,"concept":"M2-1-u3-C4","difficulty":4,"kind":"mc","stem":"어떤 수에서 8을 빼야 할 것을 잘못하여 8을 더했더니 51이 되었어요. 바르게 계산하면 얼마인가요?","options":[{"t":"35","correct":true},{"t":"43","mis":"M2-1-u3-X16"},{"t":"59","mis":"M2-1-u3-X10"}],"explanation":["8을 더했더니 51이니 어떤 수는 51 − 8 = 43이에요.","바르게 계산하면 43 − 8 = 35예요.","43은 어떤 수 — 물음은 바르게 계산한 값이에요."],"variant_rule":{"alt":[{"stem":"어떤 수에서 7을 빼야 할 것을 잘못하여 7을 더했더니 40이 되었어요. 바르게 계산하면 얼마인가요?","options":[{"t":"26","correct":true},{"t":"33","mis":"M2-1-u3-X16"},{"t":"47","mis":"M2-1-u3-X10"}],"explanation":["7을 더했더니 40이니 어떤 수는 40 − 7 = 33이에요.","바르게 계산하면 33 − 7 = 26이에요.","33은 어떤 수 — 물음은 바르게 계산한 값이에요."]},{"stem":"어떤 수에서 9를 빼야 할 것을 잘못하여 9를 더했더니 62가 되었어요. 바르게 계산하면 얼마인가요?","options":[{"t":"44","correct":true},{"t":"53","mis":"M2-1-u3-X16"},{"t":"71","mis":"M2-1-u3-X10"}],"explanation":["9를 더했더니 62니까 어떤 수는 62 − 9 = 53이에요.","바르게 계산하면 53 − 9 = 44예요.","53은 어떤 수 — 물음은 바르게 계산한 값이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L06_basic#1','math',2,1,'u3','L06','g2_1_math_u3_L06_basic','lesson_basic','M2-1-u3-C5',1,'mc','auto','42 − 19는 얼마인가요?',ARRAY['M2-1-u3-X07','M2-1-u3-X08']::text[],true,'{"seq":1,"concept":"M2-1-u3-C5","difficulty":1,"kind":"mc","stem":"42 − 19는 얼마인가요?","explanation":["일의 자리 2에서 9를 뺄 수 없어 십의 자리에서 10을 받아내려요 — 12 − 9 = 3.","십의 자리는 4에서 1을 내려 주어 3, 3 − 1 = 2. 그래서 42 − 19 = 23이에요.","9 − 2처럼 거꾸로 빼지 않아요 — 위의 수에서 아래 수를 빼요."],"variant_rule":{"ar2":{"ask":"value","kind":"s22"}},"options":[{"t":"23","correct":true},{"t":"37","mis":"M2-1-u3-X07"},{"t":"33","mis":"M2-1-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L06_basic#2','math',2,1,'u3','L06','g2_1_math_u3_L06_basic','lesson_basic','M2-1-u3-C5',1,'mc','auto','50 − 27을 세로셈으로 계산하면 얼마인가요?',ARRAY['M2-1-u3-X07','M2-1-u3-X08']::text[],true,'{"seq":2,"concept":"M2-1-u3-C5","difficulty":1,"kind":"mc","stem":"50 − 27을 세로셈으로 계산하면 얼마인가요?","explanation":["일의 자리 0에서 7을 뺄 수 없어 십의 자리에서 10을 받아내려요 — 10 − 7 = 3.","십의 자리는 5에서 1을 내려 주어 4, 4 − 2 = 2. 그래서 50 − 27 = 23이에요.","7 − 0처럼 거꾸로 빼지 않아요 — 위의 수에서 아래 수를 빼요."],"variant_rule":{"ar2":{"ask":"vert","kind":"s0"}},"options":[{"t":"23","correct":true},{"t":"37","mis":"M2-1-u3-X07"},{"t":"33","mis":"M2-1-u3-X08"}],"asset":{"type":"vert2","top":50,"bottom":27,"op":"-","ans":null}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L06_basic#3','math',2,1,'u3','L06','g2_1_math_u3_L06_basic','lesson_basic','M2-1-u3-C5',1,'mc','auto','54 − 26을 세로셈으로 계산할 때, 십의 자리에서 계산할 식은 어느 것인가요?',ARRAY['M2-1-u3-X08','M2-1-u3-X10']::text[],true,'{"seq":3,"concept":"M2-1-u3-C5","difficulty":1,"kind":"mc","stem":"54 − 26을 세로셈으로 계산할 때, 십의 자리에서 계산할 식은 어느 것인가요?","explanation":["일의 자리를 계산하려고 십의 자리에서 10을 받아내렸어요.","그래서 십의 자리는 5에서 1이 줄어 4 — 4 − 2를 계산해요.","받아내려 준 자리는 1을 줄이는 것을 잊지 않아요."],"variant_rule":{"ar2":{"ask":"btens","kind":"s22"}},"options":[{"t":"4 − 2","correct":true},{"t":"5 − 2","mis":"M2-1-u3-X08"},{"t":"4 + 2","mis":"M2-1-u3-X10"}],"asset":{"type":"vert2","top":54,"bottom":26,"op":"-","ans":null}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L06_basic#4','math',2,1,'u3','L06','g2_1_math_u3_L06_basic','lesson_basic','M2-1-u3-C5',1,'sa','auto','하루가 도토리 45개를 가지고 있었는데 28개를 친구에게 주었어요. 남은 도토리는 몇 개인가요?','{}'::text[],true,'{"seq":4,"concept":"M2-1-u3-C5","difficulty":1,"kind":"sa","stem":"하루가 도토리 45개를 가지고 있었는데 28개를 친구에게 주었어요. 남은 도토리는 몇 개인가요?","explanation":["일의 자리 5에서 8을 뺄 수 없어 십의 자리에서 10을 받아내려요 — 15 − 8 = 7.","십의 자리는 4에서 1을 내려 주어 3, 3 − 2 = 1. 그래서 45 − 28 = 17이에요.","「남은」은 덜어 내는 이야기라 뺄셈이에요 — 17개예요."],"variant_rule":{"ar2":{"ask":"story","kind":"s22"}},"answer":["17","17개"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L06_basic#5','math',2,1,'u3','L06','g2_1_math_u3_L06_basic','lesson_basic','M2-1-u3-C5',2,'mc','auto','81 − 37을 세로셈으로 계산하면 얼마인가요?',ARRAY['M2-1-u3-X07','M2-1-u3-X08']::text[],true,'{"seq":5,"concept":"M2-1-u3-C5","difficulty":2,"kind":"mc","stem":"81 − 37을 세로셈으로 계산하면 얼마인가요?","explanation":["일의 자리 1에서 7을 뺄 수 없어 십의 자리에서 10을 받아내려요 — 11 − 7 = 4.","십의 자리는 8에서 1을 내려 주어 7, 7 − 3 = 4. 그래서 81 − 37 = 44예요.","7 − 1처럼 거꾸로 빼지 않아요 — 위의 수에서 아래 수를 빼요."],"variant_rule":{"ar2":{"ask":"vert","kind":"s22"}},"options":[{"t":"44","correct":true},{"t":"56","mis":"M2-1-u3-X07"},{"t":"54","mis":"M2-1-u3-X08"}],"asset":{"type":"vert2","top":81,"bottom":37,"op":"-","ans":null}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L06_basic#6','math',2,1,'u3','L06','g2_1_math_u3_L06_basic','lesson_basic','M2-1-u3-C5',2,'mc','auto','63 − 27을 세로셈으로 계산할 때, 일의 자리에서 계산할 식은 어느 것인가요?',ARRAY['M2-1-u3-X07','M2-1-u3-X09']::text[],true,'{"seq":6,"concept":"M2-1-u3-C5","difficulty":2,"kind":"mc","stem":"63 − 27을 세로셈으로 계산할 때, 일의 자리에서 계산할 식은 어느 것인가요?","explanation":["일의 자리 3에서 7을 뺄 수 없어요.","십의 자리에서 10을 받아내리면 일의 자리는 13 — 13 − 7을 계산해요.","7 − 3처럼 아래 수에서 위의 수를 빼지 않아요."],"variant_rule":{"ar2":{"ask":"borrow","kind":"s22"}},"options":[{"t":"13 − 7","correct":true},{"t":"7 − 3","mis":"M2-1-u3-X07"},{"t":"4 − 7","mis":"M2-1-u3-X09"}],"asset":{"type":"vert2","top":63,"bottom":27,"op":"-","ans":null}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L06_basic#7','math',2,1,'u3','L06','g2_1_math_u3_L06_basic','lesson_basic','M2-1-u3-C5',2,'ox','auto','65 − 18 = 53 입니다.',ARRAY['M2-1-u3-X07']::text[],true,'{"seq":7,"concept":"M2-1-u3-C5","difficulty":2,"kind":"ox","stem":"65 − 18 = 53 입니다.","explanation":["일의 자리 5에서 8을 뺄 수 없어 십의 자리에서 10을 받아내려요 — 15 − 8 = 7.","십의 자리는 6에서 1을 내려 주어 5, 5 − 1 = 4. 그래서 65 − 18 = 47이에요.","8 − 5처럼 거꾸로 빼지 않아요 — 위의 수에서 아래 수를 빼요."],"variant_rule":{"ar2":{"ask":"value","kind":"s22"}},"answer":"X","mis":"M2-1-u3-X07","reason_options":[{"t":"바르게 계산하면 47이 되니까","correct":true},{"t":"일의 자리는 큰 수에서 작은 수를 빼면 되니까","mis":"M2-1-u3-X07"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L06_basic#8','math',2,1,'u3','L06','g2_1_math_u3_L06_basic','lesson_basic','M2-1-u3-C5',2,'mc','auto','54 − 26 = 28을 덧셈으로 확인하는 식은 어느 것인가요?',ARRAY['M2-1-u3-X16','M2-1-u3-X10']::text[],true,'{"seq":8,"concept":"M2-1-u3-C5","difficulty":2,"kind":"mc","stem":"54 − 26 = 28을 덧셈으로 확인하는 식은 어느 것인가요?","explanation":["뺄셈의 답에 뺀 수를 더하면 처음 수가 돼요.","28 + 26 = 54 — 처음 수 54가 나오니 바르게 뺐어요.","처음 수를 더하면 확인이 되지 않아요."],"variant_rule":{"ar2":{"ask":"verify","kind":"s22"}},"options":[{"t":"28 + 26 = 54","correct":true},{"t":"28 + 54 = 82","mis":"M2-1-u3-X16"},{"t":"54 + 26 = 80","mis":"M2-1-u3-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L06_basic#9','math',2,1,'u3','L06','g2_1_math_u3_L06_basic','lesson_basic','M2-1-u3-C5',2,'mc','auto','도윤이가 42 − 19를 세로셈으로 계산한 것이에요. 잘못 계산한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M2-1-u3-X07','M2-1-u3-X10']::text[],true,'{"seq":9,"concept":"M2-1-u3-C5","difficulty":2,"kind":"mc","stem":"도윤이가 42 − 19를 세로셈으로 계산한 것이에요. 잘못 계산한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"받아내림하고 십의 자리 4를 3으로 줄이지 않았어요.","correct":true},{"t":"일의 자리에서 9 − 2로 거꾸로 뺐어요.","mis":"M2-1-u3-X07"},{"t":"두 수를 더했어요.","mis":"M2-1-u3-X10"}],"explanation":["일의 자리 2에서 9를 뺄 수 없어 10을 받아내려 12 − 9 = 3이에요.","십의 자리는 4가 3으로 줄어 3 − 1 = 2 — 바른 답은 23이에요.","도윤이는 십의 자리를 4 − 1로 계산해 33이라고 썼어요."],"asset":{"type":"vert2","top":42,"bottom":19,"op":"-","ans":33},"variant_rule":{"alt":[{"stem":"도윤이가 63 − 27을 세로셈으로 계산한 것이에요. 잘못 계산한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"일의 자리에서 7 − 3으로 거꾸로 뺐어요.","correct":true},{"t":"받아내림하고 십의 자리를 줄이지 않았어요.","mis":"M2-1-u3-X08"},{"t":"두 수를 더했어요.","mis":"M2-1-u3-X10"}],"explanation":["일의 자리 3에서 7을 뺄 수 없어 10을 받아내려 13 − 7 = 6이에요.","십의 자리는 5 − 2 = 3 — 바른 답은 36이에요.","도윤이는 7 − 3 = 4로 거꾸로 빼서 44라고 썼어요."],"asset":{"type":"vert2","top":63,"bottom":27,"op":"-","ans":44}},{"stem":"도윤이가 50 − 27을 세로셈으로 계산한 것이에요. 잘못 계산한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"받아내림하고 십의 자리 5를 4로 줄이지 않았어요.","correct":true},{"t":"일의 자리에서 7 − 0으로 거꾸로 뺐어요.","mis":"M2-1-u3-X07"},{"t":"두 수를 더했어요.","mis":"M2-1-u3-X10"}],"explanation":["일의 자리 0에서 7을 뺄 수 없어 10을 받아내려 10 − 7 = 3이에요.","십의 자리는 5가 4로 줄어 4 − 2 = 2 — 바른 답은 23이에요.","도윤이는 십의 자리를 5 − 2로 계산해 33이라고 썼어요."],"asset":{"type":"vert2","top":50,"bottom":27,"op":"-","ans":33}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L06_basic#10','math',2,1,'u3','L06','g2_1_math_u3_L06_basic','lesson_basic','M2-1-u3-C5',3,'mc','auto','서아는 색종이 72장을, 곰이는 45장을 모았어요. 서아가 곰이보다 몇 장 더 많이 모았나요?',ARRAY['M2-1-u3-X07','M2-1-u3-X08','M2-1-u3-X10']::text[],true,'{"seq":10,"concept":"M2-1-u3-C5","difficulty":3,"kind":"mc","stem":"서아는 색종이 72장을, 곰이는 45장을 모았어요. 서아가 곰이보다 몇 장 더 많이 모았나요?","explanation":["일의 자리 2에서 5를 뺄 수 없어 십의 자리에서 10을 받아내려요 — 12 − 5 = 7.","십의 자리는 7에서 1을 내려 주어 6, 6 − 4 = 2. 그래서 72 − 45 = 27이에요.","「몇 장 더 많이」는 두 수를 견주는 이야기라 뺄셈이에요 — 27장이에요."],"variant_rule":{"ar2":{"ask":"story","kind":"s22"}},"options":[{"t":"27","correct":true},{"t":"33","mis":"M2-1-u3-X07"},{"t":"37","mis":"M2-1-u3-X08"},{"t":"117","mis":"M2-1-u3-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L06_challenge#1','math',2,1,'u3','L06','g2_1_math_u3_L06_challenge','lesson_challenge','M2-1-u3-C5',2,'mc','auto','80 − 34를 세로셈으로 계산하면 얼마인가요?',ARRAY['M2-1-u3-X07','M2-1-u3-X08']::text[],true,'{"seq":1,"concept":"M2-1-u3-C5","difficulty":2,"kind":"mc","stem":"80 − 34를 세로셈으로 계산하면 얼마인가요?","explanation":["일의 자리 0에서 4를 뺄 수 없어 십의 자리에서 10을 받아내려요 — 10 − 4 = 6.","십의 자리는 8에서 1을 내려 주어 7, 7 − 3 = 4. 그래서 80 − 34 = 46이에요.","4 − 0처럼 거꾸로 빼지 않아요 — 위의 수에서 아래 수를 빼요."],"variant_rule":{"ar2":{"ask":"vert","kind":"s0"}},"options":[{"t":"46","correct":true},{"t":"54","mis":"M2-1-u3-X07"},{"t":"56","mis":"M2-1-u3-X08"}],"asset":{"type":"vert2","top":80,"bottom":34,"op":"-","ans":null}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L06_challenge#2','math',2,1,'u3','L06','g2_1_math_u3_L06_challenge','lesson_challenge','M2-1-u3-C5',2,'mc','auto','71 − 38 = 33을 덧셈으로 확인하는 식은 어느 것인가요?',ARRAY['M2-1-u3-X16','M2-1-u3-X10']::text[],true,'{"seq":2,"concept":"M2-1-u3-C5","difficulty":2,"kind":"mc","stem":"71 − 38 = 33을 덧셈으로 확인하는 식은 어느 것인가요?","explanation":["뺄셈의 답에 뺀 수를 더하면 처음 수가 돼요.","33 + 38 = 71 — 처음 수 71이 나오니 바르게 뺐어요.","처음 수를 더하면 확인이 되지 않아요."],"variant_rule":{"ar2":{"ask":"verify","kind":"s22"}},"options":[{"t":"33 + 38 = 71","correct":true},{"t":"33 + 71 = 104","mis":"M2-1-u3-X16"},{"t":"71 + 38 = 109","mis":"M2-1-u3-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L06_challenge#3','math',2,1,'u3','L06','g2_1_math_u3_L06_challenge','lesson_challenge','M2-1-u3-C5',3,'sa','auto','다예는 도토리 63개를, 하루는 29개를 모았어요. 다예가 하루보다 몇 개 더 많이 모았나요?','{}'::text[],true,'{"seq":3,"concept":"M2-1-u3-C5","difficulty":3,"kind":"sa","stem":"다예는 도토리 63개를, 하루는 29개를 모았어요. 다예가 하루보다 몇 개 더 많이 모았나요?","explanation":["일의 자리 3에서 9를 뺄 수 없어 십의 자리에서 10을 받아내려요 — 13 − 9 = 4.","십의 자리는 6에서 1을 내려 주어 5, 5 − 2 = 3. 그래서 63 − 29 = 34예요.","「몇 개 더 많이」는 두 수를 견주는 이야기라 뺄셈이에요 — 34개예요."],"variant_rule":{"ar2":{"ask":"story","kind":"s22"}},"answer":["34","34개"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L06_challenge#4','math',2,1,'u3','L06','g2_1_math_u3_L06_challenge','lesson_challenge','M2-1-u3-C5',3,'mc','auto','70 − 46을 세로셈으로 계산할 때, 십의 자리에서 계산할 식은 어느 것인가요?',ARRAY['M2-1-u3-X08','M2-1-u3-X10']::text[],true,'{"seq":4,"concept":"M2-1-u3-C5","difficulty":3,"kind":"mc","stem":"70 − 46을 세로셈으로 계산할 때, 십의 자리에서 계산할 식은 어느 것인가요?","explanation":["일의 자리를 계산하려고 십의 자리에서 10을 받아내렸어요.","그래서 십의 자리는 7에서 1이 줄어 6 — 6 − 4를 계산해요.","받아내려 준 자리는 1을 줄이는 것을 잊지 않아요."],"variant_rule":{"ar2":{"ask":"btens","kind":"s0"}},"options":[{"t":"6 − 4","correct":true},{"t":"7 − 4","mis":"M2-1-u3-X08"},{"t":"6 + 4","mis":"M2-1-u3-X10"}],"asset":{"type":"vert2","top":70,"bottom":46,"op":"-","ans":null}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L06_challenge#5','math',2,1,'u3','L06','g2_1_math_u3_L06_challenge','lesson_challenge','M2-1-u3-C5',3,'mc','auto','계산 결과가 나머지 둘과 다른 하나는 어느 것인가요?',ARRAY['M2-1-u3-X08']::text[],true,'{"seq":5,"concept":"M2-1-u3-C5","difficulty":3,"kind":"mc","stem":"계산 결과가 나머지 둘과 다른 하나는 어느 것인가요?","options":[{"t":"70 − 35","correct":true},{"t":"52 − 18","mis":"M2-1-u3-X08"},{"t":"61 − 27","mis":"M2-1-u3-X08"}],"explanation":["52 − 18 = 34, 61 − 27 = 34예요.","70 − 35 = 35라서 하나만 달라요.","받아내림을 바르게 해야 같은 답끼리 찾을 수 있어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 계산 결과가 나머지 둘과 다른 하나는 어느 것인가요?","options":[{"t":"81 − 54","correct":true},{"t":"43 − 17","mis":"M2-1-u3-X08"},{"t":"54 − 28","mis":"M2-1-u3-X08"}],"explanation":["43 − 17 = 26, 54 − 28 = 26이에요.","81 − 54 = 27이라서 하나만 달라요.","받아내림한 뒤 십의 자리를 1 줄여요."]},{"stem":"이번에는 다른 보기예요. 계산 결과가 나머지 둘과 다른 하나는 어느 것인가요?","options":[{"t":"63 − 18","correct":true},{"t":"90 − 46","mis":"M2-1-u3-X08"},{"t":"72 − 28","mis":"M2-1-u3-X08"}],"explanation":["90 − 46 = 44, 72 − 28 = 44예요.","63 − 18 = 45라서 하나만 달라요.","받아내림한 뒤 십의 자리를 1 줄여요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L06_challenge#6','math',2,1,'u3','L06','g2_1_math_u3_L06_challenge','lesson_challenge','M2-1-u3-C5',3,'ox','auto','74 − 38 = 36 입니다.',ARRAY['M2-1-u3-X07']::text[],true,'{"seq":6,"concept":"M2-1-u3-C5","difficulty":3,"kind":"ox","stem":"74 − 38 = 36 입니다.","explanation":["일의 자리 4에서 8을 뺄 수 없어 십의 자리에서 10을 받아내려요 — 14 − 8 = 6.","십의 자리는 7에서 1을 내려 주어 6, 6 − 3 = 3. 그래서 74 − 38 = 36이에요.","8 − 4처럼 거꾸로 빼지 않아요 — 위의 수에서 아래 수를 빼요."],"variant_rule":{"ar2":{"ask":"value","kind":"s22"}},"answer":"O","mis":"M2-1-u3-X07","reason_options":[{"t":"십의 자리에서 받아내린 10을 더해 일의 자리를 뺐으니까","correct":true},{"t":"일의 자리는 큰 수에서 작은 수를 빼면 되니까","mis":"M2-1-u3-X07"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L06_challenge#7','math',2,1,'u3','L06','g2_1_math_u3_L06_challenge','lesson_challenge','M2-1-u3-C5',3,'sa','auto','어떤 수에서 27을 뺐더니 36이 되었어요. 어떤 수는 얼마인가요?','{}'::text[],true,'{"seq":7,"concept":"M2-1-u3-C5","difficulty":3,"kind":"sa","stem":"어떤 수에서 27을 뺐더니 36이 되었어요. 어떤 수는 얼마인가요?","answer":["63"],"explanation":["뺄셈의 답에 뺀 수를 더하면 처음 수가 돼요.","36 + 27 = 63 — 어떤 수는 63이에요.","확인 — 63 − 27 = 36."],"variant_rule":{"alt":[{"stem":"어떤 수에서 18을 뺐더니 45가 되었어요. 어떤 수는 얼마인가요?","answer":["63"],"explanation":["뺄셈의 답에 뺀 수를 더하면 처음 수가 돼요.","45 + 18 = 63 — 어떤 수는 63이에요.","확인 — 63 − 18 = 45."]},{"stem":"어떤 수에서 26을 뺐더니 47이 되었어요. 어떤 수는 얼마인가요?","answer":["73"],"explanation":["뺄셈의 답에 뺀 수를 더하면 처음 수가 돼요.","47 + 26 = 73 — 어떤 수는 73이에요.","확인 — 73 − 26 = 47."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L06_challenge#8','math',2,1,'u3','L06','g2_1_math_u3_L06_challenge','lesson_challenge','M2-1-u3-C5',4,'mc','auto','수 카드 2, 5, 8을 두 장 골라 두 자리 수를 만들어요. 가장 큰 수에서 두 번째로 작은 수를 빼면 얼마인가요?',ARRAY['M2-1-u3-X07','M2-1-u3-X16']::text[],true,'{"seq":8,"concept":"M2-1-u3-C5","difficulty":4,"kind":"mc","stem":"수 카드 2, 5, 8을 두 장 골라 두 자리 수를 만들어요. 가장 큰 수에서 두 번째로 작은 수를 빼면 얼마인가요?","options":[{"t":"57","correct":true},{"t":"63","mis":"M2-1-u3-X07"},{"t":"60","mis":"M2-1-u3-X16"}],"explanation":["가장 큰 수는 85, 가장 작은 수는 25, 두 번째로 작은 수는 28이에요.","85 − 28 = 57이에요.","60은 가장 작은 수 25를 뺀 값 — 「두 번째로 작은」 수를 물었어요."],"variant_rule":{"alt":[{"stem":"수 카드 1, 4, 6을 두 장 골라 두 자리 수를 만들어요. 가장 큰 수에서 두 번째로 작은 수를 빼면 얼마인가요?","options":[{"t":"48","correct":true},{"t":"52","mis":"M2-1-u3-X07"},{"t":"50","mis":"M2-1-u3-X16"}],"explanation":["가장 큰 수는 64, 가장 작은 수는 14, 두 번째로 작은 수는 16이에요.","64 − 16 = 48이에요.","50은 가장 작은 수 14를 뺀 값이에요."]},{"stem":"수 카드 3, 7, 9를 두 장 골라 두 자리 수를 만들어요. 가장 큰 수에서 두 번째로 작은 수를 빼면 얼마인가요?","options":[{"t":"58","correct":true},{"t":"62","mis":"M2-1-u3-X07"},{"t":"60","mis":"M2-1-u3-X16"}],"explanation":["가장 큰 수는 97, 가장 작은 수는 37, 두 번째로 작은 수는 39예요.","97 − 39 = 58이에요.","60은 가장 작은 수 37을 뺀 값이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L06_challenge#9','math',2,1,'u3','L06','g2_1_math_u3_L06_challenge','lesson_challenge','M2-1-u3-C5',4,'essay','teacher','54 − 26을 세로셈으로 계산하는 방법을 설명하고, 덧셈으로 확인해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-1-u3-C5","difficulty":4,"kind":"essay","stem":"54 − 26을 세로셈으로 계산하는 방법을 설명하고, 덧셈으로 확인해 보세요.","answer_guide":{"answer":"일의 자리 4에서 6을 뺄 수 없어 십의 자리에서 10을 받아내려 14 − 6 = 8. 십의 자리는 5가 4로 줄어 4 − 2 = 2. 답은 28. 확인: 28 + 26 = 54.","scoring_points":["일의 자리에서 10을 받아내려 14 − 6 = 8로 계산했는가","십의 자리를 1 줄여 4 − 2 = 2로 계산해 28을 구했는가","답 28에 뺀 수 26을 더해 54가 되는지 확인했는가"]},"explanation":["일의 자리 4에서 6을 뺄 수 없어 받아내림 — 14 − 6 = 8이에요.","십의 자리는 4 − 2 = 2 — 답은 28이에요.","28 + 26 = 54로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L06_challenge#10','math',2,1,'u3','L06','g2_1_math_u3_L06_challenge','lesson_challenge','M2-1-u3-C5',4,'mc','auto','곰이는 딱지 62장 가운데 몇 장을 잃어버려 35장이 남았어요. 잃어버린 딱지는 펭이가 가진 딱지 19장보다 몇 장 많은가요?',ARRAY['M2-1-u3-X16','M2-1-u3-X10']::text[],true,'{"seq":10,"concept":"M2-1-u3-C5","difficulty":4,"kind":"mc","stem":"곰이는 딱지 62장 가운데 몇 장을 잃어버려 35장이 남았어요. 잃어버린 딱지는 펭이가 가진 딱지 19장보다 몇 장 많은가요?","options":[{"t":"8","correct":true},{"t":"16","mis":"M2-1-u3-X16"},{"t":"46","mis":"M2-1-u3-X10"}],"explanation":["잃어버린 딱지는 62 − 35 = 27장이에요.","27은 19보다 27 − 19 = 8 많아요.","16은 남은 35장에서 19를 뺀 값 — 잃어버린 수부터 구해요."],"variant_rule":{"alt":[{"stem":"지우는 구슬 71개 가운데 몇 개를 동생에게 주어 44개가 남았어요. 동생에게 준 구슬은 서아가 가진 구슬 18개보다 몇 개 많은가요?","options":[{"t":"9","correct":true},{"t":"26","mis":"M2-1-u3-X16"},{"t":"45","mis":"M2-1-u3-X10"}],"explanation":["동생에게 준 구슬은 71 − 44 = 27개예요.","27은 18보다 27 − 18 = 9 많아요.","26은 남은 44개에서 18을 뺀 값 — 준 수부터 구해요."]},{"stem":"하루는 색종이 80장 가운데 몇 장을 써서 52장이 남았어요. 쓴 색종이는 다예가 쓴 색종이 13장보다 몇 장 많은가요?","options":[{"t":"15","correct":true},{"t":"39","mis":"M2-1-u3-X16"},{"t":"41","mis":"M2-1-u3-X10"}],"explanation":["하루가 쓴 색종이는 80 − 52 = 28장이에요.","28은 13보다 28 − 13 = 15 많아요.","39는 남은 52장에서 13을 뺀 값 — 쓴 수부터 구해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L08_basic#1','math',2,1,'u3','L08','g2_1_math_u3_L08_basic','lesson_basic','M2-1-u3-C6',1,'mc','auto','24 + 17 − 19를 앞에서부터 차례로 계산하면 얼마인가요?',ARRAY['M2-1-u3-X12']::text[],true,'{"seq":1,"concept":"M2-1-u3-C6","difficulty":1,"kind":"mc","stem":"24 + 17 − 19를 앞에서부터 차례로 계산하면 얼마인가요?","explanation":["① 앞의 두 수부터 — 24 + 17 = 41.","② 41 − 19 = 22예요.","41에서 멈추지 않고 남은 계산까지 해요."],"variant_rule":{"ar2":{"ask":"three"}},"options":[{"t":"22","correct":true},{"t":"41","mis":"M2-1-u3-X12"},{"t":"60","mis":"M2-1-u3-X12"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L08_basic#2','math',2,1,'u3','L08','g2_1_math_u3_L08_basic','lesson_basic','M2-1-u3-C6',1,'mc','auto','42 − 15 + 27에서 먼저 계산할 것은 어느 것인가요?',ARRAY['M2-1-u3-X11']::text[],true,'{"seq":2,"concept":"M2-1-u3-C6","difficulty":1,"kind":"mc","stem":"42 − 15 + 27에서 먼저 계산할 것은 어느 것인가요?","explanation":["세 수의 계산은 앞에서부터 차례로 해요.","먼저 42 − 15 = 27, 그다음 27 + 27 = 54예요.","15 + 27을 먼저 하면 답이 달라져요."],"variant_rule":{"ar2":{"ask":"first"}},"options":[{"t":"42 − 15","correct":true},{"t":"15 + 27","mis":"M2-1-u3-X11"},{"t":"42 + 27","mis":"M2-1-u3-X11"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L08_basic#3','math',2,1,'u3','L08','g2_1_math_u3_L08_basic','lesson_basic','M2-1-u3-C6',1,'sa','auto','42 − 15 + 27을 앞에서부터 차례로 계산하면 얼마인가요?','{}'::text[],true,'{"seq":3,"concept":"M2-1-u3-C6","difficulty":1,"kind":"sa","stem":"42 − 15 + 27을 앞에서부터 차례로 계산하면 얼마인가요?","explanation":["① 앞의 두 수부터 — 42 − 15 = 27.","② 27 + 27 = 54예요.","15 + 27을 먼저 계산하면 안 돼요 — 앞에서부터 차례로."],"variant_rule":{"ar2":{"ask":"three"}},"answer":["54"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L08_basic#4','math',2,1,'u3','L08','g2_1_math_u3_L08_basic','lesson_basic','M2-1-u3-C6',1,'mc','auto','덧셈과 뺄셈이 섞인 세 수의 계산 순서로 바른 것은 어느 것인가요?',ARRAY['M2-1-u3-X11']::text[],true,'{"seq":4,"concept":"M2-1-u3-C6","difficulty":1,"kind":"mc","stem":"덧셈과 뺄셈이 섞인 세 수의 계산 순서로 바른 것은 어느 것인가요?","options":[{"t":"섞여 있어도 앞에서부터 차례로 계산해요.","correct":true},{"t":"덧셈을 먼저 하고 뺄셈을 나중에 해요.","mis":"M2-1-u3-X11"},{"t":"뺄셈을 먼저 하고 덧셈을 나중에 해요.","mis":"M2-1-u3-X11"}],"explanation":["세 수의 계산은 늘 앞에서부터 두 수씩 차례로 해요.","덧셈과 뺄셈이 섞여 있어도 마찬가지예요.","순서를 바꾸면 답이 달라질 수 있어요."],"variant_rule":{"alt":[{"stem":"세 수의 계산은 어떤 순서로 하나요?","options":[{"t":"앞에서부터 차례로","correct":true},{"t":"뒤에서부터 차례로","mis":"M2-1-u3-X11"},{"t":"큰 수끼리 먼저","mis":"M2-1-u3-X11"}],"explanation":["세 수의 계산은 앞에서부터 차례로 해요.","앞의 두 수를 먼저 계산하고, 그 답과 세 번째 수를 계산해요.","뒤에서부터 하거나 큰 수끼리 먼저 하지 않아요."]},{"stem":"28 + 25 − 36을 계산할 때 맨 처음 하는 계산은 어느 것인가요?","options":[{"t":"28 + 25","correct":true},{"t":"25 − 36","mis":"M2-1-u3-X11"},{"t":"28 − 36","mis":"M2-1-u3-X11"}],"explanation":["세 수의 계산은 앞에서부터 해요.","맨 처음에는 28 + 25 = 53을 계산해요.","그다음 53 − 36 = 17이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L08_basic#5','math',2,1,'u3','L08','g2_1_math_u3_L08_basic','lesson_basic','M2-1-u3-C6',2,'sa','auto','28 + 25 − 36을 앞에서부터 차례로 계산하면 얼마인가요?','{}'::text[],true,'{"seq":5,"concept":"M2-1-u3-C6","difficulty":2,"kind":"sa","stem":"28 + 25 − 36을 앞에서부터 차례로 계산하면 얼마인가요?","explanation":["① 앞의 두 수부터 — 28 + 25 = 53.","② 53 − 36 = 17이에요.","53에서 멈추지 않고 남은 계산까지 해요."],"variant_rule":{"ar2":{"ask":"three"}},"answer":["17"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L08_basic#6','math',2,1,'u3','L08','g2_1_math_u3_L08_basic','lesson_basic','M2-1-u3-C6',2,'mc','auto','63 − 28 + 17을 앞에서부터 차례로 계산하면 얼마인가요?',ARRAY['M2-1-u3-X11','M2-1-u3-X12']::text[],true,'{"seq":6,"concept":"M2-1-u3-C6","difficulty":2,"kind":"mc","stem":"63 − 28 + 17을 앞에서부터 차례로 계산하면 얼마인가요?","explanation":["① 앞의 두 수부터 — 63 − 28 = 35.","② 35 + 17 = 52예요.","28 + 17을 먼저 계산하면 안 돼요 — 앞에서부터 차례로."],"variant_rule":{"ar2":{"ask":"three"}},"options":[{"t":"52","correct":true},{"t":"18","mis":"M2-1-u3-X11"},{"t":"35","mis":"M2-1-u3-X12"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L08_basic#7','math',2,1,'u3','L08','g2_1_math_u3_L08_basic','lesson_basic','M2-1-u3-C6',2,'mc','auto','45 + 27 − 19를 앞에서부터 차례로 계산하면 얼마인가요?',ARRAY['M2-1-u3-X12','M2-1-u3-X01']::text[],true,'{"seq":7,"concept":"M2-1-u3-C6","difficulty":2,"kind":"mc","stem":"45 + 27 − 19를 앞에서부터 차례로 계산하면 얼마인가요?","explanation":["① 앞의 두 수부터 — 45 + 27 = 72.","② 72 − 19 = 53이에요.","72에서 멈추지 않고 남은 계산까지 해요."],"variant_rule":{"ar2":{"ask":"three"}},"options":[{"t":"53","correct":true},{"t":"72","mis":"M2-1-u3-X12"},{"t":"91","mis":"M2-1-u3-X12"},{"t":"63","mis":"M2-1-u3-X01"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L08_basic#8','math',2,1,'u3','L08','g2_1_math_u3_L08_basic','lesson_basic','M2-1-u3-C6',2,'error','auto','친구들이 42 − 15 + 27을 계산한 방법이에요. 잘못 계산한 친구는 누구인가요?',ARRAY['M2-1-u3-X11','M2-1-u3-X12']::text[],true,'{"seq":8,"concept":"M2-1-u3-C6","difficulty":2,"kind":"error","stem":"친구들이 42 − 15 + 27을 계산한 방법이에요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"하린: 15 + 27 = 42를 먼저 해서 42 − 42 = 0","correct":true,"mis_target":"M2-1-u3-X11"},{"t":"도윤: 42 − 15 = 27, 27 + 27 = 54","mis":"M2-1-u3-X12"},{"t":"서아: 앞의 두 수부터 계산해서 54","mis":"M2-1-u3-X12"}],"explanation":["세 수의 계산은 앞에서부터 해요.","42 − 15 = 27, 27 + 27 = 54가 바른 답이에요.","하린이는 뒤의 두 수를 먼저 더해서 틀렸어요."],"variant_rule":{"alt":[{"stem":"친구들이 24 + 17 − 19를 계산한 방법이에요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"서아: 24 + 17 = 41이니까 답은 41","correct":true,"mis_target":"M2-1-u3-X12"},{"t":"지우: 24 + 17 = 41, 41 − 19 = 22","mis":"M2-1-u3-X11"},{"t":"하루: 앞에서부터 두 번 계산해서 22","mis":"M2-1-u3-X11"}],"explanation":["세 수의 계산은 두 번 계산해야 끝나요.","24 + 17 = 41, 41 − 19 = 22예요.","서아는 첫 계산에서 멈췄어요."]},{"stem":"친구들이 50 − 23 + 14를 계산한 방법이에요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"민준: 23 + 14 = 37을 먼저 해서 50 − 37 = 13","correct":true,"mis_target":"M2-1-u3-X11"},{"t":"다예: 50 − 23 = 27, 27 + 14 = 41","mis":"M2-1-u3-X12"},{"t":"은우: 앞의 두 수부터 계산해서 41","mis":"M2-1-u3-X12"}],"explanation":["세 수의 계산은 앞에서부터 해요.","50 − 23 = 27, 27 + 14 = 41이 바른 답이에요.","민준이는 뒤의 두 수를 먼저 더해서 틀렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L08_basic#9','math',2,1,'u3','L08','g2_1_math_u3_L08_basic','lesson_basic','M2-1-u3-C6',2,'mc','auto','36 + 18 − 25에서 먼저 계산할 것은 어느 것인가요?',ARRAY['M2-1-u3-X11']::text[],true,'{"seq":9,"concept":"M2-1-u3-C6","difficulty":2,"kind":"mc","stem":"36 + 18 − 25에서 먼저 계산할 것은 어느 것인가요?","explanation":["세 수의 계산은 앞에서부터 차례로 해요.","먼저 36 + 18 = 54, 그다음 54 − 25 = 29예요.","순서를 바꾸지 않고 왼쪽부터 두 수씩 계산해요."],"variant_rule":{"ar2":{"ask":"first"}},"options":[{"t":"36 + 18","correct":true},{"t":"18 − 25","mis":"M2-1-u3-X11"},{"t":"36 − 25","mis":"M2-1-u3-X11"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L08_basic#10','math',2,1,'u3','L08','g2_1_math_u3_L08_basic','lesson_basic','M2-1-u3-C6',3,'sa','auto','곰 15마리가 있었는데 19마리가 더 오고 21마리가 떠났어요. 지금 곰은 몇 마리인가요?','{}'::text[],true,'{"seq":10,"concept":"M2-1-u3-C6","difficulty":3,"kind":"sa","stem":"곰 15마리가 있었는데 19마리가 더 오고 21마리가 떠났어요. 지금 곰은 몇 마리인가요?","answer":["13","13마리"],"explanation":["식은 15 + 19 − 21이에요.","앞에서부터 15 + 19 = 34, 34 − 21 = 13이에요.","더 온 것은 더하고, 떠난 것은 빼요."],"variant_rule":{"alt":[{"stem":"도토리 45개 가운데 17개를 먹고, 다시 24개를 주웠어요. 도토리는 몇 개가 되었나요?","answer":["52","52개"],"explanation":["식은 45 − 17 + 24예요.","앞에서부터 45 − 17 = 28, 28 + 24 = 52예요.","먹은 것은 빼고, 주운 것은 더해요."]},{"stem":"버스에 32명이 타고 있었는데 정류장에서 18명이 내리고 27명이 탔어요. 버스에 탄 사람은 몇 명인가요?","answer":["41","41명"],"explanation":["식은 32 − 18 + 27이에요.","앞에서부터 32 − 18 = 14, 14 + 27 = 41이에요.","내린 사람은 빼고, 탄 사람은 더해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L08_challenge#1','math',2,1,'u3','L08','g2_1_math_u3_L08_challenge','lesson_challenge','M2-1-u3-C6',2,'sa','auto','50 − 23 + 14를 앞에서부터 차례로 계산하면 얼마인가요?','{}'::text[],true,'{"seq":1,"concept":"M2-1-u3-C6","difficulty":2,"kind":"sa","stem":"50 − 23 + 14를 앞에서부터 차례로 계산하면 얼마인가요?","explanation":["① 앞의 두 수부터 — 50 − 23 = 27.","② 27 + 14 = 41이에요.","23 + 14를 먼저 계산하면 안 돼요 — 앞에서부터 차례로."],"variant_rule":{"ar2":{"ask":"three"}},"answer":["41"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L08_challenge#2','math',2,1,'u3','L08','g2_1_math_u3_L08_challenge','lesson_challenge','M2-1-u3-C6',2,'mc','auto','61 − 28 + 15에서 먼저 계산할 것은 어느 것인가요?',ARRAY['M2-1-u3-X11']::text[],true,'{"seq":2,"concept":"M2-1-u3-C6","difficulty":2,"kind":"mc","stem":"61 − 28 + 15에서 먼저 계산할 것은 어느 것인가요?","explanation":["세 수의 계산은 앞에서부터 차례로 해요.","먼저 61 − 28 = 33, 그다음 33 + 15 = 48이에요.","28 + 15를 먼저 하면 답이 달라져요."],"variant_rule":{"ar2":{"ask":"first"}},"options":[{"t":"61 − 28","correct":true},{"t":"28 + 15","mis":"M2-1-u3-X11"},{"t":"61 + 15","mis":"M2-1-u3-X11"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L08_challenge#3','math',2,1,'u3','L08','g2_1_math_u3_L08_challenge','lesson_challenge','M2-1-u3-C6',3,'mc','auto','37 + 46 − 58을 앞에서부터 차례로 계산하면 얼마인가요?',ARRAY['M2-1-u3-X12','M2-1-u3-X01']::text[],true,'{"seq":3,"concept":"M2-1-u3-C6","difficulty":3,"kind":"mc","stem":"37 + 46 − 58을 앞에서부터 차례로 계산하면 얼마인가요?","explanation":["① 앞의 두 수부터 — 37 + 46 = 83.","② 83 − 58 = 25예요.","83에서 멈추지 않고 남은 계산까지 해요."],"variant_rule":{"ar2":{"ask":"three"}},"options":[{"t":"25","correct":true},{"t":"83","mis":"M2-1-u3-X12"},{"t":"141","mis":"M2-1-u3-X12"},{"t":"35","mis":"M2-1-u3-X01"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L08_challenge#4','math',2,1,'u3','L08','g2_1_math_u3_L08_challenge','lesson_challenge','M2-1-u3-C6',3,'mc','auto','72 − 45 + 38을 앞에서부터 차례로 계산하면 얼마인가요?',ARRAY['M2-1-u3-X12']::text[],true,'{"seq":4,"concept":"M2-1-u3-C6","difficulty":3,"kind":"mc","stem":"72 − 45 + 38을 앞에서부터 차례로 계산하면 얼마인가요?","explanation":["① 앞의 두 수부터 — 72 − 45 = 27.","② 27 + 38 = 65예요.","45 + 38을 먼저 계산하면 안 돼요 — 앞에서부터 차례로."],"variant_rule":{"ar2":{"ask":"three"}},"options":[{"t":"65","correct":true},{"t":"27","mis":"M2-1-u3-X12"},{"t":"155","mis":"M2-1-u3-X12"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L08_challenge#5','math',2,1,'u3','L08','g2_1_math_u3_L08_challenge','lesson_challenge','M2-1-u3-C6',3,'mc','auto','계산 결과가 가장 큰 것은 어느 것인가요?',ARRAY['M2-1-u3-X12','M2-1-u3-X11']::text[],true,'{"seq":5,"concept":"M2-1-u3-C6","difficulty":3,"kind":"mc","stem":"계산 결과가 가장 큰 것은 어느 것인가요?","options":[{"t":"45 − 18 + 26","correct":true},{"t":"36 + 27 − 19","mis":"M2-1-u3-X12"},{"t":"64 − 37 + 19","mis":"M2-1-u3-X11"}],"explanation":["45 − 18 + 26 = 53, 36 + 27 − 19 = 44, 64 − 37 + 19 = 46이에요.","가장 큰 것은 45 − 18 + 26이에요.","세 식 모두 앞에서부터 차례로 계산해요."],"variant_rule":{"alt":[{"stem":"계산 결과가 가장 작은 것은 어느 것인가요?","options":[{"t":"52 − 27 + 18","correct":true},{"t":"29 + 34 − 18","mis":"M2-1-u3-X12"},{"t":"73 − 46 + 19","mis":"M2-1-u3-X11"}],"explanation":["52 − 27 + 18 = 43, 29 + 34 − 18 = 45, 73 − 46 + 19 = 46이에요.","가장 작은 것은 52 − 27 + 18이에요.","세 식 모두 앞에서부터 차례로 계산해요."]},{"stem":"이번에는 다른 보기예요. 계산 결과가 가장 큰 것은 어느 것인가요?","options":[{"t":"38 + 47 − 29","correct":true},{"t":"61 − 26 + 18","mis":"M2-1-u3-X11"},{"t":"45 + 28 − 19","mis":"M2-1-u3-X12"}],"explanation":["38 + 47 − 29 = 56, 61 − 26 + 18 = 53, 45 + 28 − 19 = 54예요.","가장 큰 것은 38 + 47 − 29예요.","세 식 모두 앞에서부터 차례로 계산해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L08_challenge#6','math',2,1,'u3','L08','g2_1_math_u3_L08_challenge','lesson_challenge','M2-1-u3-C6',3,'mc','auto','35 ○ 18 ○ 26 = 43이 되도록 ○ 안에 +, −를 차례로 넣은 것은 어느 것인가요?',ARRAY['M2-1-u3-X12']::text[],true,'{"seq":6,"concept":"M2-1-u3-C6","difficulty":3,"kind":"mc","stem":"35 ○ 18 ○ 26 = 43이 되도록 ○ 안에 +, −를 차례로 넣은 것은 어느 것인가요?","options":[{"t":"−, +","correct":true},{"t":"+, −","mis":"M2-1-u3-X12"},{"t":"−, −","mis":"M2-1-u3-X12"}],"explanation":["35 − 18 = 17, 17 + 26 = 43이에요.","그래서 차례로 −, +예요.","35 + 18 − 26 = 27이라 43이 되지 않아요."],"variant_rule":{"alt":[{"stem":"47 ○ 25 ○ 38 = 34가 되도록 ○ 안에 +, −를 차례로 넣은 것은 어느 것인가요?","options":[{"t":"+, −","correct":true},{"t":"−, +","mis":"M2-1-u3-X12"},{"t":"+, +","mis":"M2-1-u3-X12"}],"explanation":["47 + 25 = 72, 72 − 38 = 34예요.","그래서 차례로 +, −예요.","47 − 25 + 38 = 60이라 34가 되지 않아요."]},{"stem":"62 ○ 27 ○ 19 = 54가 되도록 ○ 안에 +, −를 차례로 넣은 것은 어느 것인가요?","options":[{"t":"−, +","correct":true},{"t":"+, −","mis":"M2-1-u3-X12"},{"t":"−, −","mis":"M2-1-u3-X12"}],"explanation":["62 − 27 = 35, 35 + 19 = 54예요.","그래서 차례로 −, +예요.","62 + 27 − 19 = 70이라 54가 되지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L08_challenge#7','math',2,1,'u3','L08','g2_1_math_u3_L08_challenge','lesson_challenge','M2-1-u3-C6',3,'sa','auto','58 + 26 − 39를 앞에서부터 차례로 계산하면 얼마인가요?','{}'::text[],true,'{"seq":7,"concept":"M2-1-u3-C6","difficulty":3,"kind":"sa","stem":"58 + 26 − 39를 앞에서부터 차례로 계산하면 얼마인가요?","explanation":["① 앞의 두 수부터 — 58 + 26 = 84.","② 84 − 39 = 45예요.","84에서 멈추지 않고 남은 계산까지 해요."],"variant_rule":{"ar2":{"ask":"three"}},"answer":["45"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L08_challenge#8','math',2,1,'u3','L08','g2_1_math_u3_L08_challenge','lesson_challenge','M2-1-u3-C6',4,'mc','auto','세 수 26, 48, 35 가운데 두 수를 더하고 남은 수를 빼려고 해요. 계산 결과가 가장 클 때 그 값은 얼마인가요?',ARRAY['M2-1-u3-X16','M2-1-u3-X12']::text[],true,'{"seq":8,"concept":"M2-1-u3-C6","difficulty":4,"kind":"mc","stem":"세 수 26, 48, 35 가운데 두 수를 더하고 남은 수를 빼려고 해요. 계산 결과가 가장 클 때 그 값은 얼마인가요?","options":[{"t":"57","correct":true},{"t":"39","mis":"M2-1-u3-X16"},{"t":"109","mis":"M2-1-u3-X12"}],"explanation":["가장 작은 수를 빼야 결과가 가장 커요.","48 + 35 − 26 = 83 − 26 = 57이에요.","109는 세 수를 모두 더한 값이에요."],"variant_rule":{"alt":[{"stem":"세 수 17, 39, 54 가운데 두 수를 더하고 남은 수를 빼려고 해요. 계산 결과가 가장 클 때 그 값은 얼마인가요?","options":[{"t":"76","correct":true},{"t":"32","mis":"M2-1-u3-X16"},{"t":"110","mis":"M2-1-u3-X12"}],"explanation":["가장 작은 수 17을 빼야 결과가 가장 커요.","39 + 54 − 17 = 93 − 17 = 76이에요.","110은 세 수를 모두 더한 값이에요."]},{"stem":"세 수 23, 38, 45 가운데 두 수를 더하고 남은 수를 빼려고 해요. 계산 결과가 가장 클 때 그 값은 얼마인가요?","options":[{"t":"60","correct":true},{"t":"16","mis":"M2-1-u3-X16"},{"t":"106","mis":"M2-1-u3-X12"}],"explanation":["가장 작은 수 23을 빼야 결과가 가장 커요.","38 + 45 − 23 = 83 − 23 = 60이에요.","106은 세 수를 모두 더한 값이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L08_challenge#9','math',2,1,'u3','L08','g2_1_math_u3_L08_challenge','lesson_challenge','M2-1-u3-C6',4,'essay','teacher','42 − 15 + 27을 계산하는 순서를 설명하고, 순서를 바꾸면 안 되는 까닭을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-1-u3-C6","difficulty":4,"kind":"essay","stem":"42 − 15 + 27을 계산하는 순서를 설명하고, 순서를 바꾸면 안 되는 까닭을 써 보세요.","answer_guide":{"answer":"앞에서부터 42 − 15 = 27, 27 + 27 = 54. 15 + 27을 먼저 계산하면 42 − 42 = 0이 되어 답이 달라지므로 앞에서부터 차례로 계산해야 한다.","scoring_points":["앞에서부터 두 번 계산해 54를 구했는가","순서를 바꾸면(15 + 27 먼저) 답이 달라짐을 보였는가","「앞에서부터 차례로」라는 규칙을 말로 썼는가"]},"explanation":["42 − 15 = 27, 27 + 27 = 54예요.","15 + 27을 먼저 하면 42 − 42 = 0이 돼요.","그래서 세 수의 계산은 앞에서부터 차례로 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L08_challenge#10','math',2,1,'u3','L08','g2_1_math_u3_L08_challenge','lesson_challenge','M2-1-u3-C6',4,'mc','auto','연필이 36자루 있었어요. 동생에게 몇 자루를 주고, 다시 18자루를 샀더니 41자루가 되었어요. 동생에게 준 연필은 몇 자루인가요?',ARRAY['M2-1-u3-X15']::text[],true,'{"seq":10,"concept":"M2-1-u3-C6","difficulty":4,"kind":"mc","stem":"연필이 36자루 있었어요. 동생에게 몇 자루를 주고, 다시 18자루를 샀더니 41자루가 되었어요. 동생에게 준 연필은 몇 자루인가요?","options":[{"t":"13","correct":true},{"t":"23","mis":"M2-1-u3-X15"},{"t":"5","mis":"M2-1-u3-X15"}],"explanation":["36 − □ + 18 = 41이에요.","36 + 18 = 54이니까 54 − □ = 41, □ = 54 − 41 = 13이에요.","확인 — 36 − 13 + 18 = 23 + 18 = 41."],"variant_rule":{"alt":[{"stem":"도토리가 45개 있었어요. 몇 개를 먹고, 다시 27개를 주웠더니 58개가 되었어요. 먹은 도토리는 몇 개인가요?","options":[{"t":"14","correct":true},{"t":"31","mis":"M2-1-u3-X15"},{"t":"13","mis":"M2-1-u3-X15"}],"explanation":["45 − □ + 27 = 58이에요.","45 + 27 = 72이니까 72 − □ = 58, □ = 72 − 58 = 14예요.","확인 — 45 − 14 + 27 = 31 + 27 = 58."]},{"stem":"색종이가 52장 있었어요. 친구에게 몇 장을 주고, 다시 19장을 받았더니 47장이 되었어요. 친구에게 준 색종이는 몇 장인가요?","options":[{"t":"24","correct":true},{"t":"28","mis":"M2-1-u3-X15"},{"t":"5","mis":"M2-1-u3-X15"}],"explanation":["52 − □ + 19 = 47이에요.","52 + 19 = 71이니까 71 − □ = 47, □ = 71 − 47 = 24예요.","확인 — 52 − 24 + 19 = 28 + 19 = 47."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L09_basic#1','math',2,1,'u3','L09','g2_1_math_u3_L09_basic','lesson_basic','M2-1-u3-C7',1,'mc','auto','덧셈식 7 + 3 = 10을 뺄셈식으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-1-u3-X13','M2-1-u3-X14']::text[],true,'{"seq":1,"concept":"M2-1-u3-C7","difficulty":1,"kind":"mc","stem":"덧셈식 7 + 3 = 10을 뺄셈식으로 바르게 나타낸 것은 어느 것인가요?","explanation":["10은 전체, 7과 3은 부분이에요.","전체에서 한 부분을 빼면 다른 부분 — 10 − 7 = 3, 10 − 3 = 7.","뺄셈식은 늘 전체에서 빼요 — 부분끼리 빼지 않아요."],"variant_rule":{"ar2":{"ask":"rel","to":"sub","size":"small"}},"options":[{"t":"10 − 7 = 3","correct":true},{"t":"7 − 3 = 10","mis":"M2-1-u3-X13"},{"t":"3 − 10 = 7","mis":"M2-1-u3-X14"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L09_basic#2','math',2,1,'u3','L09','g2_1_math_u3_L09_basic','lesson_basic','M2-1-u3-C8',1,'mc','auto','5 + □ = 9에서 □에 알맞은 수는 얼마인가요?',ARRAY['M2-1-u3-X15']::text[],true,'{"seq":2,"concept":"M2-1-u3-C8","difficulty":1,"kind":"mc","stem":"5 + □ = 9에서 □에 알맞은 수는 얼마인가요?","explanation":["전체 9, 한 부분 5예요.","다른 부분 □는 9 − 5 = 4예요.","확인 — 5 + 4 = 9."],"variant_rule":{"ar2":{"ask":"box","size":"small"}},"options":[{"t":"4","correct":true},{"t":"14","mis":"M2-1-u3-X15"},{"t":"5","mis":"M2-1-u3-X15"}],"asset":{"type":"bar2","whole":9,"parts":[5,null]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L09_basic#3','math',2,1,'u3','L09','g2_1_math_u3_L09_basic','lesson_basic','M2-1-u3-C7',1,'mc','auto','뺄셈식 13 − 8 = 5를 덧셈식으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-1-u3-X14']::text[],true,'{"seq":3,"concept":"M2-1-u3-C7","difficulty":1,"kind":"mc","stem":"뺄셈식 13 − 8 = 5를 덧셈식으로 바르게 나타낸 것은 어느 것인가요?","explanation":["13은 전체, 8과 5는 부분이에요.","두 부분을 모으면 전체 — 8 + 5 = 13.","덧셈식에서 전체는 = 오른쪽에 와요."],"variant_rule":{"ar2":{"ask":"rel","to":"add","size":"small"}},"options":[{"t":"8 + 5 = 13","correct":true},{"t":"13 + 8 = 5","mis":"M2-1-u3-X14"},{"t":"13 + 5 = 8","mis":"M2-1-u3-X14"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L09_basic#4','math',2,1,'u3','L09','g2_1_math_u3_L09_basic','lesson_basic','M2-1-u3-C8',1,'sa','auto','13 − □ = 8에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":4,"concept":"M2-1-u3-C8","difficulty":1,"kind":"sa","stem":"13 − □ = 8에서 □에 알맞은 수는 얼마인가요?","explanation":["13에서 □만큼 빼서 8이 남았어요.","빼는 수 □는 13 − 8 = 5예요.","확인 — 13 − 5 = 8."],"variant_rule":{"ar2":{"ask":"box","size":"small"}},"answer":["5"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L09_basic#5','math',2,1,'u3','L09','g2_1_math_u3_L09_basic','lesson_basic','M2-1-u3-C8',2,'mc','auto','□ − 7 = 8에서 □에 알맞은 수는 얼마인가요?',ARRAY['M2-1-u3-X15','M2-1-u3-X01']::text[],true,'{"seq":5,"concept":"M2-1-u3-C8","difficulty":2,"kind":"mc","stem":"□ − 7 = 8에서 □에 알맞은 수는 얼마인가요?","explanation":["□에서 7을 뺐더니 8이 남았어요.","처음 수 □는 8 + 7 = 15예요.","확인 — 15 − 7 = 8."],"variant_rule":{"ar2":{"ask":"box","size":"small"}},"options":[{"t":"15","correct":true},{"t":"1","mis":"M2-1-u3-X15"},{"t":"5","mis":"M2-1-u3-X01"}],"asset":{"type":"bar2","whole":null,"parts":[8,7]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L09_basic#6','math',2,1,'u3','L09','g2_1_math_u3_L09_basic','lesson_basic','M2-1-u3-C7',2,'mc','auto','덧셈식 28 + 19 = 47을 뺄셈식으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-1-u3-X13','M2-1-u3-X14','M2-1-u3-X10']::text[],true,'{"seq":6,"concept":"M2-1-u3-C7","difficulty":2,"kind":"mc","stem":"덧셈식 28 + 19 = 47을 뺄셈식으로 바르게 나타낸 것은 어느 것인가요?","explanation":["47은 전체, 28과 19는 부분이에요.","전체에서 한 부분을 빼면 다른 부분 — 47 − 28 = 19, 47 − 19 = 28.","뺄셈식은 늘 전체에서 빼요 — 부분끼리 빼지 않아요."],"variant_rule":{"ar2":{"ask":"rel","to":"sub","size":"big"}},"options":[{"t":"47 − 19 = 28","correct":true},{"t":"28 − 19 = 47","mis":"M2-1-u3-X13"},{"t":"28 − 47 = 19","mis":"M2-1-u3-X14"},{"t":"47 − 28 = 75","mis":"M2-1-u3-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L09_basic#7','math',2,1,'u3','L09','g2_1_math_u3_L09_basic','lesson_basic','M2-1-u3-C8',2,'mc','auto','곰이가 도토리 9개를 가지고 있었는데 몇 개를 더 받았더니 15개가 되었어요. 더 받은 도토리의 수를 □로 하여 식을 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-1-u3-X15']::text[],true,'{"seq":7,"concept":"M2-1-u3-C8","difficulty":2,"kind":"mc","stem":"곰이가 도토리 9개를 가지고 있었는데 몇 개를 더 받았더니 15개가 되었어요. 더 받은 도토리의 수를 □로 하여 식을 바르게 나타낸 것은 어느 것인가요?","explanation":["처음 9개에 □개를 더 받아 15개가 되었어요.","그래서 식은 9 + □ = 15 — □는 15 − 9 = 6이에요.","처음 수와 결과의 수가 식에서 제자리에 있는지 살펴요."],"variant_rule":{"ar2":{"ask":"boxmake"}},"options":[{"t":"9 + □ = 15","correct":true},{"t":"15 + □ = 9","mis":"M2-1-u3-X15"},{"t":"9 + 15 = □","mis":"M2-1-u3-X15"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L09_basic#8','math',2,1,'u3','L09','g2_1_math_u3_L09_basic','lesson_basic','M2-1-u3-C8',2,'sa','auto','27 + □ = 45에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":8,"concept":"M2-1-u3-C8","difficulty":2,"kind":"sa","stem":"27 + □ = 45에서 □에 알맞은 수는 얼마인가요?","explanation":["전체 45, 한 부분 27이에요.","다른 부분 □는 45 − 27 = 18이에요.","확인 — 27 + 18 = 45."],"variant_rule":{"ar2":{"ask":"box","size":"big"}},"answer":["18"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L09_basic#9','math',2,1,'u3','L09','g2_1_math_u3_L09_basic','lesson_basic','M2-1-u3-C8',2,'mc','auto','막대 그림을 보고 □를 구하는 식으로 알맞은 것은 어느 것인가요?',ARRAY['M2-1-u3-X15','M2-1-u3-X13']::text[],true,'{"seq":9,"concept":"M2-1-u3-C8","difficulty":2,"kind":"mc","stem":"막대 그림을 보고 □를 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"15 − 9","correct":true},{"t":"15 + 9","mis":"M2-1-u3-X15"},{"t":"9 − 6","mis":"M2-1-u3-X13"}],"explanation":["전체가 15, 한 부분이 9예요.","다른 부분 □는 전체에서 아는 부분을 빼요 — 15 − 9 = 6이에요.","전체와 부분을 더하지 않아요."],"asset":{"type":"bar2","whole":15,"parts":[9,null]},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 막대 그림을 보고 □를 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"8 + 6","correct":true},{"t":"8 − 6","mis":"M2-1-u3-X13"},{"t":"14 − 6","mis":"M2-1-u3-X14"}],"explanation":["두 부분이 8과 6이고, 전체가 □예요.","전체는 두 부분을 모아요 — 8 + 6 = 14예요.","부분끼리 빼지 않아요."],"asset":{"type":"bar2","whole":null,"parts":[8,6]}},{"stem":"이번에는 다른 보기예요. 막대 그림을 보고 □를 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"23 − 14","correct":true},{"t":"23 + 14","mis":"M2-1-u3-X15"},{"t":"14 − 9","mis":"M2-1-u3-X13"}],"explanation":["전체가 23, 한 부분이 14예요.","다른 부분 □는 23 − 14 = 9예요.","전체와 부분을 더하지 않아요."],"asset":{"type":"bar2","whole":23,"parts":[null,14]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L09_basic#10','math',2,1,'u3','L09','g2_1_math_u3_L09_basic','lesson_basic','M2-1-u3-C8',3,'mc','auto','서아가 색종이 몇 장을 가지고 있었는데 7장을 친구에게 주었더니 8장이 남았어요. 처음에 있던 색종이의 수를 □로 하여 식을 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-1-u3-X14','M2-1-u3-X10']::text[],true,'{"seq":10,"concept":"M2-1-u3-C8","difficulty":3,"kind":"mc","stem":"서아가 색종이 몇 장을 가지고 있었는데 7장을 친구에게 주었더니 8장이 남았어요. 처음에 있던 색종이의 수를 □로 하여 식을 바르게 나타낸 것은 어느 것인가요?","explanation":["처음 □장에서 7장을 주고 8장이 남았어요.","그래서 식은 □ − 7 = 8 — □는 8 + 7 = 15예요.","처음 수 □가 빼는 식의 맨 앞에 와요."],"variant_rule":{"ar2":{"ask":"boxmake"}},"options":[{"t":"□ − 7 = 8","correct":true},{"t":"7 − □ = 8","mis":"M2-1-u3-X14"},{"t":"□ + 7 = 8","mis":"M2-1-u3-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
