INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L09_challenge#2','math',2,1,'u3','L09','g2_1_math_u3_L09_challenge','lesson_challenge','M2-1-u3-C7',2,'mc','auto','뺄셈식 74 − 46 = 28을 덧셈식으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-1-u3-X14']::text[],true,'{"seq":2,"concept":"M2-1-u3-C7","difficulty":2,"kind":"mc","stem":"뺄셈식 74 − 46 = 28을 덧셈식으로 바르게 나타낸 것은 어느 것인가요?","explanation":["74는 전체, 46과 28은 부분이에요.","두 부분을 모으면 전체 — 46 + 28 = 74.","덧셈식에서 전체는 = 오른쪽에 와요."],"variant_rule":{"ar2":{"ask":"rel","to":"add","size":"big"}},"options":[{"t":"28 + 46 = 74","correct":true},{"t":"74 + 46 = 28","mis":"M2-1-u3-X14"},{"t":"74 + 28 = 46","mis":"M2-1-u3-X14"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L09_challenge#3','math',2,1,'u3','L09','g2_1_math_u3_L09_challenge','lesson_challenge','M2-1-u3-C8',3,'mc','auto','63 − □ = 25에서 □에 알맞은 수는 얼마인가요?',ARRAY['M2-1-u3-X15','M2-1-u3-X08']::text[],true,'{"seq":3,"concept":"M2-1-u3-C8","difficulty":3,"kind":"mc","stem":"63 − □ = 25에서 □에 알맞은 수는 얼마인가요?","explanation":["63에서 □만큼 빼서 25가 남았어요.","빼는 수 □는 63 − 25 = 38이에요.","확인 — 63 − 38 = 25."],"variant_rule":{"ar2":{"ask":"box","size":"big"}},"options":[{"t":"38","correct":true},{"t":"88","mis":"M2-1-u3-X15"},{"t":"48","mis":"M2-1-u3-X08"},{"t":"25","mis":"M2-1-u3-X15"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L09_challenge#4','math',2,1,'u3','L09','g2_1_math_u3_L09_challenge','lesson_challenge','M2-1-u3-C8',3,'mc','auto','□ − 34 = 29에서 □에 알맞은 수는 얼마인가요?',ARRAY['M2-1-u3-X15','M2-1-u3-X01']::text[],true,'{"seq":4,"concept":"M2-1-u3-C8","difficulty":3,"kind":"mc","stem":"□ − 34 = 29에서 □에 알맞은 수는 얼마인가요?","explanation":["□에서 34를 뺐더니 29가 남았어요.","처음 수 □는 29 + 34 = 63이에요.","확인 — 63 − 34 = 29."],"variant_rule":{"ar2":{"ask":"box","size":"big"}},"options":[{"t":"63","correct":true},{"t":"5","mis":"M2-1-u3-X15"},{"t":"53","mis":"M2-1-u3-X01"}],"asset":{"type":"bar2","whole":null,"parts":[29,34]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L09_challenge#5','math',2,1,'u3','L09','g2_1_math_u3_L09_challenge','lesson_challenge','M2-1-u3-C7',3,'mc','auto','세 수 6, 8, 14로 만들 수 있는 식이 아닌 것은 어느 것인가요?',ARRAY['M2-1-u3-X13']::text[],true,'{"seq":5,"concept":"M2-1-u3-C7","difficulty":3,"kind":"mc","stem":"세 수 6, 8, 14로 만들 수 있는 식이 아닌 것은 어느 것인가요?","options":[{"t":"8 − 6 = 14","correct":true},{"t":"14 − 6 = 8","mis":"M2-1-u3-X13"},{"t":"14 − 8 = 6","mis":"M2-1-u3-X13"}],"explanation":["14가 전체, 6과 8이 부분이에요.","뺄셈식은 전체에서 부분을 빼요 — 14 − 6 = 8, 14 − 8 = 6.","8 − 6은 2라서 14가 될 수 없어요."],"variant_rule":{"alt":[{"stem":"세 수 9, 17, 26으로 만들 수 있는 식이 아닌 것은 어느 것인가요?","options":[{"t":"17 − 9 = 26","correct":true},{"t":"26 − 9 = 17","mis":"M2-1-u3-X14"},{"t":"26 − 17 = 9","mis":"M2-1-u3-X14"}],"explanation":["26이 전체, 9와 17이 부분이에요.","뺄셈식은 전체에서 부분을 빼요 — 26 − 9 = 17, 26 − 17 = 9.","17 − 9는 8이라서 26이 될 수 없어요."]},{"stem":"세 수 25, 38, 63으로 만들 수 있는 식이 아닌 것은 어느 것인가요?","options":[{"t":"38 − 25 = 63","correct":true},{"t":"63 − 25 = 38","mis":"M2-1-u3-X13"},{"t":"25 + 38 = 63","mis":"M2-1-u3-X13"}],"explanation":["63이 전체, 25와 38이 부분이에요.","25 + 38 = 63, 63 − 25 = 38은 맞는 식이에요.","38 − 25는 13이라서 63이 될 수 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L09_challenge#6','math',2,1,'u3','L09','g2_1_math_u3_L09_challenge','lesson_challenge','M2-1-u3-C8',3,'mc','auto','지우가 도토리 27개를 가지고 있었는데 몇 개를 더 받았더니 45개가 되었어요. 더 받은 도토리의 수를 □로 하여 식을 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-1-u3-X15']::text[],true,'{"seq":6,"concept":"M2-1-u3-C8","difficulty":3,"kind":"mc","stem":"지우가 도토리 27개를 가지고 있었는데 몇 개를 더 받았더니 45개가 되었어요. 더 받은 도토리의 수를 □로 하여 식을 바르게 나타낸 것은 어느 것인가요?","explanation":["처음 27개에 □개를 더 받아 45개가 되었어요.","그래서 식은 27 + □ = 45 — □는 45 − 27 = 18이에요.","처음 수와 결과의 수가 식에서 제자리에 있는지 살펴요."],"variant_rule":{"ar2":{"ask":"boxmake"}},"options":[{"t":"27 + □ = 45","correct":true},{"t":"45 + □ = 27","mis":"M2-1-u3-X15"},{"t":"27 + 45 = □","mis":"M2-1-u3-X15"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L09_challenge#7','math',2,1,'u3','L09','g2_1_math_u3_L09_challenge','lesson_challenge','M2-1-u3-C8',3,'sa','auto','어떤 수에 18을 더했더니 52가 되었어요. 어떤 수를 □로 하여 식을 만들고, □의 값을 구하세요.','{}'::text[],true,'{"seq":7,"concept":"M2-1-u3-C8","difficulty":3,"kind":"sa","stem":"어떤 수에 18을 더했더니 52가 되었어요. 어떤 수를 □로 하여 식을 만들고, □의 값을 구하세요.","answer":["34"],"explanation":["식은 □ + 18 = 52예요.","□ = 52 − 18 = 34예요.","확인 — 34 + 18 = 52."],"variant_rule":{"alt":[{"stem":"어떤 수에서 26을 뺐더니 37이 되었어요. 어떤 수를 □로 하여 식을 만들고, □의 값을 구하세요.","answer":["63"],"explanation":["식은 □ − 26 = 37이에요.","□ = 37 + 26 = 63이에요.","확인 — 63 − 26 = 37."]},{"stem":"45에서 어떤 수를 뺐더니 17이 되었어요. 어떤 수를 □로 하여 식을 만들고, □의 값을 구하세요.","answer":["28"],"explanation":["식은 45 − □ = 17이에요.","□ = 45 − 17 = 28이에요.","확인 — 45 − 28 = 17."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L09_challenge#8','math',2,1,'u3','L09','g2_1_math_u3_L09_challenge','lesson_challenge','M2-1-u3-C8',4,'mc','auto','□ 안에 알맞은 수가 가장 큰 것은 어느 것인가요?',ARRAY['M2-1-u3-X15']::text[],true,'{"seq":8,"concept":"M2-1-u3-C8","difficulty":4,"kind":"mc","stem":"□ 안에 알맞은 수가 가장 큰 것은 어느 것인가요?","options":[{"t":"□ − 19 = 9","correct":true},{"t":"□ + 18 = 45","mis":"M2-1-u3-X15"},{"t":"52 − □ = 26","mis":"M2-1-u3-X15"}],"explanation":["□ + 18 = 45에서 □ = 27, 52 − □ = 26에서 □ = 26이에요.","□ − 19 = 9에서 □ = 9 + 19 = 28 — 가장 커요.","□를 구한 뒤 식에 넣어 확인해요."],"variant_rule":{"alt":[{"stem":"□ 안에 알맞은 수가 가장 작은 것은 어느 것인가요?","options":[{"t":"70 − □ = 47","correct":true},{"t":"36 + □ = 61","mis":"M2-1-u3-X15"},{"t":"□ − 15 = 9","mis":"M2-1-u3-X15"}],"explanation":["36 + □ = 61에서 □ = 25, □ − 15 = 9에서 □ = 24예요.","70 − □ = 47에서 □ = 23 — 가장 작아요.","□를 구한 뒤 식에 넣어 확인해요."]},{"stem":"이번에는 다른 보기예요. □ 안에 알맞은 수가 가장 큰 것은 어느 것인가요?","options":[{"t":"□ + 29 = 64","correct":true},{"t":"81 − □ = 47","mis":"M2-1-u3-X15"},{"t":"□ − 18 = 15","mis":"M2-1-u3-X15"}],"explanation":["□ + 29 = 64에서 □ = 35예요.","81 − □ = 47에서 □ = 34, □ − 18 = 15에서 □ = 33이에요.","그래서 가장 큰 것은 □ + 29 = 64예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L09_challenge#9','math',2,1,'u3','L09','g2_1_math_u3_L09_challenge','lesson_challenge','M2-1-u3-C8',4,'essay','teacher','7 + □ = 15에서 □를 구하는 방법을 덧셈과 뺄셈의 관계로 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-1-u3-C8","difficulty":4,"kind":"essay","stem":"7 + □ = 15에서 □를 구하는 방법을 덧셈과 뺄셈의 관계로 설명해 보세요.","answer_guide":{"answer":"15는 전체, 7과 □는 부분이다. 전체에서 아는 부분을 빼면 다른 부분이므로 □ = 15 − 7 = 8. 확인: 7 + 8 = 15.","scoring_points":["15를 전체, 7과 □를 부분으로 보았는가","뺄셈식 15 − 7 = 8로 □를 구했는가","구한 값을 식에 넣어 확인했는가"]},"explanation":["15가 전체, 7과 □가 부분이에요.","□ = 15 − 7 = 8이에요.","7 + 8 = 15로 확인해요."],"asset":{"type":"bar2","whole":15,"parts":[7,null]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_L09_challenge#10','math',2,1,'u3','L09','g2_1_math_u3_L09_challenge','lesson_challenge','M2-1-u3-C8',4,'mc','auto','어떤 수에 28을 더해야 할 것을 잘못하여 82를 더했더니 95가 되었어요. 바르게 계산하면 얼마인가요?',ARRAY['M2-1-u3-X16','M2-1-u3-X15']::text[],true,'{"seq":10,"concept":"M2-1-u3-C8","difficulty":4,"kind":"mc","stem":"어떤 수에 28을 더해야 할 것을 잘못하여 82를 더했더니 95가 되었어요. 바르게 계산하면 얼마인가요?","options":[{"t":"41","correct":true},{"t":"13","mis":"M2-1-u3-X16"},{"t":"67","mis":"M2-1-u3-X15"}],"explanation":["□ + 82 = 95이니 어떤 수 □ = 95 − 82 = 13이에요.","바르게 계산하면 13 + 28 = 41이에요.","13은 어떤 수 — 물음은 바르게 계산한 값이에요."],"variant_rule":{"alt":[{"stem":"어떤 수에서 16을 빼야 할 것을 잘못하여 61을 뺐더니 23이 되었어요. 바르게 계산하면 얼마인가요?","options":[{"t":"68","correct":true},{"t":"84","mis":"M2-1-u3-X16"},{"t":"39","mis":"M2-1-u3-X15"}],"explanation":["□ − 61 = 23이니 어떤 수 □ = 23 + 61 = 84예요.","바르게 계산하면 84 − 16 = 68이에요.","84는 어떤 수 — 물음은 바르게 계산한 값이에요."]},{"stem":"어떤 수에 19를 더해야 할 것을 잘못하여 91을 더했더니 97이 되었어요. 바르게 계산하면 얼마인가요?","options":[{"t":"25","correct":true},{"t":"6","mis":"M2-1-u3-X16"},{"t":"78","mis":"M2-1-u3-X15"}],"explanation":["□ + 91 = 97이니 어떤 수 □ = 97 − 91 = 6이에요.","바르게 계산하면 6 + 19 = 25예요.","6은 어떤 수 — 물음은 바르게 계산한 값이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_a#1','math',2,1,'u3','','g2_1_math_u3_review_a','unit_review','M2-1-u3-C1',1,'mc','auto','26 + 7은 얼마인가요?',ARRAY['M2-1-u3-X01','M2-1-u3-X03']::text[],true,'{"seq":1,"concept":"M2-1-u3-C1","difficulty":1,"kind":"mc","stem":"26 + 7은 얼마인가요?","explanation":["일의 자리 6 + 7 = 13 — 3을 쓰고 10은 십의 자리로 받아올려요.","십의 자리 2 + 1 = 3. 그래서 26 + 7 = 33이에요.","받아올림한 1은 십의 자리에서 꼭 더해요 — 빠뜨리면 10이 작아져요."],"variant_rule":{"ar2":{"ask":"value","kind":"a21"}},"options":[{"t":"33","correct":true},{"t":"23","mis":"M2-1-u3-X01"},{"t":"96","mis":"M2-1-u3-X03"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_a#2','math',2,1,'u3','','g2_1_math_u3_review_a','unit_review','M2-1-u3-C2',1,'sa','auto','38 + 27은 얼마인가요?','{}'::text[],true,'{"seq":2,"concept":"M2-1-u3-C2","difficulty":1,"kind":"sa","stem":"38 + 27은 얼마인가요?","explanation":["일의 자리 8 + 7 = 15 — 5를 쓰고 10은 십의 자리로 받아올려요.","십의 자리 3 + 2 + 1 = 6. 그래서 38 + 27 = 65예요.","받아올림한 1은 십의 자리에서 꼭 더해요 — 빠뜨리면 10이 작아져요."],"variant_rule":{"ar2":{"ask":"value","kind":"a22"}},"answer":["65"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_a#3','math',2,1,'u3','','g2_1_math_u3_review_a','unit_review','M2-1-u3-C3',1,'mc','auto','58 + 46을 세로셈으로 계산하면 얼마인가요?',ARRAY['M2-1-u3-X01','M2-1-u3-X05']::text[],true,'{"seq":3,"concept":"M2-1-u3-C3","difficulty":1,"kind":"mc","stem":"58 + 46을 세로셈으로 계산하면 얼마인가요?","explanation":["일의 자리 8 + 6 = 14 — 4를 쓰고 10은 십의 자리로 받아올려요.","십의 자리 5 + 4 + 1 = 10 — 10이 넘어 백의 자리로 올려요. 그래서 58 + 46 = 104예요.","십의 자리 합이 10을 넘으면 백의 자리에 1을 써요."],"variant_rule":{"ar2":{"ask":"vert","kind":"a22h"}},"options":[{"t":"104","correct":true},{"t":"94","mis":"M2-1-u3-X01"},{"t":"4","mis":"M2-1-u3-X05"}],"asset":{"type":"vert2","top":58,"bottom":46,"op":"+","ans":null}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_a#4','math',2,1,'u3','','g2_1_math_u3_review_a','unit_review','M2-1-u3-C4',1,'mc','auto','34 − 8은 얼마인가요?',ARRAY['M2-1-u3-X07','M2-1-u3-X08']::text[],true,'{"seq":4,"concept":"M2-1-u3-C4","difficulty":1,"kind":"mc","stem":"34 − 8은 얼마인가요?","explanation":["일의 자리 4에서 8을 뺄 수 없어 십의 자리에서 10을 받아내려요 — 14 − 8 = 6.","십의 자리는 3에서 1을 내려 주어 2. 그래서 34 − 8 = 26이에요.","8 − 4처럼 거꾸로 빼지 않아요 — 위의 수에서 아래 수를 빼요."],"variant_rule":{"ar2":{"ask":"value","kind":"s21"}},"options":[{"t":"26","correct":true},{"t":"34","mis":"M2-1-u3-X07"},{"t":"36","mis":"M2-1-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_a#5','math',2,1,'u3','','g2_1_math_u3_review_a','unit_review','M2-1-u3-C5',1,'mc','auto','54 − 26을 세로셈으로 계산하면 얼마인가요?',ARRAY['M2-1-u3-X07','M2-1-u3-X08']::text[],true,'{"seq":5,"concept":"M2-1-u3-C5","difficulty":1,"kind":"mc","stem":"54 − 26을 세로셈으로 계산하면 얼마인가요?","explanation":["일의 자리 4에서 6을 뺄 수 없어 십의 자리에서 10을 받아내려요 — 14 − 6 = 8.","십의 자리는 5에서 1을 내려 주어 4, 4 − 2 = 2. 그래서 54 − 26 = 28이에요.","6 − 4처럼 거꾸로 빼지 않아요 — 위의 수에서 아래 수를 빼요."],"variant_rule":{"ar2":{"ask":"vert","kind":"s22"}},"options":[{"t":"28","correct":true},{"t":"32","mis":"M2-1-u3-X07"},{"t":"38","mis":"M2-1-u3-X08"}],"asset":{"type":"vert2","top":54,"bottom":26,"op":"-","ans":null}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_a#6','math',2,1,'u3','','g2_1_math_u3_review_a','unit_review','M2-1-u3-C6',1,'mc','auto','42 − 15 + 27에서 먼저 계산할 것은 어느 것인가요?',ARRAY['M2-1-u3-X11']::text[],true,'{"seq":6,"concept":"M2-1-u3-C6","difficulty":1,"kind":"mc","stem":"42 − 15 + 27에서 먼저 계산할 것은 어느 것인가요?","explanation":["세 수의 계산은 앞에서부터 차례로 해요.","먼저 42 − 15 = 27, 그다음 27 + 27 = 54예요.","15 + 27을 먼저 하면 답이 달라져요."],"variant_rule":{"ar2":{"ask":"first"}},"options":[{"t":"42 − 15","correct":true},{"t":"15 + 27","mis":"M2-1-u3-X11"},{"t":"42 + 27","mis":"M2-1-u3-X11"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_a#7','math',2,1,'u3','','g2_1_math_u3_review_a','unit_review','M2-1-u3-C7',1,'mc','auto','덧셈식 8 + 5 = 13을 뺄셈식으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-1-u3-X13','M2-1-u3-X14']::text[],true,'{"seq":7,"concept":"M2-1-u3-C7","difficulty":1,"kind":"mc","stem":"덧셈식 8 + 5 = 13을 뺄셈식으로 바르게 나타낸 것은 어느 것인가요?","explanation":["13은 전체, 8과 5는 부분이에요.","전체에서 한 부분을 빼면 다른 부분 — 13 − 8 = 5, 13 − 5 = 8.","뺄셈식은 늘 전체에서 빼요 — 부분끼리 빼지 않아요."],"variant_rule":{"ar2":{"ask":"rel","to":"sub","size":"small"}},"options":[{"t":"13 − 8 = 5","correct":true},{"t":"8 − 5 = 13","mis":"M2-1-u3-X13"},{"t":"5 − 13 = 8","mis":"M2-1-u3-X14"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_a#8','math',2,1,'u3','','g2_1_math_u3_review_a','unit_review','M2-1-u3-C8',1,'mc','auto','6 + □ = 13에서 □에 알맞은 수는 얼마인가요?',ARRAY['M2-1-u3-X15','M2-1-u3-X08']::text[],true,'{"seq":8,"concept":"M2-1-u3-C8","difficulty":1,"kind":"mc","stem":"6 + □ = 13에서 □에 알맞은 수는 얼마인가요?","explanation":["전체 13, 한 부분 6이에요.","다른 부분 □는 13 − 6 = 7이에요.","확인 — 6 + 7 = 13."],"variant_rule":{"ar2":{"ask":"box","size":"small"}},"options":[{"t":"7","correct":true},{"t":"19","mis":"M2-1-u3-X15"},{"t":"17","mis":"M2-1-u3-X08"}],"asset":{"type":"bar2","whole":13,"parts":[6,null]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_a#9','math',2,1,'u3','','g2_1_math_u3_review_a','unit_review','M2-1-u3-C1',2,'mc','auto','18 + 5를 계산할 때, 18에 얼마를 더하면 20이 되나요?',ARRAY['M2-1-u3-X04']::text[],true,'{"seq":9,"concept":"M2-1-u3-C1","difficulty":2,"kind":"mc","stem":"18 + 5를 계산할 때, 18에 얼마를 더하면 20이 되나요?","explanation":["18에서 20까지는 2만큼 더 가야 해요.","18 + 2 = 20 — 먼저 몇십을 만들어요.","남은 3을 더하면 20 + 3 = 23이에요."],"variant_rule":{"ar2":{"ask":"fill","kind":"a21"}},"options":[{"t":"2","correct":true},{"t":"3","mis":"M2-1-u3-X04"},{"t":"8","mis":"M2-1-u3-X04"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_a#10','math',2,1,'u3','','g2_1_math_u3_review_a','unit_review','M2-1-u3-C3',2,'mc','auto','38 + 25를 세로셈으로 계산할 때, 십의 자리에서 계산할 식은 어느 것인가요?',ARRAY['M2-1-u3-X01','M2-1-u3-X06']::text[],true,'{"seq":10,"concept":"M2-1-u3-C3","difficulty":2,"kind":"mc","stem":"38 + 25를 세로셈으로 계산할 때, 십의 자리에서 계산할 식은 어느 것인가요?","explanation":["일의 자리 8 + 5 = 13 — 10을 십의 자리로 받아올려요.","받아올림한 10은 십의 자리에서는 1이에요. 그래서 십의 자리 식은 3 + 2 + 1이에요.","받아올린 수는 십의 자리에서 「1」로 더해요 — 10을 더하지 않아요."],"variant_rule":{"ar2":{"ask":"carry","kind":"a22"}},"options":[{"t":"3 + 2 + 1","correct":true},{"t":"3 + 2","mis":"M2-1-u3-X01"},{"t":"3 + 2 + 10","mis":"M2-1-u3-X06"}],"asset":{"type":"vert2","top":38,"bottom":25,"op":"+","ans":null}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_a#11','math',2,1,'u3','','g2_1_math_u3_review_a','unit_review','M2-1-u3-C5',2,'mc','auto','52 − 18을 세로셈으로 계산할 때, 일의 자리에서 계산할 식은 어느 것인가요?',ARRAY['M2-1-u3-X07','M2-1-u3-X09']::text[],true,'{"seq":11,"concept":"M2-1-u3-C5","difficulty":2,"kind":"mc","stem":"52 − 18을 세로셈으로 계산할 때, 일의 자리에서 계산할 식은 어느 것인가요?","explanation":["일의 자리 2에서 8을 뺄 수 없어요.","십의 자리에서 10을 받아내리면 일의 자리는 12 — 12 − 8을 계산해요.","8 − 2처럼 아래 수에서 위의 수를 빼지 않아요."],"variant_rule":{"ar2":{"ask":"borrow","kind":"s22"}},"options":[{"t":"12 − 8","correct":true},{"t":"8 − 2","mis":"M2-1-u3-X07"},{"t":"3 − 8","mis":"M2-1-u3-X09"}],"asset":{"type":"vert2","top":52,"bottom":18,"op":"-","ans":null}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_a#12','math',2,1,'u3','','g2_1_math_u3_review_a','unit_review','M2-1-u3-C3',2,'ox','auto','75 + 74 = 49 입니다.',ARRAY['M2-1-u3-X01']::text[],true,'{"seq":12,"concept":"M2-1-u3-C3","difficulty":2,"kind":"ox","stem":"75 + 74 = 49 입니다.","explanation":["일의 자리 5 + 4 = 9예요.","십의 자리 7 + 7 = 14 — 10이 넘어 백의 자리로 올려요. 그래서 75 + 74 = 149예요.","십의 자리 합이 10을 넘으면 백의 자리에 1을 써요."],"variant_rule":{"ar2":{"ask":"value","kind":"a22h"}},"answer":"X","mis":"M2-1-u3-X05","reason_options":[{"t":"바르게 계산하면 149가 되니까","correct":true},{"t":"일의 자리끼리, 십의 자리끼리 더하기만 하면 되니까","mis":"M2-1-u3-X01"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_a#13','math',2,1,'u3','','g2_1_math_u3_review_a','unit_review','M2-1-u3-C6',2,'sa','auto','50 − 23 + 14를 앞에서부터 차례로 계산하면 얼마인가요?','{}'::text[],true,'{"seq":13,"concept":"M2-1-u3-C6","difficulty":2,"kind":"sa","stem":"50 − 23 + 14를 앞에서부터 차례로 계산하면 얼마인가요?","explanation":["① 앞의 두 수부터 — 50 − 23 = 27.","② 27 + 14 = 41이에요.","23 + 14를 먼저 계산하면 안 돼요 — 앞에서부터 차례로."],"variant_rule":{"ar2":{"ask":"three"}},"answer":["41"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_a#14','math',2,1,'u3','','g2_1_math_u3_review_a','unit_review','M2-1-u3-C5',2,'mc','auto','54 − 26 = 28을 덧셈으로 확인하는 식은 어느 것인가요?',ARRAY['M2-1-u3-X16','M2-1-u3-X10']::text[],true,'{"seq":14,"concept":"M2-1-u3-C5","difficulty":2,"kind":"mc","stem":"54 − 26 = 28을 덧셈으로 확인하는 식은 어느 것인가요?","explanation":["뺄셈의 답에 뺀 수를 더하면 처음 수가 돼요.","28 + 26 = 54 — 처음 수 54가 나오니 바르게 뺐어요.","처음 수를 더하면 확인이 되지 않아요."],"variant_rule":{"ar2":{"ask":"verify","kind":"s22"}},"options":[{"t":"28 + 26 = 54","correct":true},{"t":"28 + 54 = 82","mis":"M2-1-u3-X16"},{"t":"54 + 26 = 80","mis":"M2-1-u3-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_a#15','math',2,1,'u3','','g2_1_math_u3_review_a','unit_review','M2-1-u3-C5',2,'mc','auto','지우가 색종이 63장을 가지고 있었는데 27장을 친구에게 주었어요. 남은 색종이는 몇 장인가요?',ARRAY['M2-1-u3-X07','M2-1-u3-X08']::text[],true,'{"seq":15,"concept":"M2-1-u3-C5","difficulty":2,"kind":"mc","stem":"지우가 색종이 63장을 가지고 있었는데 27장을 친구에게 주었어요. 남은 색종이는 몇 장인가요?","explanation":["일의 자리 3에서 7을 뺄 수 없어 십의 자리에서 10을 받아내려요 — 13 − 7 = 6.","십의 자리는 6에서 1을 내려 주어 5, 5 − 2 = 3. 그래서 63 − 27 = 36이에요.","「남은」은 덜어 내는 이야기라 뺄셈이에요 — 36장이에요."],"variant_rule":{"ar2":{"ask":"story","kind":"s22"}},"options":[{"t":"36","correct":true},{"t":"44","mis":"M2-1-u3-X07"},{"t":"46","mis":"M2-1-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_a#16','math',2,1,'u3','','g2_1_math_u3_review_a','unit_review','M2-1-u3-C8',2,'sa','auto','27 + □ = 45에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":16,"concept":"M2-1-u3-C8","difficulty":2,"kind":"sa","stem":"27 + □ = 45에서 □에 알맞은 수는 얼마인가요?","explanation":["전체 45, 한 부분 27이에요.","다른 부분 □는 45 − 27 = 18이에요.","확인 — 27 + 18 = 45."],"variant_rule":{"ar2":{"ask":"box","size":"big"}},"answer":["18"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_a#17','math',2,1,'u3','','g2_1_math_u3_review_a','unit_review','M2-1-u3-C3',3,'sa','auto','다예가 색종이 58장을 가지고 있었는데 46장을 더 받았어요. 색종이는 모두 몇 장인가요?','{}'::text[],true,'{"seq":17,"concept":"M2-1-u3-C3","difficulty":3,"kind":"sa","stem":"다예가 색종이 58장을 가지고 있었는데 46장을 더 받았어요. 색종이는 모두 몇 장인가요?","explanation":["일의 자리 8 + 6 = 14 — 4를 쓰고 10은 십의 자리로 받아올려요.","십의 자리 5 + 4 + 1 = 10 — 10이 넘어 백의 자리로 올려요. 그래서 58 + 46 = 104예요.","「모두」는 모으는 이야기라 덧셈이에요 — 104장이에요."],"variant_rule":{"ar2":{"ask":"story","kind":"a22h"}},"answer":["104","104장"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_a#18','math',2,1,'u3','','g2_1_math_u3_review_a','unit_review','M2-1-u3-C6',3,'mc','auto','37 + 46 − 58을 앞에서부터 차례로 계산하면 얼마인가요?',ARRAY['M2-1-u3-X12','M2-1-u3-X01']::text[],true,'{"seq":18,"concept":"M2-1-u3-C6","difficulty":3,"kind":"mc","stem":"37 + 46 − 58을 앞에서부터 차례로 계산하면 얼마인가요?","explanation":["① 앞의 두 수부터 — 37 + 46 = 83.","② 83 − 58 = 25예요.","83에서 멈추지 않고 남은 계산까지 해요."],"variant_rule":{"ar2":{"ask":"three"}},"options":[{"t":"25","correct":true},{"t":"83","mis":"M2-1-u3-X12"},{"t":"141","mis":"M2-1-u3-X12"},{"t":"35","mis":"M2-1-u3-X01"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_a#19','math',2,1,'u3','','g2_1_math_u3_review_a','unit_review','M2-1-u3-C8',3,'mc','auto','서아가 색종이 27장을 가지고 있었는데 몇 장을 더 받았더니 45장이 되었어요. 더 받은 색종이의 수를 □로 하여 식을 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-1-u3-X15']::text[],true,'{"seq":19,"concept":"M2-1-u3-C8","difficulty":3,"kind":"mc","stem":"서아가 색종이 27장을 가지고 있었는데 몇 장을 더 받았더니 45장이 되었어요. 더 받은 색종이의 수를 □로 하여 식을 바르게 나타낸 것은 어느 것인가요?","explanation":["처음 27장에 □장을 더 받아 45장이 되었어요.","그래서 식은 27 + □ = 45 — □는 45 − 27 = 18이에요.","처음 수와 결과의 수가 식에서 제자리에 있는지 살펴요."],"variant_rule":{"ar2":{"ask":"boxmake"}},"options":[{"t":"27 + □ = 45","correct":true},{"t":"45 + □ = 27","mis":"M2-1-u3-X15"},{"t":"27 + 45 = □","mis":"M2-1-u3-X15"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_a#20','math',2,1,'u3','','g2_1_math_u3_review_a','unit_review','M2-1-u3-C3',3,'mc','auto','지우가 58 + 46을 세로셈으로 계산한 것이에요. 잘못 계산한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M2-1-u3-X02','M2-1-u3-X03']::text[],false,'{"seq":20,"concept":"M2-1-u3-C3","difficulty":3,"kind":"mc","stem":"지우가 58 + 46을 세로셈으로 계산한 것이에요. 잘못 계산한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"받아올림한 1을 십의 자리에서 더하지 않았어요.","correct":true},{"t":"일의 자리 8 + 6을 잘못 더했어요.","mis":"M2-1-u3-X02"},{"t":"두 수의 자리를 맞추지 않았어요.","mis":"M2-1-u3-X03"}],"explanation":["일의 자리 8 + 6 = 14 — 4를 쓰고 1을 받아올려요.","십의 자리 5 + 4 + 1 = 10 — 바른 답은 104예요.","지우는 받아올림한 1을 더하지 않아 94라고 썼어요."],"asset":{"type":"vert2","top":58,"bottom":46,"op":"+","ans":94}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_a#21','math',2,1,'u3','','g2_1_math_u3_review_a','unit_review','M2-1-u3-C7',3,'mc','auto','뺄셈식 74 − 46 = 28을 덧셈식으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-1-u3-X14']::text[],true,'{"seq":21,"concept":"M2-1-u3-C7","difficulty":3,"kind":"mc","stem":"뺄셈식 74 − 46 = 28을 덧셈식으로 바르게 나타낸 것은 어느 것인가요?","explanation":["74는 전체, 46과 28은 부분이에요.","두 부분을 모으면 전체 — 46 + 28 = 74.","덧셈식에서 전체는 = 오른쪽에 와요."],"variant_rule":{"ar2":{"ask":"rel","to":"add","size":"big"}},"options":[{"t":"46 + 28 = 74","correct":true},{"t":"74 + 46 = 28","mis":"M2-1-u3-X14"},{"t":"74 + 28 = 46","mis":"M2-1-u3-X14"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_a#22','math',2,1,'u3','','g2_1_math_u3_review_a','unit_review','M2-1-u3-C6',3,'sa','auto','곰 15마리가 있었는데 19마리가 더 오고 21마리가 떠났어요. 지금 곰은 몇 마리인가요?','{}'::text[],false,'{"seq":22,"concept":"M2-1-u3-C6","difficulty":3,"kind":"sa","stem":"곰 15마리가 있었는데 19마리가 더 오고 21마리가 떠났어요. 지금 곰은 몇 마리인가요?","answer":["13","13마리"],"explanation":["식은 15 + 19 − 21이에요.","15 + 19 = 34, 34 − 21 = 13이에요.","더 온 것은 더하고 떠난 것은 빼요 — 앞에서부터."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_a#23','math',2,1,'u3','','g2_1_math_u3_review_a','unit_review','M2-1-u3-C1',4,'mc','auto','어떤 수에 9를 더해야 할 것을 잘못하여 9를 뺐더니 24가 되었어요. 바르게 계산하면 얼마인가요?',ARRAY['M2-1-u3-X16','M2-1-u3-X10']::text[],false,'{"seq":23,"concept":"M2-1-u3-C1","difficulty":4,"kind":"mc","stem":"어떤 수에 9를 더해야 할 것을 잘못하여 9를 뺐더니 24가 되었어요. 바르게 계산하면 얼마인가요?","options":[{"t":"42","correct":true},{"t":"33","mis":"M2-1-u3-X16"},{"t":"15","mis":"M2-1-u3-X10"}],"explanation":["9를 뺐더니 24니까 어떤 수는 24 + 9 = 33이에요.","바르게 계산하면 33 + 9 = 42예요.","33은 어떤 수 — 물음은 바르게 계산한 값이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_a#24','math',2,1,'u3','','g2_1_math_u3_review_a','unit_review','M2-1-u3-C3',4,'mc','auto','수 카드 2, 5, 7, 9를 한 번씩 모두 써서 두 자리 수 두 개를 만들었어요. 두 수의 합이 가장 클 때, 그 합은 얼마인가요?',ARRAY['M2-1-u3-X16']::text[],false,'{"seq":24,"concept":"M2-1-u3-C3","difficulty":4,"kind":"mc","stem":"수 카드 2, 5, 7, 9를 한 번씩 모두 써서 두 자리 수 두 개를 만들었어요. 두 수의 합이 가장 클 때, 그 합은 얼마인가요?","options":[{"t":"167","correct":true},{"t":"149","mis":"M2-1-u3-X16"},{"t":"122","mis":"M2-1-u3-X16"}],"explanation":["합이 크려면 큰 수 9와 7을 십의 자리에 놓아요.","95 + 72 = 167 (92 + 75도 167)이에요.","97 + 52 = 149처럼 한 수만 크게 만들면 더 작아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_a#25','math',2,1,'u3','','g2_1_math_u3_review_a','unit_review','M2-1-u3-C2',4,'essay','teacher','28 + 19를 두 가지 방법으로 계산하고, 각 방법을 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M2-1-u3-C2","difficulty":4,"kind":"essay","stem":"28 + 19를 두 가지 방법으로 계산하고, 각 방법을 설명해 보세요.","answer_guide":{"answer":"① 자리별로: 20 + 10 = 30, 8 + 9 = 17, 30 + 17 = 47. ② 19를 20으로 보고 28 + 20 = 48, 1을 더 더했으니 48 − 1 = 47.","scoring_points":["서로 다른 방법 두 가지를 썼는가","두 방법 모두 답이 47인가","받아올림이나 몇십 만들기를 말로 설명했는가"]},"explanation":["자리별로 나누면 30 + 17 = 47이에요.","19를 20으로 보고 더한 뒤 1을 빼도 47이에요.","일의 자리 17의 10은 십의 자리로 받아올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_b#1','math',2,1,'u3','','g2_1_math_u3_review_b','unit_review','M2-1-u3-C1',1,'mc','auto','48 + 5는 얼마인가요?',ARRAY['M2-1-u3-X01','M2-1-u3-X03']::text[],true,'{"seq":1,"concept":"M2-1-u3-C1","difficulty":1,"kind":"mc","stem":"48 + 5는 얼마인가요?","explanation":["일의 자리 8 + 5 = 13 — 3을 쓰고 10은 십의 자리로 받아올려요.","십의 자리 4 + 1 = 5. 그래서 48 + 5 = 53이에요.","받아올림한 1은 십의 자리에서 꼭 더해요 — 빠뜨리면 10이 작아져요."],"variant_rule":{"ar2":{"ask":"value","kind":"a21"}},"options":[{"t":"53","correct":true},{"t":"43","mis":"M2-1-u3-X01"},{"t":"98","mis":"M2-1-u3-X03"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_b#2','math',2,1,'u3','','g2_1_math_u3_review_b','unit_review','M2-1-u3-C2',1,'sa','auto','46 + 29는 얼마인가요?','{}'::text[],true,'{"seq":2,"concept":"M2-1-u3-C2","difficulty":1,"kind":"sa","stem":"46 + 29는 얼마인가요?","explanation":["일의 자리 6 + 9 = 15 — 5를 쓰고 10은 십의 자리로 받아올려요.","십의 자리 4 + 2 + 1 = 7. 그래서 46 + 29 = 75예요.","받아올림한 1은 십의 자리에서 꼭 더해요 — 빠뜨리면 10이 작아져요."],"variant_rule":{"ar2":{"ask":"value","kind":"a22"}},"answer":["75"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_b#3','math',2,1,'u3','','g2_1_math_u3_review_b','unit_review','M2-1-u3-C3',1,'mc','auto','67 + 85를 세로셈으로 계산하면 얼마인가요?',ARRAY['M2-1-u3-X01','M2-1-u3-X05']::text[],true,'{"seq":3,"concept":"M2-1-u3-C3","difficulty":1,"kind":"mc","stem":"67 + 85를 세로셈으로 계산하면 얼마인가요?","explanation":["일의 자리 7 + 5 = 12 — 2를 쓰고 10은 십의 자리로 받아올려요.","십의 자리 6 + 8 + 1 = 15 — 10이 넘어 백의 자리로 올려요. 그래서 67 + 85 = 152예요.","십의 자리 합이 10을 넘으면 백의 자리에 1을 써요."],"variant_rule":{"ar2":{"ask":"vert","kind":"a22h"}},"options":[{"t":"152","correct":true},{"t":"142","mis":"M2-1-u3-X01"},{"t":"52","mis":"M2-1-u3-X05"}],"asset":{"type":"vert2","top":67,"bottom":85,"op":"+","ans":null}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_b#4','math',2,1,'u3','','g2_1_math_u3_review_b','unit_review','M2-1-u3-C4',1,'mc','auto','52 − 6은 얼마인가요?',ARRAY['M2-1-u3-X07','M2-1-u3-X08']::text[],true,'{"seq":4,"concept":"M2-1-u3-C4","difficulty":1,"kind":"mc","stem":"52 − 6은 얼마인가요?","explanation":["일의 자리 2에서 6을 뺄 수 없어 십의 자리에서 10을 받아내려요 — 12 − 6 = 6.","십의 자리는 5에서 1을 내려 주어 4. 그래서 52 − 6 = 46이에요.","6 − 2처럼 거꾸로 빼지 않아요 — 위의 수에서 아래 수를 빼요."],"variant_rule":{"ar2":{"ask":"value","kind":"s21"}},"options":[{"t":"46","correct":true},{"t":"54","mis":"M2-1-u3-X07"},{"t":"56","mis":"M2-1-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_b#5','math',2,1,'u3','','g2_1_math_u3_review_b','unit_review','M2-1-u3-C5',1,'mc','auto','82 − 47을 세로셈으로 계산하면 얼마인가요?',ARRAY['M2-1-u3-X07','M2-1-u3-X10']::text[],true,'{"seq":5,"concept":"M2-1-u3-C5","difficulty":1,"kind":"mc","stem":"82 − 47을 세로셈으로 계산하면 얼마인가요?","explanation":["일의 자리 2에서 7을 뺄 수 없어 십의 자리에서 10을 받아내려요 — 12 − 7 = 5.","십의 자리는 8에서 1을 내려 주어 7, 7 − 4 = 3. 그래서 82 − 47 = 35예요.","7 − 2처럼 거꾸로 빼지 않아요 — 위의 수에서 아래 수를 빼요."],"variant_rule":{"ar2":{"ask":"vert","kind":"s22"}},"options":[{"t":"35","correct":true},{"t":"45","mis":"M2-1-u3-X07"},{"t":"129","mis":"M2-1-u3-X10"}],"asset":{"type":"vert2","top":82,"bottom":47,"op":"-","ans":null}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_b#6','math',2,1,'u3','','g2_1_math_u3_review_b','unit_review','M2-1-u3-C6',1,'mc','auto','28 + 25 − 36에서 먼저 계산할 것은 어느 것인가요?',ARRAY['M2-1-u3-X11']::text[],true,'{"seq":6,"concept":"M2-1-u3-C6","difficulty":1,"kind":"mc","stem":"28 + 25 − 36에서 먼저 계산할 것은 어느 것인가요?","explanation":["세 수의 계산은 앞에서부터 차례로 해요.","먼저 28 + 25 = 53, 그다음 53 − 36 = 17이에요.","순서를 바꾸지 않고 왼쪽부터 두 수씩 계산해요."],"variant_rule":{"ar2":{"ask":"first"}},"options":[{"t":"28 + 25","correct":true},{"t":"25 − 36","mis":"M2-1-u3-X11"},{"t":"28 − 36","mis":"M2-1-u3-X11"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_b#7','math',2,1,'u3','','g2_1_math_u3_review_b','unit_review','M2-1-u3-C7',1,'mc','auto','덧셈식 6 + 9 = 15를 뺄셈식으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-1-u3-X13','M2-1-u3-X14']::text[],true,'{"seq":7,"concept":"M2-1-u3-C7","difficulty":1,"kind":"mc","stem":"덧셈식 6 + 9 = 15를 뺄셈식으로 바르게 나타낸 것은 어느 것인가요?","explanation":["15는 전체, 6과 9는 부분이에요.","전체에서 한 부분을 빼면 다른 부분 — 15 − 6 = 9, 15 − 9 = 6.","뺄셈식은 늘 전체에서 빼요 — 부분끼리 빼지 않아요."],"variant_rule":{"ar2":{"ask":"rel","to":"sub","size":"small"}},"options":[{"t":"15 − 9 = 6","correct":true},{"t":"9 − 6 = 15","mis":"M2-1-u3-X13"},{"t":"6 − 15 = 9","mis":"M2-1-u3-X14"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_b#8','math',2,1,'u3','','g2_1_math_u3_review_b','unit_review','M2-1-u3-C8',1,'mc','auto','13 − □ = 8에서 □에 알맞은 수는 얼마인가요?',ARRAY['M2-1-u3-X15','M2-1-u3-X08']::text[],true,'{"seq":8,"concept":"M2-1-u3-C8","difficulty":1,"kind":"mc","stem":"13 − □ = 8에서 □에 알맞은 수는 얼마인가요?","explanation":["13에서 □만큼 빼서 8이 남았어요.","빼는 수 □는 13 − 8 = 5예요.","확인 — 13 − 5 = 8."],"variant_rule":{"ar2":{"ask":"box","size":"small"}},"options":[{"t":"5","correct":true},{"t":"21","mis":"M2-1-u3-X15"},{"t":"15","mis":"M2-1-u3-X08"}],"asset":{"type":"bar2","whole":13,"parts":[null,8]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_b#9','math',2,1,'u3','','g2_1_math_u3_review_b','unit_review','M2-1-u3-C1',2,'mc','auto','27 + 6을 계산할 때, 27에 얼마를 더하면 30이 되나요?',ARRAY['M2-1-u3-X04']::text[],true,'{"seq":9,"concept":"M2-1-u3-C1","difficulty":2,"kind":"mc","stem":"27 + 6을 계산할 때, 27에 얼마를 더하면 30이 되나요?","explanation":["27에서 30까지는 3만큼 더 가야 해요.","27 + 3 = 30 — 먼저 몇십을 만들어요.","남은 3을 더하면 30 + 3 = 33이에요."],"variant_rule":{"ar2":{"ask":"fill","kind":"a21"}},"options":[{"t":"3","correct":true},{"t":"7","mis":"M2-1-u3-X04"},{"t":"4","mis":"M2-1-u3-X04"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_b#10','math',2,1,'u3','','g2_1_math_u3_review_b','unit_review','M2-1-u3-C3',2,'mc','auto','47 + 36을 세로셈으로 계산할 때, 십의 자리에서 계산할 식은 어느 것인가요?',ARRAY['M2-1-u3-X01','M2-1-u3-X06']::text[],true,'{"seq":10,"concept":"M2-1-u3-C3","difficulty":2,"kind":"mc","stem":"47 + 36을 세로셈으로 계산할 때, 십의 자리에서 계산할 식은 어느 것인가요?","explanation":["일의 자리 7 + 6 = 13 — 10을 십의 자리로 받아올려요.","받아올림한 10은 십의 자리에서는 1이에요. 그래서 십의 자리 식은 4 + 3 + 1이에요.","받아올린 수는 십의 자리에서 「1」로 더해요 — 10을 더하지 않아요."],"variant_rule":{"ar2":{"ask":"carry","kind":"a22"}},"options":[{"t":"4 + 3 + 1","correct":true},{"t":"4 + 3","mis":"M2-1-u3-X01"},{"t":"4 + 3 + 10","mis":"M2-1-u3-X06"}],"asset":{"type":"vert2","top":47,"bottom":36,"op":"+","ans":null}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_b#11','math',2,1,'u3','','g2_1_math_u3_review_b','unit_review','M2-1-u3-C5',2,'mc','auto','74 − 39를 세로셈으로 계산할 때, 일의 자리에서 계산할 식은 어느 것인가요?',ARRAY['M2-1-u3-X07','M2-1-u3-X09']::text[],true,'{"seq":11,"concept":"M2-1-u3-C5","difficulty":2,"kind":"mc","stem":"74 − 39를 세로셈으로 계산할 때, 일의 자리에서 계산할 식은 어느 것인가요?","explanation":["일의 자리 4에서 9를 뺄 수 없어요.","십의 자리에서 10을 받아내리면 일의 자리는 14 — 14 − 9를 계산해요.","9 − 4처럼 아래 수에서 위의 수를 빼지 않아요."],"variant_rule":{"ar2":{"ask":"borrow","kind":"s22"}},"options":[{"t":"14 − 9","correct":true},{"t":"9 − 4","mis":"M2-1-u3-X07"},{"t":"5 − 9","mis":"M2-1-u3-X09"}],"asset":{"type":"vert2","top":74,"bottom":39,"op":"-","ans":null}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_b#12','math',2,1,'u3','','g2_1_math_u3_review_b','unit_review','M2-1-u3-C3',2,'ox','auto','68 + 59 = 127 입니다.',ARRAY['M2-1-u3-X01']::text[],true,'{"seq":12,"concept":"M2-1-u3-C3","difficulty":2,"kind":"ox","stem":"68 + 59 = 127 입니다.","explanation":["일의 자리 8 + 9 = 17 — 7을 쓰고 10은 십의 자리로 받아올려요.","십의 자리 6 + 5 + 1 = 12 — 10이 넘어 백의 자리로 올려요. 그래서 68 + 59 = 127이에요.","십의 자리 합이 10을 넘으면 백의 자리에 1을 써요."],"variant_rule":{"ar2":{"ask":"value","kind":"a22h"}},"answer":"O","mis":"M2-1-u3-X05","reason_options":[{"t":"받아올림한 1을 십의 자리에 더해 계산했으니까","correct":true},{"t":"일의 자리끼리, 십의 자리끼리 더하기만 하면 되니까","mis":"M2-1-u3-X01"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_b#13','math',2,1,'u3','','g2_1_math_u3_review_b','unit_review','M2-1-u3-C6',2,'sa','auto','61 − 28 + 15를 앞에서부터 차례로 계산하면 얼마인가요?','{}'::text[],true,'{"seq":13,"concept":"M2-1-u3-C6","difficulty":2,"kind":"sa","stem":"61 − 28 + 15를 앞에서부터 차례로 계산하면 얼마인가요?","explanation":["① 앞의 두 수부터 — 61 − 28 = 33.","② 33 + 15 = 48이에요.","28 + 15를 먼저 계산하면 안 돼요 — 앞에서부터 차례로."],"variant_rule":{"ar2":{"ask":"three"}},"answer":["48"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_b#14','math',2,1,'u3','','g2_1_math_u3_review_b','unit_review','M2-1-u3-C5',2,'mc','auto','71 − 38 = 33을 덧셈으로 확인하는 식은 어느 것인가요?',ARRAY['M2-1-u3-X16','M2-1-u3-X10']::text[],true,'{"seq":14,"concept":"M2-1-u3-C5","difficulty":2,"kind":"mc","stem":"71 − 38 = 33을 덧셈으로 확인하는 식은 어느 것인가요?","explanation":["뺄셈의 답에 뺀 수를 더하면 처음 수가 돼요.","33 + 38 = 71 — 처음 수 71이 나오니 바르게 뺐어요.","처음 수를 더하면 확인이 되지 않아요."],"variant_rule":{"ar2":{"ask":"verify","kind":"s22"}},"options":[{"t":"33 + 38 = 71","correct":true},{"t":"33 + 71 = 104","mis":"M2-1-u3-X16"},{"t":"71 + 38 = 109","mis":"M2-1-u3-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_b#15','math',2,1,'u3','','g2_1_math_u3_review_b','unit_review','M2-1-u3-C5',2,'mc','auto','지우는 색종이 72장을, 펭이는 45장을 모았어요. 지우가 펭이보다 몇 장 더 많이 모았나요?',ARRAY['M2-1-u3-X07','M2-1-u3-X08']::text[],true,'{"seq":15,"concept":"M2-1-u3-C5","difficulty":2,"kind":"mc","stem":"지우는 색종이 72장을, 펭이는 45장을 모았어요. 지우가 펭이보다 몇 장 더 많이 모았나요?","explanation":["일의 자리 2에서 5를 뺄 수 없어 십의 자리에서 10을 받아내려요 — 12 − 5 = 7.","십의 자리는 7에서 1을 내려 주어 6, 6 − 4 = 2. 그래서 72 − 45 = 27이에요.","「몇 장 더 많이」는 두 수를 견주는 이야기라 뺄셈이에요 — 27장이에요."],"variant_rule":{"ar2":{"ask":"story","kind":"s22"}},"options":[{"t":"27","correct":true},{"t":"33","mis":"M2-1-u3-X07"},{"t":"37","mis":"M2-1-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_b#16','math',2,1,'u3','','g2_1_math_u3_review_b','unit_review','M2-1-u3-C8',2,'sa','auto','63 − □ = 25에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":16,"concept":"M2-1-u3-C8","difficulty":2,"kind":"sa","stem":"63 − □ = 25에서 □에 알맞은 수는 얼마인가요?","explanation":["63에서 □만큼 빼서 25가 남았어요.","빼는 수 □는 63 − 25 = 38이에요.","확인 — 63 − 38 = 25."],"variant_rule":{"ar2":{"ask":"box","size":"big"}},"answer":["38"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_b#17','math',2,1,'u3','','g2_1_math_u3_review_b','unit_review','M2-1-u3-C3',3,'sa','auto','다예가 색종이 76장을 가지고 있었는데 49장을 더 받았어요. 색종이는 모두 몇 장인가요?','{}'::text[],true,'{"seq":17,"concept":"M2-1-u3-C3","difficulty":3,"kind":"sa","stem":"다예가 색종이 76장을 가지고 있었는데 49장을 더 받았어요. 색종이는 모두 몇 장인가요?","explanation":["일의 자리 6 + 9 = 15 — 5를 쓰고 10은 십의 자리로 받아올려요.","십의 자리 7 + 4 + 1 = 12 — 10이 넘어 백의 자리로 올려요. 그래서 76 + 49 = 125예요.","「모두」는 모으는 이야기라 덧셈이에요 — 125장이에요."],"variant_rule":{"ar2":{"ask":"story","kind":"a22h"}},"answer":["125","125장"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_b#18','math',2,1,'u3','','g2_1_math_u3_review_b','unit_review','M2-1-u3-C6',3,'mc','auto','58 + 26 − 39를 앞에서부터 차례로 계산하면 얼마인가요?',ARRAY['M2-1-u3-X12','M2-1-u3-X01']::text[],true,'{"seq":18,"concept":"M2-1-u3-C6","difficulty":3,"kind":"mc","stem":"58 + 26 − 39를 앞에서부터 차례로 계산하면 얼마인가요?","explanation":["① 앞의 두 수부터 — 58 + 26 = 84.","② 84 − 39 = 45예요.","84에서 멈추지 않고 남은 계산까지 해요."],"variant_rule":{"ar2":{"ask":"three"}},"options":[{"t":"45","correct":true},{"t":"84","mis":"M2-1-u3-X12"},{"t":"123","mis":"M2-1-u3-X12"},{"t":"55","mis":"M2-1-u3-X01"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_b#19','math',2,1,'u3','','g2_1_math_u3_review_b','unit_review','M2-1-u3-C8',3,'mc','auto','서아가 색종이 몇 장을 가지고 있었는데 26장을 친구에게 주었더니 35장이 남았어요. 처음에 있던 색종이의 수를 □로 하여 식을 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-1-u3-X14','M2-1-u3-X10']::text[],true,'{"seq":19,"concept":"M2-1-u3-C8","difficulty":3,"kind":"mc","stem":"서아가 색종이 몇 장을 가지고 있었는데 26장을 친구에게 주었더니 35장이 남았어요. 처음에 있던 색종이의 수를 □로 하여 식을 바르게 나타낸 것은 어느 것인가요?","explanation":["처음 □장에서 26장을 주고 35장이 남았어요.","그래서 식은 □ − 26 = 35 — □는 35 + 26 = 61이에요.","처음 수 □가 빼는 식의 맨 앞에 와요."],"variant_rule":{"ar2":{"ask":"boxmake"}},"options":[{"t":"□ − 26 = 35","correct":true},{"t":"26 − □ = 35","mis":"M2-1-u3-X14"},{"t":"□ + 26 = 35","mis":"M2-1-u3-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_b#20','math',2,1,'u3','','g2_1_math_u3_review_b','unit_review','M2-1-u3-C3',3,'mc','auto','지우가 62 + 53을 세로셈으로 계산한 것이에요. 잘못 계산한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M2-1-u3-X02','M2-1-u3-X06']::text[],false,'{"seq":20,"concept":"M2-1-u3-C3","difficulty":3,"kind":"mc","stem":"지우가 62 + 53을 세로셈으로 계산한 것이에요. 잘못 계산한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"십의 자리 합 11의 1을 백의 자리로 올리지 않았어요.","correct":true},{"t":"일의 자리 2 + 3을 잘못 더했어요.","mis":"M2-1-u3-X02"},{"t":"받아올림한 1을 두 번 더했어요.","mis":"M2-1-u3-X06"}],"explanation":["일의 자리 2 + 3 = 5예요.","십의 자리 6 + 5 = 11 — 바른 답은 115예요.","지우는 백의 자리를 쓰지 않아 15라고 썼어요."],"asset":{"type":"vert2","top":62,"bottom":53,"op":"+","ans":15}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_b#21','math',2,1,'u3','','g2_1_math_u3_review_b','unit_review','M2-1-u3-C7',3,'mc','auto','뺄셈식 62 − 37 = 25를 덧셈식으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-1-u3-X14']::text[],true,'{"seq":21,"concept":"M2-1-u3-C7","difficulty":3,"kind":"mc","stem":"뺄셈식 62 − 37 = 25를 덧셈식으로 바르게 나타낸 것은 어느 것인가요?","explanation":["62는 전체, 37과 25는 부분이에요.","두 부분을 모으면 전체 — 37 + 25 = 62.","덧셈식에서 전체는 = 오른쪽에 와요."],"variant_rule":{"ar2":{"ask":"rel","to":"add","size":"big"}},"options":[{"t":"25 + 37 = 62","correct":true},{"t":"62 + 37 = 25","mis":"M2-1-u3-X14"},{"t":"62 + 25 = 37","mis":"M2-1-u3-X14"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_b#22','math',2,1,'u3','','g2_1_math_u3_review_b','unit_review','M2-1-u3-C6',3,'sa','auto','도토리 45개 가운데 17개를 먹고, 다시 24개를 주웠어요. 도토리는 몇 개가 되었나요?','{}'::text[],false,'{"seq":22,"concept":"M2-1-u3-C6","difficulty":3,"kind":"sa","stem":"도토리 45개 가운데 17개를 먹고, 다시 24개를 주웠어요. 도토리는 몇 개가 되었나요?","answer":["52","52개"],"explanation":["식은 45 − 17 + 24예요.","45 − 17 = 28, 28 + 24 = 52예요.","먹은 것은 빼고 주운 것은 더해요 — 앞에서부터."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_b#23','math',2,1,'u3','','g2_1_math_u3_review_b','unit_review','M2-1-u3-C4',4,'mc','auto','어떤 수에서 7을 빼야 할 것을 잘못하여 7을 더했더니 52가 되었어요. 바르게 계산하면 얼마인가요?',ARRAY['M2-1-u3-X16','M2-1-u3-X10']::text[],false,'{"seq":23,"concept":"M2-1-u3-C4","difficulty":4,"kind":"mc","stem":"어떤 수에서 7을 빼야 할 것을 잘못하여 7을 더했더니 52가 되었어요. 바르게 계산하면 얼마인가요?","options":[{"t":"38","correct":true},{"t":"45","mis":"M2-1-u3-X16"},{"t":"59","mis":"M2-1-u3-X10"}],"explanation":["7을 더했더니 52니까 어떤 수는 52 − 7 = 45예요.","바르게 계산하면 45 − 7 = 38이에요.","45는 어떤 수 — 물음은 바르게 계산한 값이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_b#24','math',2,1,'u3','','g2_1_math_u3_review_b','unit_review','M2-1-u3-C5',4,'mc','auto','수 카드 3, 6, 9를 두 장 골라 두 자리 수를 만들어요. 가장 큰 수에서 두 번째로 작은 수를 빼면 얼마인가요?',ARRAY['M2-1-u3-X07','M2-1-u3-X16']::text[],false,'{"seq":24,"concept":"M2-1-u3-C5","difficulty":4,"kind":"mc","stem":"수 카드 3, 6, 9를 두 장 골라 두 자리 수를 만들어요. 가장 큰 수에서 두 번째로 작은 수를 빼면 얼마인가요?","options":[{"t":"57","correct":true},{"t":"63","mis":"M2-1-u3-X07"},{"t":"60","mis":"M2-1-u3-X16"}],"explanation":["가장 큰 수는 96, 가장 작은 수는 36, 두 번째로 작은 수는 39예요.","96 − 39 = 57이에요.","60은 가장 작은 수 36을 뺀 값이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_b#25','math',2,1,'u3','','g2_1_math_u3_review_b','unit_review','M2-1-u3-C5',4,'essay','teacher','54 − 26을 세로셈으로 계산하는 방법을 설명하고, 덧셈으로 확인해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M2-1-u3-C5","difficulty":4,"kind":"essay","stem":"54 − 26을 세로셈으로 계산하는 방법을 설명하고, 덧셈으로 확인해 보세요.","answer_guide":{"answer":"일의 자리 4에서 6을 뺄 수 없어 10을 받아내려 14 − 6 = 8, 십의 자리 4 − 2 = 2. 답은 28. 확인: 28 + 26 = 54.","scoring_points":["받아내림으로 14 − 6 = 8을 계산했는가","십의 자리를 1 줄여 28을 구했는가","28 + 26 = 54로 확인했는가"]},"explanation":["14 − 6 = 8, 십의 자리 4 − 2 = 2예요.","답은 28이에요.","28 + 26 = 54로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_c#1','math',2,1,'u3','','g2_1_math_u3_review_c','unit_review','M2-1-u3-C1',1,'mc','auto','39 + 4는 얼마인가요?',ARRAY['M2-1-u3-X01','M2-1-u3-X03']::text[],true,'{"seq":1,"concept":"M2-1-u3-C1","difficulty":1,"kind":"mc","stem":"39 + 4는 얼마인가요?","explanation":["일의 자리 9 + 4 = 13 — 3을 쓰고 10은 십의 자리로 받아올려요.","십의 자리 3 + 1 = 4. 그래서 39 + 4 = 43이에요.","받아올림한 1은 십의 자리에서 꼭 더해요 — 빠뜨리면 10이 작아져요."],"variant_rule":{"ar2":{"ask":"value","kind":"a21"}},"options":[{"t":"43","correct":true},{"t":"33","mis":"M2-1-u3-X01"},{"t":"79","mis":"M2-1-u3-X03"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_c#2','math',2,1,'u3','','g2_1_math_u3_review_c','unit_review','M2-1-u3-C2',1,'sa','auto','17 + 58은 얼마인가요?','{}'::text[],true,'{"seq":2,"concept":"M2-1-u3-C2","difficulty":1,"kind":"sa","stem":"17 + 58은 얼마인가요?","explanation":["일의 자리 7 + 8 = 15 — 5를 쓰고 10은 십의 자리로 받아올려요.","십의 자리 1 + 5 + 1 = 7. 그래서 17 + 58 = 75예요.","받아올림한 1은 십의 자리에서 꼭 더해요 — 빠뜨리면 10이 작아져요."],"variant_rule":{"ar2":{"ask":"value","kind":"a22"}},"answer":["75"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_c#3','math',2,1,'u3','','g2_1_math_u3_review_c','unit_review','M2-1-u3-C3',1,'mc','auto','94 + 27을 세로셈으로 계산하면 얼마인가요?',ARRAY['M2-1-u3-X01','M2-1-u3-X05']::text[],true,'{"seq":3,"concept":"M2-1-u3-C3","difficulty":1,"kind":"mc","stem":"94 + 27을 세로셈으로 계산하면 얼마인가요?","explanation":["일의 자리 4 + 7 = 11 — 1을 쓰고 10은 십의 자리로 받아올려요.","십의 자리 9 + 2 + 1 = 12 — 10이 넘어 백의 자리로 올려요. 그래서 94 + 27 = 121이에요.","십의 자리 합이 10을 넘으면 백의 자리에 1을 써요."],"variant_rule":{"ar2":{"ask":"vert","kind":"a22h"}},"options":[{"t":"121","correct":true},{"t":"111","mis":"M2-1-u3-X01"},{"t":"21","mis":"M2-1-u3-X05"}],"asset":{"type":"vert2","top":94,"bottom":27,"op":"+","ans":null}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_c#4','math',2,1,'u3','','g2_1_math_u3_review_c','unit_review','M2-1-u3-C4',1,'mc','auto','71 − 5는 얼마인가요?',ARRAY['M2-1-u3-X07','M2-1-u3-X08']::text[],true,'{"seq":4,"concept":"M2-1-u3-C4","difficulty":1,"kind":"mc","stem":"71 − 5는 얼마인가요?","explanation":["일의 자리 1에서 5를 뺄 수 없어 십의 자리에서 10을 받아내려요 — 11 − 5 = 6.","십의 자리는 7에서 1을 내려 주어 6. 그래서 71 − 5 = 66이에요.","5 − 1처럼 거꾸로 빼지 않아요 — 위의 수에서 아래 수를 빼요."],"variant_rule":{"ar2":{"ask":"value","kind":"s21"}},"options":[{"t":"66","correct":true},{"t":"74","mis":"M2-1-u3-X07"},{"t":"76","mis":"M2-1-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_c#5','math',2,1,'u3','','g2_1_math_u3_review_c','unit_review','M2-1-u3-C5',1,'mc','auto','63 − 38을 세로셈으로 계산하면 얼마인가요?',ARRAY['M2-1-u3-X07','M2-1-u3-X10']::text[],true,'{"seq":5,"concept":"M2-1-u3-C5","difficulty":1,"kind":"mc","stem":"63 − 38을 세로셈으로 계산하면 얼마인가요?","explanation":["일의 자리 3에서 8을 뺄 수 없어 십의 자리에서 10을 받아내려요 — 13 − 8 = 5.","십의 자리는 6에서 1을 내려 주어 5, 5 − 3 = 2. 그래서 63 − 38 = 25예요.","8 − 3처럼 거꾸로 빼지 않아요 — 위의 수에서 아래 수를 빼요."],"variant_rule":{"ar2":{"ask":"vert","kind":"s22"}},"options":[{"t":"25","correct":true},{"t":"35","mis":"M2-1-u3-X07"},{"t":"101","mis":"M2-1-u3-X10"}],"asset":{"type":"vert2","top":63,"bottom":38,"op":"-","ans":null}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_c#6','math',2,1,'u3','','g2_1_math_u3_review_c','unit_review','M2-1-u3-C6',1,'mc','auto','63 − 28 + 17에서 먼저 계산할 것은 어느 것인가요?',ARRAY['M2-1-u3-X11']::text[],true,'{"seq":6,"concept":"M2-1-u3-C6","difficulty":1,"kind":"mc","stem":"63 − 28 + 17에서 먼저 계산할 것은 어느 것인가요?","explanation":["세 수의 계산은 앞에서부터 차례로 해요.","먼저 63 − 28 = 35, 그다음 35 + 17 = 52예요.","28 + 17을 먼저 하면 답이 달라져요."],"variant_rule":{"ar2":{"ask":"first"}},"options":[{"t":"63 − 28","correct":true},{"t":"28 + 17","mis":"M2-1-u3-X11"},{"t":"63 + 17","mis":"M2-1-u3-X11"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_c#7','math',2,1,'u3','','g2_1_math_u3_review_c','unit_review','M2-1-u3-C7',1,'mc','auto','덧셈식 7 + 4 = 11을 뺄셈식으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-1-u3-X13','M2-1-u3-X14']::text[],true,'{"seq":7,"concept":"M2-1-u3-C7","difficulty":1,"kind":"mc","stem":"덧셈식 7 + 4 = 11을 뺄셈식으로 바르게 나타낸 것은 어느 것인가요?","explanation":["11은 전체, 7과 4는 부분이에요.","전체에서 한 부분을 빼면 다른 부분 — 11 − 7 = 4, 11 − 4 = 7.","뺄셈식은 늘 전체에서 빼요 — 부분끼리 빼지 않아요."],"variant_rule":{"ar2":{"ask":"rel","to":"sub","size":"small"}},"options":[{"t":"11 − 4 = 7","correct":true},{"t":"7 − 4 = 11","mis":"M2-1-u3-X13"},{"t":"7 − 11 = 4","mis":"M2-1-u3-X14"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_c#8','math',2,1,'u3','','g2_1_math_u3_review_c','unit_review','M2-1-u3-C8',1,'mc','auto','□ + 4 = 13에서 □에 알맞은 수는 얼마인가요?',ARRAY['M2-1-u3-X15','M2-1-u3-X08']::text[],true,'{"seq":8,"concept":"M2-1-u3-C8","difficulty":1,"kind":"mc","stem":"□ + 4 = 13에서 □에 알맞은 수는 얼마인가요?","explanation":["전체 13, 한 부분 4예요.","다른 부분 □는 13 − 4 = 9예요.","확인 — 9 + 4 = 13."],"variant_rule":{"ar2":{"ask":"box","size":"small"}},"options":[{"t":"9","correct":true},{"t":"17","mis":"M2-1-u3-X15"},{"t":"19","mis":"M2-1-u3-X08"}],"asset":{"type":"bar2","whole":13,"parts":[null,4]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_c#9','math',2,1,'u3','','g2_1_math_u3_review_c','unit_review','M2-1-u3-C1',2,'mc','auto','46 + 8을 계산할 때, 46에 얼마를 더하면 50이 되나요?',ARRAY['M2-1-u3-X04']::text[],true,'{"seq":9,"concept":"M2-1-u3-C1","difficulty":2,"kind":"mc","stem":"46 + 8을 계산할 때, 46에 얼마를 더하면 50이 되나요?","explanation":["46에서 50까지는 4만큼 더 가야 해요.","46 + 4 = 50 — 먼저 몇십을 만들어요.","남은 4를 더하면 50 + 4 = 54예요."],"variant_rule":{"ar2":{"ask":"fill","kind":"a21"}},"options":[{"t":"4","correct":true},{"t":"6","mis":"M2-1-u3-X04"},{"t":"2","mis":"M2-1-u3-X04"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_c#10','math',2,1,'u3','','g2_1_math_u3_review_c','unit_review','M2-1-u3-C3',2,'mc','auto','29 + 48을 세로셈으로 계산할 때, 십의 자리에서 계산할 식은 어느 것인가요?',ARRAY['M2-1-u3-X01','M2-1-u3-X06']::text[],true,'{"seq":10,"concept":"M2-1-u3-C3","difficulty":2,"kind":"mc","stem":"29 + 48을 세로셈으로 계산할 때, 십의 자리에서 계산할 식은 어느 것인가요?","explanation":["일의 자리 9 + 8 = 17 — 10을 십의 자리로 받아올려요.","받아올림한 10은 십의 자리에서는 1이에요. 그래서 십의 자리 식은 2 + 4 + 1이에요.","받아올린 수는 십의 자리에서 「1」로 더해요 — 10을 더하지 않아요."],"variant_rule":{"ar2":{"ask":"carry","kind":"a22"}},"options":[{"t":"2 + 4 + 1","correct":true},{"t":"2 + 4","mis":"M2-1-u3-X01"},{"t":"2 + 4 + 10","mis":"M2-1-u3-X06"}],"asset":{"type":"vert2","top":29,"bottom":48,"op":"+","ans":null}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_c#11','math',2,1,'u3','','g2_1_math_u3_review_c','unit_review','M2-1-u3-C5',2,'mc','auto','61 − 25를 세로셈으로 계산할 때, 일의 자리에서 계산할 식은 어느 것인가요?',ARRAY['M2-1-u3-X07','M2-1-u3-X09']::text[],true,'{"seq":11,"concept":"M2-1-u3-C5","difficulty":2,"kind":"mc","stem":"61 − 25를 세로셈으로 계산할 때, 일의 자리에서 계산할 식은 어느 것인가요?","explanation":["일의 자리 1에서 5를 뺄 수 없어요.","십의 자리에서 10을 받아내리면 일의 자리는 11 — 11 − 5를 계산해요.","5 − 1처럼 아래 수에서 위의 수를 빼지 않아요."],"variant_rule":{"ar2":{"ask":"borrow","kind":"s22"}},"options":[{"t":"11 − 5","correct":true},{"t":"5 − 1","mis":"M2-1-u3-X07"},{"t":"2 − 5","mis":"M2-1-u3-X09"}],"asset":{"type":"vert2","top":61,"bottom":25,"op":"-","ans":null}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_c#12','math',2,1,'u3','','g2_1_math_u3_review_c','unit_review','M2-1-u3-C3',2,'ox','auto','87 + 46 = 123 입니다.',ARRAY['M2-1-u3-X01']::text[],true,'{"seq":12,"concept":"M2-1-u3-C3","difficulty":2,"kind":"ox","stem":"87 + 46 = 123 입니다.","explanation":["일의 자리 7 + 6 = 13 — 3을 쓰고 10은 십의 자리로 받아올려요.","십의 자리 8 + 4 + 1 = 13 — 10이 넘어 백의 자리로 올려요. 그래서 87 + 46 = 133이에요.","십의 자리 합이 10을 넘으면 백의 자리에 1을 써요."],"variant_rule":{"ar2":{"ask":"value","kind":"a22h"}},"answer":"X","mis":"M2-1-u3-X05","reason_options":[{"t":"바르게 계산하면 133이 되니까","correct":true},{"t":"일의 자리끼리, 십의 자리끼리 더하기만 하면 되니까","mis":"M2-1-u3-X01"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_c#13','math',2,1,'u3','','g2_1_math_u3_review_c','unit_review','M2-1-u3-C6',2,'sa','auto','42 − 15 + 27을 앞에서부터 차례로 계산하면 얼마인가요?','{}'::text[],true,'{"seq":13,"concept":"M2-1-u3-C6","difficulty":2,"kind":"sa","stem":"42 − 15 + 27을 앞에서부터 차례로 계산하면 얼마인가요?","explanation":["① 앞의 두 수부터 — 42 − 15 = 27.","② 27 + 27 = 54예요.","15 + 27을 먼저 계산하면 안 돼요 — 앞에서부터 차례로."],"variant_rule":{"ar2":{"ask":"three"}},"answer":["54"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_c#14','math',2,1,'u3','','g2_1_math_u3_review_c','unit_review','M2-1-u3-C5',2,'mc','auto','45 − 28 = 17을 덧셈으로 확인하는 식은 어느 것인가요?',ARRAY['M2-1-u3-X16','M2-1-u3-X10']::text[],true,'{"seq":14,"concept":"M2-1-u3-C5","difficulty":2,"kind":"mc","stem":"45 − 28 = 17을 덧셈으로 확인하는 식은 어느 것인가요?","explanation":["뺄셈의 답에 뺀 수를 더하면 처음 수가 돼요.","17 + 28 = 45 — 처음 수 45가 나오니 바르게 뺐어요.","처음 수를 더하면 확인이 되지 않아요."],"variant_rule":{"ar2":{"ask":"verify","kind":"s22"}},"options":[{"t":"17 + 28 = 45","correct":true},{"t":"17 + 45 = 62","mis":"M2-1-u3-X16"},{"t":"45 + 28 = 73","mis":"M2-1-u3-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_c#15','math',2,1,'u3','','g2_1_math_u3_review_c','unit_review','M2-1-u3-C5',2,'mc','auto','지우가 색종이 50장을 가지고 있었는데 24장을 친구에게 주었어요. 남은 색종이는 몇 장인가요?',ARRAY['M2-1-u3-X07','M2-1-u3-X08']::text[],true,'{"seq":15,"concept":"M2-1-u3-C5","difficulty":2,"kind":"mc","stem":"지우가 색종이 50장을 가지고 있었는데 24장을 친구에게 주었어요. 남은 색종이는 몇 장인가요?","explanation":["일의 자리 0에서 4를 뺄 수 없어 십의 자리에서 10을 받아내려요 — 10 − 4 = 6.","십의 자리는 5에서 1을 내려 주어 4, 4 − 2 = 2. 그래서 50 − 24 = 26이에요.","「남은」은 덜어 내는 이야기라 뺄셈이에요 — 26장이에요."],"variant_rule":{"ar2":{"ask":"story","kind":"s22"}},"options":[{"t":"26","correct":true},{"t":"34","mis":"M2-1-u3-X07"},{"t":"36","mis":"M2-1-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_c#16','math',2,1,'u3','','g2_1_math_u3_review_c','unit_review','M2-1-u3-C8',2,'sa','auto','□ + 27 = 63에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":16,"concept":"M2-1-u3-C8","difficulty":2,"kind":"sa","stem":"□ + 27 = 63에서 □에 알맞은 수는 얼마인가요?","explanation":["전체 63, 한 부분 27이에요.","다른 부분 □는 63 − 27 = 36이에요.","확인 — 36 + 27 = 63."],"variant_rule":{"ar2":{"ask":"box","size":"big"}},"answer":["36"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_c#17','math',2,1,'u3','','g2_1_math_u3_review_c','unit_review','M2-1-u3-C3',3,'sa','auto','다예가 색종이 85장을 가지고 있었는데 37장을 더 받았어요. 색종이는 모두 몇 장인가요?','{}'::text[],true,'{"seq":17,"concept":"M2-1-u3-C3","difficulty":3,"kind":"sa","stem":"다예가 색종이 85장을 가지고 있었는데 37장을 더 받았어요. 색종이는 모두 몇 장인가요?","explanation":["일의 자리 5 + 7 = 12 — 2를 쓰고 10은 십의 자리로 받아올려요.","십의 자리 8 + 3 + 1 = 12 — 10이 넘어 백의 자리로 올려요. 그래서 85 + 37 = 122예요.","「모두」는 모으는 이야기라 덧셈이에요 — 122장이에요."],"variant_rule":{"ar2":{"ask":"story","kind":"a22h"}},"answer":["122","122장"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_c#18','math',2,1,'u3','','g2_1_math_u3_review_c','unit_review','M2-1-u3-C6',3,'mc','auto','45 + 27 − 19를 앞에서부터 차례로 계산하면 얼마인가요?',ARRAY['M2-1-u3-X12','M2-1-u3-X01']::text[],true,'{"seq":18,"concept":"M2-1-u3-C6","difficulty":3,"kind":"mc","stem":"45 + 27 − 19를 앞에서부터 차례로 계산하면 얼마인가요?","explanation":["① 앞의 두 수부터 — 45 + 27 = 72.","② 72 − 19 = 53이에요.","72에서 멈추지 않고 남은 계산까지 해요."],"variant_rule":{"ar2":{"ask":"three"}},"options":[{"t":"53","correct":true},{"t":"72","mis":"M2-1-u3-X12"},{"t":"91","mis":"M2-1-u3-X12"},{"t":"63","mis":"M2-1-u3-X01"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_c#19','math',2,1,'u3','','g2_1_math_u3_review_c','unit_review','M2-1-u3-C8',3,'mc','auto','서아가 색종이 19장을 가지고 있었는데 몇 장을 더 받았더니 43장이 되었어요. 더 받은 색종이의 수를 □로 하여 식을 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-1-u3-X15']::text[],true,'{"seq":19,"concept":"M2-1-u3-C8","difficulty":3,"kind":"mc","stem":"서아가 색종이 19장을 가지고 있었는데 몇 장을 더 받았더니 43장이 되었어요. 더 받은 색종이의 수를 □로 하여 식을 바르게 나타낸 것은 어느 것인가요?","explanation":["처음 19장에 □장을 더 받아 43장이 되었어요.","그래서 식은 19 + □ = 43 — □는 43 − 19 = 24예요.","처음 수와 결과의 수가 식에서 제자리에 있는지 살펴요."],"variant_rule":{"ar2":{"ask":"boxmake"}},"options":[{"t":"19 + □ = 43","correct":true},{"t":"43 + □ = 19","mis":"M2-1-u3-X15"},{"t":"19 + 43 = □","mis":"M2-1-u3-X15"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_c#20','math',2,1,'u3','','g2_1_math_u3_review_c','unit_review','M2-1-u3-C5',3,'mc','auto','도윤이가 42 − 19를 세로셈으로 계산한 것이에요. 잘못 계산한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M2-1-u3-X07','M2-1-u3-X10']::text[],false,'{"seq":20,"concept":"M2-1-u3-C5","difficulty":3,"kind":"mc","stem":"도윤이가 42 − 19를 세로셈으로 계산한 것이에요. 잘못 계산한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"받아내림하고 십의 자리 4를 3으로 줄이지 않았어요.","correct":true},{"t":"일의 자리에서 9 − 2로 거꾸로 뺐어요.","mis":"M2-1-u3-X07"},{"t":"두 수를 더했어요.","mis":"M2-1-u3-X10"}],"explanation":["일의 자리 12 − 9 = 3이에요.","십의 자리는 4가 3으로 줄어 3 − 1 = 2 — 바른 답은 23이에요.","도윤이는 십의 자리를 줄이지 않아 33이라고 썼어요."],"asset":{"type":"vert2","top":42,"bottom":19,"op":"-","ans":33}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_c#21','math',2,1,'u3','','g2_1_math_u3_review_c','unit_review','M2-1-u3-C7',3,'mc','auto','뺄셈식 77 − 29 = 48을 덧셈식으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-1-u3-X14']::text[],true,'{"seq":21,"concept":"M2-1-u3-C7","difficulty":3,"kind":"mc","stem":"뺄셈식 77 − 29 = 48을 덧셈식으로 바르게 나타낸 것은 어느 것인가요?","explanation":["77은 전체, 29와 48은 부분이에요.","두 부분을 모으면 전체 — 29 + 48 = 77.","덧셈식에서 전체는 = 오른쪽에 와요."],"variant_rule":{"ar2":{"ask":"rel","to":"add","size":"big"}},"options":[{"t":"29 + 48 = 77","correct":true},{"t":"77 + 29 = 48","mis":"M2-1-u3-X14"},{"t":"77 + 48 = 29","mis":"M2-1-u3-X14"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_c#22','math',2,1,'u3','','g2_1_math_u3_review_c','unit_review','M2-1-u3-C6',3,'sa','auto','버스에 32명이 타고 있었는데 18명이 내리고 27명이 탔어요. 버스에 탄 사람은 몇 명인가요?','{}'::text[],false,'{"seq":22,"concept":"M2-1-u3-C6","difficulty":3,"kind":"sa","stem":"버스에 32명이 타고 있었는데 18명이 내리고 27명이 탔어요. 버스에 탄 사람은 몇 명인가요?","answer":["41","41명"],"explanation":["식은 32 − 18 + 27이에요.","32 − 18 = 14, 14 + 27 = 41이에요.","내린 사람은 빼고 탄 사람은 더해요 — 앞에서부터."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_c#23','math',2,1,'u3','','g2_1_math_u3_review_c','unit_review','M2-1-u3-C8',4,'mc','auto','어떤 수에 27을 더해야 할 것을 잘못하여 72를 더했더니 91이 되었어요. 바르게 계산하면 얼마인가요?',ARRAY['M2-1-u3-X16','M2-1-u3-X15']::text[],false,'{"seq":23,"concept":"M2-1-u3-C8","difficulty":4,"kind":"mc","stem":"어떤 수에 27을 더해야 할 것을 잘못하여 72를 더했더니 91이 되었어요. 바르게 계산하면 얼마인가요?","options":[{"t":"46","correct":true},{"t":"19","mis":"M2-1-u3-X16"},{"t":"64","mis":"M2-1-u3-X15"}],"explanation":["□ + 72 = 91이니 어떤 수 □ = 91 − 72 = 19예요.","바르게 계산하면 19 + 27 = 46이에요.","19는 어떤 수 — 물음은 바르게 계산한 값이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_c#24','math',2,1,'u3','','g2_1_math_u3_review_c','unit_review','M2-1-u3-C3',4,'mc','auto','수 카드 1, 3, 8, 9를 한 번씩 모두 써서 두 자리 수 두 개를 만들었어요. 두 수의 합이 가장 클 때, 그 합은 얼마인가요?',ARRAY['M2-1-u3-X16']::text[],false,'{"seq":24,"concept":"M2-1-u3-C3","difficulty":4,"kind":"mc","stem":"수 카드 1, 3, 8, 9를 한 번씩 모두 써서 두 자리 수 두 개를 만들었어요. 두 수의 합이 가장 클 때, 그 합은 얼마인가요?","options":[{"t":"174","correct":true},{"t":"129","mis":"M2-1-u3-X16"},{"t":"111","mis":"M2-1-u3-X16"}],"explanation":["합이 크려면 큰 수 9와 8을 십의 자리에 놓아요.","93 + 81 = 174 (91 + 83도 174)예요.","98 + 31 = 129처럼 한 수만 크게 만들면 더 작아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_c#25','math',2,1,'u3','','g2_1_math_u3_review_c','unit_review','M2-1-u3-C6',4,'essay','teacher','42 − 15 + 27을 계산하는 순서를 설명하고, 순서를 바꾸면 안 되는 까닭을 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M2-1-u3-C6","difficulty":4,"kind":"essay","stem":"42 − 15 + 27을 계산하는 순서를 설명하고, 순서를 바꾸면 안 되는 까닭을 써 보세요.","answer_guide":{"answer":"앞에서부터 42 − 15 = 27, 27 + 27 = 54. 15 + 27을 먼저 하면 42 − 42 = 0이 되어 답이 달라진다.","scoring_points":["앞에서부터 계산해 54를 구했는가","순서를 바꾸면 답이 달라짐을 보였는가","「앞에서부터 차례로」를 말로 썼는가"]},"explanation":["42 − 15 = 27, 27 + 27 = 54예요.","15 + 27을 먼저 하면 0이 돼요.","그래서 앞에서부터 차례로 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_d#1','math',2,1,'u3','','g2_1_math_u3_review_d','unit_review','M2-1-u3-C1',1,'mc','auto','57 + 8은 얼마인가요?',ARRAY['M2-1-u3-X01','M2-1-u3-X03']::text[],true,'{"seq":1,"concept":"M2-1-u3-C1","difficulty":1,"kind":"mc","stem":"57 + 8은 얼마인가요?","explanation":["일의 자리 7 + 8 = 15 — 5를 쓰고 10은 십의 자리로 받아올려요.","십의 자리 5 + 1 = 6. 그래서 57 + 8 = 65예요.","받아올림한 1은 십의 자리에서 꼭 더해요 — 빠뜨리면 10이 작아져요."],"variant_rule":{"ar2":{"ask":"value","kind":"a21"}},"options":[{"t":"65","correct":true},{"t":"55","mis":"M2-1-u3-X01"},{"t":"137","mis":"M2-1-u3-X03"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_d#2','math',2,1,'u3','','g2_1_math_u3_review_d','unit_review','M2-1-u3-C2',1,'sa','auto','25 + 36은 얼마인가요?','{}'::text[],true,'{"seq":2,"concept":"M2-1-u3-C2","difficulty":1,"kind":"sa","stem":"25 + 36은 얼마인가요?","explanation":["일의 자리 5 + 6 = 11 — 1을 쓰고 10은 십의 자리로 받아올려요.","십의 자리 2 + 3 + 1 = 6. 그래서 25 + 36 = 61이에요.","받아올림한 1은 십의 자리에서 꼭 더해요 — 빠뜨리면 10이 작아져요."],"variant_rule":{"ar2":{"ask":"value","kind":"a22"}},"answer":["61"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_d#3','math',2,1,'u3','','g2_1_math_u3_review_d','unit_review','M2-1-u3-C3',1,'mc','auto','76 + 38을 세로셈으로 계산하면 얼마인가요?',ARRAY['M2-1-u3-X01','M2-1-u3-X05']::text[],true,'{"seq":3,"concept":"M2-1-u3-C3","difficulty":1,"kind":"mc","stem":"76 + 38을 세로셈으로 계산하면 얼마인가요?","explanation":["일의 자리 6 + 8 = 14 — 4를 쓰고 10은 십의 자리로 받아올려요.","십의 자리 7 + 3 + 1 = 11 — 10이 넘어 백의 자리로 올려요. 그래서 76 + 38 = 114예요.","십의 자리 합이 10을 넘으면 백의 자리에 1을 써요."],"variant_rule":{"ar2":{"ask":"vert","kind":"a22h"}},"options":[{"t":"114","correct":true},{"t":"104","mis":"M2-1-u3-X01"},{"t":"14","mis":"M2-1-u3-X05"}],"asset":{"type":"vert2","top":76,"bottom":38,"op":"+","ans":null}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_d#4','math',2,1,'u3','','g2_1_math_u3_review_d','unit_review','M2-1-u3-C4',1,'mc','auto','43 − 9는 얼마인가요?',ARRAY['M2-1-u3-X07','M2-1-u3-X08']::text[],true,'{"seq":4,"concept":"M2-1-u3-C4","difficulty":1,"kind":"mc","stem":"43 − 9는 얼마인가요?","explanation":["일의 자리 3에서 9를 뺄 수 없어 십의 자리에서 10을 받아내려요 — 13 − 9 = 4.","십의 자리는 4에서 1을 내려 주어 3. 그래서 43 − 9 = 34예요.","9 − 3처럼 거꾸로 빼지 않아요 — 위의 수에서 아래 수를 빼요."],"variant_rule":{"ar2":{"ask":"value","kind":"s21"}},"options":[{"t":"34","correct":true},{"t":"46","mis":"M2-1-u3-X07"},{"t":"44","mis":"M2-1-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_d#5','math',2,1,'u3','','g2_1_math_u3_review_d','unit_review','M2-1-u3-C5',1,'mc','auto','91 − 56을 세로셈으로 계산하면 얼마인가요?',ARRAY['M2-1-u3-X07','M2-1-u3-X10']::text[],true,'{"seq":5,"concept":"M2-1-u3-C5","difficulty":1,"kind":"mc","stem":"91 − 56을 세로셈으로 계산하면 얼마인가요?","explanation":["일의 자리 1에서 6을 뺄 수 없어 십의 자리에서 10을 받아내려요 — 11 − 6 = 5.","십의 자리는 9에서 1을 내려 주어 8, 8 − 5 = 3. 그래서 91 − 56 = 35예요.","6 − 1처럼 거꾸로 빼지 않아요 — 위의 수에서 아래 수를 빼요."],"variant_rule":{"ar2":{"ask":"vert","kind":"s22"}},"options":[{"t":"35","correct":true},{"t":"45","mis":"M2-1-u3-X07"},{"t":"147","mis":"M2-1-u3-X10"}],"asset":{"type":"vert2","top":91,"bottom":56,"op":"-","ans":null}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_d#6','math',2,1,'u3','','g2_1_math_u3_review_d','unit_review','M2-1-u3-C6',1,'mc','auto','45 + 27 − 19에서 먼저 계산할 것은 어느 것인가요?',ARRAY['M2-1-u3-X11']::text[],true,'{"seq":6,"concept":"M2-1-u3-C6","difficulty":1,"kind":"mc","stem":"45 + 27 − 19에서 먼저 계산할 것은 어느 것인가요?","explanation":["세 수의 계산은 앞에서부터 차례로 해요.","먼저 45 + 27 = 72, 그다음 72 − 19 = 53이에요.","순서를 바꾸지 않고 왼쪽부터 두 수씩 계산해요."],"variant_rule":{"ar2":{"ask":"first"}},"options":[{"t":"45 + 27","correct":true},{"t":"27 − 19","mis":"M2-1-u3-X11"},{"t":"45 − 19","mis":"M2-1-u3-X11"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_d#7','math',2,1,'u3','','g2_1_math_u3_review_d','unit_review','M2-1-u3-C7',1,'mc','auto','덧셈식 9 + 8 = 17을 뺄셈식으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-1-u3-X13','M2-1-u3-X14']::text[],true,'{"seq":7,"concept":"M2-1-u3-C7","difficulty":1,"kind":"mc","stem":"덧셈식 9 + 8 = 17을 뺄셈식으로 바르게 나타낸 것은 어느 것인가요?","explanation":["17은 전체, 9와 8은 부분이에요.","전체에서 한 부분을 빼면 다른 부분 — 17 − 9 = 8, 17 − 8 = 9.","뺄셈식은 늘 전체에서 빼요 — 부분끼리 빼지 않아요."],"variant_rule":{"ar2":{"ask":"rel","to":"sub","size":"small"}},"options":[{"t":"17 − 9 = 8","correct":true},{"t":"9 − 8 = 17","mis":"M2-1-u3-X13"},{"t":"8 − 17 = 9","mis":"M2-1-u3-X14"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_d#8','math',2,1,'u3','','g2_1_math_u3_review_d','unit_review','M2-1-u3-C8',1,'mc','auto','□ − 6 = 8에서 □에 알맞은 수는 얼마인가요?',ARRAY['M2-1-u3-X15','M2-1-u3-X01']::text[],true,'{"seq":8,"concept":"M2-1-u3-C8","difficulty":1,"kind":"mc","stem":"□ − 6 = 8에서 □에 알맞은 수는 얼마인가요?","explanation":["□에서 6을 뺐더니 8이 남았어요.","처음 수 □는 8 + 6 = 14예요.","확인 — 14 − 6 = 8."],"variant_rule":{"ar2":{"ask":"box","size":"small"}},"options":[{"t":"14","correct":true},{"t":"2","mis":"M2-1-u3-X15"},{"t":"4","mis":"M2-1-u3-X01"}],"asset":{"type":"bar2","whole":null,"parts":[8,6]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_d#9','math',2,1,'u3','','g2_1_math_u3_review_d','unit_review','M2-1-u3-C1',2,'mc','auto','35 + 9를 계산할 때, 35에 얼마를 더하면 40이 되나요?',ARRAY['M2-1-u3-X04']::text[],true,'{"seq":9,"concept":"M2-1-u3-C1","difficulty":2,"kind":"mc","stem":"35 + 9를 계산할 때, 35에 얼마를 더하면 40이 되나요?","explanation":["35에서 40까지는 5만큼 더 가야 해요.","35 + 5 = 40 — 먼저 몇십을 만들어요.","남은 4를 더하면 40 + 4 = 44예요."],"variant_rule":{"ar2":{"ask":"fill","kind":"a21"}},"options":[{"t":"5","correct":true},{"t":"4","mis":"M2-1-u3-X04"},{"t":"1","mis":"M2-1-u3-X04"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_d#10','math',2,1,'u3','','g2_1_math_u3_review_d','unit_review','M2-1-u3-C3',2,'mc','auto','56 + 17을 세로셈으로 계산할 때, 십의 자리에서 계산할 식은 어느 것인가요?',ARRAY['M2-1-u3-X01','M2-1-u3-X06']::text[],true,'{"seq":10,"concept":"M2-1-u3-C3","difficulty":2,"kind":"mc","stem":"56 + 17을 세로셈으로 계산할 때, 십의 자리에서 계산할 식은 어느 것인가요?","explanation":["일의 자리 6 + 7 = 13 — 10을 십의 자리로 받아올려요.","받아올림한 10은 십의 자리에서는 1이에요. 그래서 십의 자리 식은 5 + 1 + 1이에요.","받아올린 수는 십의 자리에서 「1」로 더해요 — 10을 더하지 않아요."],"variant_rule":{"ar2":{"ask":"carry","kind":"a22"}},"options":[{"t":"5 + 1 + 1","correct":true},{"t":"5 + 1","mis":"M2-1-u3-X01"},{"t":"5 + 1 + 10","mis":"M2-1-u3-X06"}],"asset":{"type":"vert2","top":56,"bottom":17,"op":"+","ans":null}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_d#11','math',2,1,'u3','','g2_1_math_u3_review_d','unit_review','M2-1-u3-C5',2,'mc','auto','83 − 47을 세로셈으로 계산할 때, 일의 자리에서 계산할 식은 어느 것인가요?',ARRAY['M2-1-u3-X07','M2-1-u3-X09']::text[],true,'{"seq":11,"concept":"M2-1-u3-C5","difficulty":2,"kind":"mc","stem":"83 − 47을 세로셈으로 계산할 때, 일의 자리에서 계산할 식은 어느 것인가요?","explanation":["일의 자리 3에서 7을 뺄 수 없어요.","십의 자리에서 10을 받아내리면 일의 자리는 13 — 13 − 7을 계산해요.","7 − 3처럼 아래 수에서 위의 수를 빼지 않아요."],"variant_rule":{"ar2":{"ask":"borrow","kind":"s22"}},"options":[{"t":"13 − 7","correct":true},{"t":"7 − 3","mis":"M2-1-u3-X07"},{"t":"4 − 7","mis":"M2-1-u3-X09"}],"asset":{"type":"vert2","top":83,"bottom":47,"op":"-","ans":null}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_d#12','math',2,1,'u3','','g2_1_math_u3_review_d','unit_review','M2-1-u3-C3',2,'ox','auto','49 + 51 = 100 입니다.',ARRAY['M2-1-u3-X01']::text[],true,'{"seq":12,"concept":"M2-1-u3-C3","difficulty":2,"kind":"ox","stem":"49 + 51 = 100 입니다.","explanation":["일의 자리 9 + 1 = 10 — 0을 쓰고 10은 십의 자리로 받아올려요.","십의 자리 4 + 5 + 1 = 10 — 10이 넘어 백의 자리로 올려요. 그래서 49 + 51 = 100이에요.","십의 자리 합이 10을 넘으면 백의 자리에 1을 써요."],"variant_rule":{"ar2":{"ask":"value","kind":"a22h"}},"answer":"O","mis":"M2-1-u3-X05","reason_options":[{"t":"받아올림한 1을 십의 자리에 더해 계산했으니까","correct":true},{"t":"일의 자리끼리, 십의 자리끼리 더하기만 하면 되니까","mis":"M2-1-u3-X01"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_d#13','math',2,1,'u3','','g2_1_math_u3_review_d','unit_review','M2-1-u3-C6',2,'sa','auto','72 − 45 + 38을 앞에서부터 차례로 계산하면 얼마인가요?','{}'::text[],true,'{"seq":13,"concept":"M2-1-u3-C6","difficulty":2,"kind":"sa","stem":"72 − 45 + 38을 앞에서부터 차례로 계산하면 얼마인가요?","explanation":["① 앞의 두 수부터 — 72 − 45 = 27.","② 27 + 38 = 65예요.","45 + 38을 먼저 계산하면 안 돼요 — 앞에서부터 차례로."],"variant_rule":{"ar2":{"ask":"three"}},"answer":["65"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_d#14','math',2,1,'u3','','g2_1_math_u3_review_d','unit_review','M2-1-u3-C5',2,'mc','auto','62 − 29 = 33을 덧셈으로 확인하는 식은 어느 것인가요?',ARRAY['M2-1-u3-X16','M2-1-u3-X10']::text[],true,'{"seq":14,"concept":"M2-1-u3-C5","difficulty":2,"kind":"mc","stem":"62 − 29 = 33을 덧셈으로 확인하는 식은 어느 것인가요?","explanation":["뺄셈의 답에 뺀 수를 더하면 처음 수가 돼요.","33 + 29 = 62 — 처음 수 62가 나오니 바르게 뺐어요.","처음 수를 더하면 확인이 되지 않아요."],"variant_rule":{"ar2":{"ask":"verify","kind":"s22"}},"options":[{"t":"33 + 29 = 62","correct":true},{"t":"33 + 62 = 95","mis":"M2-1-u3-X16"},{"t":"62 + 29 = 91","mis":"M2-1-u3-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_d#15','math',2,1,'u3','','g2_1_math_u3_review_d','unit_review','M2-1-u3-C5',2,'mc','auto','지우는 색종이 81장을, 펭이는 36장을 모았어요. 지우가 펭이보다 몇 장 더 많이 모았나요?',ARRAY['M2-1-u3-X07','M2-1-u3-X10']::text[],true,'{"seq":15,"concept":"M2-1-u3-C5","difficulty":2,"kind":"mc","stem":"지우는 색종이 81장을, 펭이는 36장을 모았어요. 지우가 펭이보다 몇 장 더 많이 모았나요?","explanation":["일의 자리 1에서 6을 뺄 수 없어 십의 자리에서 10을 받아내려요 — 11 − 6 = 5.","십의 자리는 8에서 1을 내려 주어 7, 7 − 3 = 4. 그래서 81 − 36 = 45예요.","「몇 장 더 많이」는 두 수를 견주는 이야기라 뺄셈이에요 — 45장이에요."],"variant_rule":{"ar2":{"ask":"story","kind":"s22"}},"options":[{"t":"45","correct":true},{"t":"55","mis":"M2-1-u3-X07"},{"t":"117","mis":"M2-1-u3-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_d#16','math',2,1,'u3','','g2_1_math_u3_review_d','unit_review','M2-1-u3-C8',2,'sa','auto','□ − 34 = 29에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":16,"concept":"M2-1-u3-C8","difficulty":2,"kind":"sa","stem":"□ − 34 = 29에서 □에 알맞은 수는 얼마인가요?","explanation":["□에서 34를 뺐더니 29가 남았어요.","처음 수 □는 29 + 34 = 63이에요.","확인 — 63 − 34 = 29."],"variant_rule":{"ar2":{"ask":"box","size":"big"}},"answer":["63"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_d#17','math',2,1,'u3','','g2_1_math_u3_review_d','unit_review','M2-1-u3-C3',3,'sa','auto','다예가 색종이 69장을 가지고 있었는데 54장을 더 받았어요. 색종이는 모두 몇 장인가요?','{}'::text[],true,'{"seq":17,"concept":"M2-1-u3-C3","difficulty":3,"kind":"sa","stem":"다예가 색종이 69장을 가지고 있었는데 54장을 더 받았어요. 색종이는 모두 몇 장인가요?","explanation":["일의 자리 9 + 4 = 13 — 3을 쓰고 10은 십의 자리로 받아올려요.","십의 자리 6 + 5 + 1 = 12 — 10이 넘어 백의 자리로 올려요. 그래서 69 + 54 = 123이에요.","「모두」는 모으는 이야기라 덧셈이에요 — 123장이에요."],"variant_rule":{"ar2":{"ask":"story","kind":"a22h"}},"answer":["123","123장"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_d#18','math',2,1,'u3','','g2_1_math_u3_review_d','unit_review','M2-1-u3-C6',3,'mc','auto','28 + 35 − 47을 앞에서부터 차례로 계산하면 얼마인가요?',ARRAY['M2-1-u3-X12','M2-1-u3-X01']::text[],true,'{"seq":18,"concept":"M2-1-u3-C6","difficulty":3,"kind":"mc","stem":"28 + 35 − 47을 앞에서부터 차례로 계산하면 얼마인가요?","explanation":["① 앞의 두 수부터 — 28 + 35 = 63.","② 63 − 47 = 16이에요.","63에서 멈추지 않고 남은 계산까지 해요."],"variant_rule":{"ar2":{"ask":"three"}},"options":[{"t":"16","correct":true},{"t":"63","mis":"M2-1-u3-X12"},{"t":"110","mis":"M2-1-u3-X12"},{"t":"26","mis":"M2-1-u3-X01"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_d#19','math',2,1,'u3','','g2_1_math_u3_review_d','unit_review','M2-1-u3-C8',3,'mc','auto','서아가 색종이 몇 장을 가지고 있었는데 17장을 친구에게 주었더니 46장이 남았어요. 처음에 있던 색종이의 수를 □로 하여 식을 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-1-u3-X14','M2-1-u3-X10']::text[],true,'{"seq":19,"concept":"M2-1-u3-C8","difficulty":3,"kind":"mc","stem":"서아가 색종이 몇 장을 가지고 있었는데 17장을 친구에게 주었더니 46장이 남았어요. 처음에 있던 색종이의 수를 □로 하여 식을 바르게 나타낸 것은 어느 것인가요?","explanation":["처음 □장에서 17장을 주고 46장이 남았어요.","그래서 식은 □ − 17 = 46 — □는 46 + 17 = 63이에요.","처음 수 □가 빼는 식의 맨 앞에 와요."],"variant_rule":{"ar2":{"ask":"boxmake"}},"options":[{"t":"□ − 17 = 46","correct":true},{"t":"17 − □ = 46","mis":"M2-1-u3-X14"},{"t":"□ + 17 = 46","mis":"M2-1-u3-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_d#20','math',2,1,'u3','','g2_1_math_u3_review_d','unit_review','M2-1-u3-C5',3,'mc','auto','도윤이가 63 − 27을 세로셈으로 계산한 것이에요. 잘못 계산한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M2-1-u3-X08','M2-1-u3-X10']::text[],false,'{"seq":20,"concept":"M2-1-u3-C5","difficulty":3,"kind":"mc","stem":"도윤이가 63 − 27을 세로셈으로 계산한 것이에요. 잘못 계산한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"일의 자리에서 7 − 3으로 거꾸로 뺐어요.","correct":true},{"t":"받아내림하고 십의 자리를 줄이지 않았어요.","mis":"M2-1-u3-X08"},{"t":"두 수를 더했어요.","mis":"M2-1-u3-X10"}],"explanation":["일의 자리 3에서 7을 뺄 수 없어 13 − 7 = 6이에요.","십의 자리는 5 − 2 = 3 — 바른 답은 36이에요.","도윤이는 7 − 3 = 4로 거꾸로 빼서 44라고 썼어요."],"asset":{"type":"vert2","top":63,"bottom":27,"op":"-","ans":44}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_d#21','math',2,1,'u3','','g2_1_math_u3_review_d','unit_review','M2-1-u3-C7',3,'mc','auto','뺄셈식 73 − 54 = 19를 덧셈식으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-1-u3-X14']::text[],true,'{"seq":21,"concept":"M2-1-u3-C7","difficulty":3,"kind":"mc","stem":"뺄셈식 73 − 54 = 19를 덧셈식으로 바르게 나타낸 것은 어느 것인가요?","explanation":["73은 전체, 54와 19는 부분이에요.","두 부분을 모으면 전체 — 54 + 19 = 73.","덧셈식에서 전체는 = 오른쪽에 와요."],"variant_rule":{"ar2":{"ask":"rel","to":"add","size":"big"}},"options":[{"t":"19 + 54 = 73","correct":true},{"t":"73 + 54 = 19","mis":"M2-1-u3-X14"},{"t":"73 + 19 = 54","mis":"M2-1-u3-X14"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_d#22','math',2,1,'u3','','g2_1_math_u3_review_d','unit_review','M2-1-u3-C6',3,'sa','auto','색종이 28장에 36장을 더 받고, 그중 19장을 썼어요. 남은 색종이는 몇 장인가요?','{}'::text[],false,'{"seq":22,"concept":"M2-1-u3-C6","difficulty":3,"kind":"sa","stem":"색종이 28장에 36장을 더 받고, 그중 19장을 썼어요. 남은 색종이는 몇 장인가요?","answer":["45","45장"],"explanation":["식은 28 + 36 − 19예요.","28 + 36 = 64, 64 − 19 = 45예요.","받은 것은 더하고 쓴 것은 빼요 — 앞에서부터."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_d#23','math',2,1,'u3','','g2_1_math_u3_review_d','unit_review','M2-1-u3-C8',4,'mc','auto','어떤 수에서 18을 빼야 할 것을 잘못하여 81을 뺐더니 12가 되었어요. 바르게 계산하면 얼마인가요?',ARRAY['M2-1-u3-X16','M2-1-u3-X15']::text[],false,'{"seq":23,"concept":"M2-1-u3-C8","difficulty":4,"kind":"mc","stem":"어떤 수에서 18을 빼야 할 것을 잘못하여 81을 뺐더니 12가 되었어요. 바르게 계산하면 얼마인가요?","options":[{"t":"75","correct":true},{"t":"93","mis":"M2-1-u3-X16"},{"t":"30","mis":"M2-1-u3-X15"}],"explanation":["□ − 81 = 12이니 어떤 수 □ = 12 + 81 = 93이에요.","바르게 계산하면 93 − 18 = 75예요.","93은 어떤 수 — 물음은 바르게 계산한 값이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_d#24','math',2,1,'u3','','g2_1_math_u3_review_d','unit_review','M2-1-u3-C5',4,'mc','auto','수 카드 2, 7, 8을 두 장 골라 두 자리 수를 만들어요. 가장 큰 수에서 두 번째로 작은 수를 빼면 얼마인가요?',ARRAY['M2-1-u3-X07','M2-1-u3-X16']::text[],false,'{"seq":24,"concept":"M2-1-u3-C5","difficulty":4,"kind":"mc","stem":"수 카드 2, 7, 8을 두 장 골라 두 자리 수를 만들어요. 가장 큰 수에서 두 번째로 작은 수를 빼면 얼마인가요?","options":[{"t":"59","correct":true},{"t":"61","mis":"M2-1-u3-X07"},{"t":"60","mis":"M2-1-u3-X16"}],"explanation":["가장 큰 수는 87, 가장 작은 수는 27, 두 번째로 작은 수는 28이에요.","87 − 28 = 59예요.","60은 가장 작은 수 27을 뺀 값이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u3_review_d#25','math',2,1,'u3','','g2_1_math_u3_review_d','unit_review','M2-1-u3-C8',4,'essay','teacher','7 + □ = 15에서 □를 구하는 방법을 덧셈과 뺄셈의 관계로 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M2-1-u3-C8","difficulty":4,"kind":"essay","stem":"7 + □ = 15에서 □를 구하는 방법을 덧셈과 뺄셈의 관계로 설명해 보세요.","answer_guide":{"answer":"15는 전체, 7과 □는 부분이다. 전체에서 아는 부분을 빼면 다른 부분이므로 □ = 15 − 7 = 8. 확인: 7 + 8 = 15.","scoring_points":["15를 전체, 7과 □를 부분으로 보았는가","15 − 7 = 8로 □를 구했는가","구한 값을 식에 넣어 확인했는가"]},"explanation":["15가 전체, 7과 □가 부분이에요.","□ = 15 − 7 = 8이에요.","7 + 8 = 15로 확인해요."],"asset":{"type":"bar2","whole":15,"parts":[7,null]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
